private func debugArgumentValue(forKey key: String) -> String? {
    let arguments = ProcessInfo.processInfo.arguments
    let candidateFlags = [
        "-\(key)",
        "--\(key)",
        key
    ]

    for flag in candidateFlags {
        guard let index = arguments.firstIndex(of: flag),
              arguments.indices.contains(arguments.index(after: index)) else {
            continue
        }
        return arguments[arguments.index(after: index)]
    }

    return nil
}

private func debugStringValue(forKey key: String) -> String? {
    if let value = debugArgumentValue(forKey: key), !value.isEmpty {
        return value
    }
    return UserDefaults.standard.string(forKey: key)
}

private func debugOneShotStringValue(forKey key: String) -> String? {
    if let value = debugArgumentValue(forKey: key), !value.isEmpty {
        return value
    }

    let defaults = UserDefaults.standard
    guard let value = defaults.string(forKey: key), !value.isEmpty else {
        return nil
    }
    defaults.removeObject(forKey: key)
    return value
}

private func debugDoubleValue(forKey key: String) -> Double {
    if let value = debugArgumentValue(forKey: key),
       let parsed = Double(value) {
        return parsed
    }
    return UserDefaults.standard.double(forKey: key)
}

private func debugOneShotDoubleValue(forKey key: String) -> Double? {
    if let value = debugArgumentValue(forKey: key),
       let parsed = Double(value) {
        return parsed
    }

    let defaults = UserDefaults.standard
    guard let value = defaults.object(forKey: key) else {
        return nil
    }

    let parsed: Double?
    if let number = value as? NSNumber {
        parsed = number.doubleValue
    } else if let string = value as? String {
        parsed = Double(string)
    } else {
        parsed = nil
    }

    defaults.removeObject(forKey: key)
    return parsed
}

private func debugArgumentDoubleValue(forKey key: String) -> Double? {
    guard let value = debugArgumentValue(forKey: key),
          let parsed = Double(value) else {
        return nil
    }
    return parsed
}

private func debugIntArgumentValue(forKey key: String) -> Int? {
    guard let value = debugArgumentValue(forKey: key),
          let parsed = Int(value) else {
        return nil
    }
    return parsed
}

private func debugBoolArgumentValue(forKey key: String) -> Bool? {
    guard let rawValue = debugArgumentValue(forKey: key)?
        .trimmingCharacters(in: .whitespacesAndNewlines)
        .lowercased() else {
        return nil
    }

    switch rawValue {
    case "1", "true", "yes", "on":
        return true
    case "0", "false", "no", "off":
        return false
    default:
        return nil
    }
}

private func applyDebugPreferenceOverridesIfNeeded() {
    if let maxHistorySize = debugIntArgumentValue(forKey: "debugMaxHistorySize") {
        UserDefaults.standard.set(maxHistorySize, forKey: CMPrefMaxHistorySizeKey)
    }
    if let saveHistoryOnQuit = debugBoolArgumentValue(forKey: "debugSaveHistoryOnQuit") {
        UserDefaults.standard.set(saveHistoryOnQuit, forKey: CMPrefSaveHistoryOnQuitKey)
    }
    if let enableAction = debugBoolArgumentValue(forKey: "debugEnableAction") {
        UserDefaults.standard.set(enableAction, forKey: CMPrefEnableActionKey)
    }
    if let invokeActionImmediately = debugBoolArgumentValue(forKey: "debugInvokeActionImmediately") {
        UserDefaults.standard.set(invokeActionImmediately, forKey: CMPrefInvokeActionImmediatelyKey)
    }
}

private func debugHasSupportDirectoryOverride() -> Bool {
    let environment = ProcessInfo.processInfo.environment
    let overridePath = debugArgumentValue(forKey: CMDebugSupportDirectoryDefaultsKey)
        ?? environment[CMDebugSupportDirectoryEnvironmentKey]
    return overridePath?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
}

