        "debugWriteHistoryFailureAlertsReportAfterLaunchDelay",
        "debugWriteDefaultsShapeReportAfterLaunchDelay",
        "debugRunClipStoreRoundTripAfterLaunchDelay",
        "debugRunSnippetStoreRoundTripAfterLaunchDelay",
        "debugRunSnippetSelectionAfterLaunchDelay",
        "debugRunJavaScriptActionAfterLaunchDelay",
        "debugRunActionMenuSelectionAfterLaunchDelay",
        "debugShowVisibleActionMenuAfterLaunchDelay",
        "debugRunPasteboardRoundTripAfterLaunchDelay",
        "debugDumpDefaultsAfterLaunchDelay",
        "debugShowPreferencesAfterLaunchDelay",
        "debugShowSnippetEditorAfterLaunchDelay",
        "debugShowPopulatedSnippetEditorAfterLaunchDelay"
    ]

    return harnessDelayKeys.contains {
        debugDoubleValue(forKey: $0) > 0
    }
}
#endif

private func CMRuntimePrefersJapanese() -> Bool {
    if let languages = UserDefaults.standard.array(forKey: "AppleLanguages") as? [String],
       let firstLanguage = languages.first,
       firstLanguage.hasPrefix("ja") {
        return true
    }

    if let firstPreferredLanguage = Locale.preferredLanguages.first,
       firstPreferredLanguage.hasPrefix("ja") {
        return true
    }

    return Bundle.main.preferredLocalizations.first?.hasPrefix("ja") == true
}

private let CMPrefStoreTypesKey = "storeTypes"
private let CMPrefExcludeAppsKey = "excludeApps"
private let kCMBundleIdentifierKey = "bundleIdentifier"
private let kCMNameKey = "name"

private extension NSPasteboard.PasteboardType {
    static let clipMenuFilenames = NSPasteboard.PasteboardType("NSFilenamesPboardType")
    static let clipMenuURL = NSPasteboard.PasteboardType("NSURLPboardType")
    static let clipMenuPICT = NSPasteboard.PasteboardType("Apple PICT pasteboard type")
    static let clipMenuFileURL = NSPasteboard.PasteboardType("public.file-url")
    static let clipMenuPublicURL = NSPasteboard.PasteboardType("public.url")
}

