extension NSEvent.ModifierFlags {
    var carbonHotKeyModifiers: Int {
        var modifiers = 0
        if contains(.command) {
            modifiers |= cmdKey
        }
        if contains(.option) {
            modifiers |= optionKey
        }
        if contains(.control) {
            modifiers |= controlKey
        }
        if contains(.shift) {
            modifiers |= shiftKey
        }
        return modifiers
    }

    var normalizedShortcutFlags: NSEvent.ModifierFlags {
        intersection([.command, .option, .control, .shift])
    }
}

struct ClipItem: Codable, Identifiable, Equatable {
    let id: UUID
    var types: [String]
    var createdAt: Date
    var lastUsedAt: Date
    var text: String
    var rtfData: Data?
    var pdfData: Data?
    var filenames: [String]?
    var urls: [String]?
    var imageData: Data?

    private enum CodingKeys: String, CodingKey {
        case id
        case types
        case createdAt
        case lastUsedAt
        case text
        case rtfData
        case pdfData
        case filenames
        case urls
        case imageData
    }

    init(id: UUID = UUID(), text: String, createdAt: Date = Date(), lastUsedAt: Date = Date()) {
        self.id = id
        self.types = [NSPasteboard.PasteboardType.string.rawValue]
        self.text = text
        self.createdAt = createdAt
        self.lastUsedAt = lastUsedAt
    }

    init(
        id: UUID = UUID(),
        types: [String],
        createdAt: Date = Date(),
        lastUsedAt: Date = Date(),
        text: String = "",
        rtfData: Data? = nil,
        pdfData: Data? = nil,
        filenames: [String]? = nil,
        urls: [String]? = nil,
        imageData: Data? = nil
    ) {
        self.id = id
        self.types = types.map(Self.normalizedPasteboardType)
        self.createdAt = createdAt
        self.lastUsedAt = lastUsedAt
        self.text = text
        self.rtfData = rtfData
        self.pdfData = pdfData
        self.filenames = filenames
        self.urls = urls
        self.imageData = imageData
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        id = try container.decodeIfPresent(UUID.self, forKey: .id) ?? UUID()
        createdAt = try container.decodeIfPresent(Date.self, forKey: .createdAt) ?? Date()
        lastUsedAt = try container.decodeIfPresent(Date.self, forKey: .lastUsedAt) ?? createdAt
        text = try container.decodeIfPresent(String.self, forKey: .text) ?? ""
        rtfData = try container.decodeIfPresent(Data.self, forKey: .rtfData)
        pdfData = try container.decodeIfPresent(Data.self, forKey: .pdfData)
        filenames = try container.decodeIfPresent([String].self, forKey: .filenames)
        urls = try container.decodeIfPresent([String].self, forKey: .urls)
        imageData = try container.decodeIfPresent(Data.self, forKey: .imageData)

        if let decodedTypes = try container.decodeIfPresent([String].self, forKey: .types), !decodedTypes.isEmpty {
            types = decodedTypes.map(Self.normalizedPasteboardType)
        } else if !text.isEmpty {
            types = [NSPasteboard.PasteboardType.string.rawValue]
        } else {
            var inferred: [NSPasteboard.PasteboardType] = []
            if rtfData != nil {
                inferred.append(.rtf)
            }
            if pdfData != nil {
                inferred.append(.pdf)
            }
            if filenames != nil {
                inferred.append(.clipMenuFilenames)
            }
            if urls != nil {
                inferred.append(.clipMenuURL)
            }
            if imageData != nil {
                inferred.append(.tiff)
            }
            types = inferred.map(\.rawValue)
        }
    }

    var primaryPasteboardType: NSPasteboard.PasteboardType? {
        types.first.map { NSPasteboard.PasteboardType($0) }
    }

    var duplicateKey: String {
        var parts = [types.joined()]
        if let imageData {
            parts.append("image-length:\(imageData.count)")
        }
        if let filenames {
            parts.append("filenames:\(filenames.sorted().joined(separator: "\u{1f}"))")
        } else if let urls {
            parts.append("url:\(urls.sorted().joined(separator: "\u{1f}"))")
        } else if let pdfData {
            parts.append("pdf-length:\(pdfData.count)")
        } else {
            parts.append("text:\(text)")
        }
        if let rtfData {
            parts.append("rtf-length:\(rtfData.count)")
        }
        return parts.joined(separator: "\u{1e}")
    }

    var titleSource: String {
        if !text.isEmpty {
            return text
        }
        if let filenames, !filenames.isEmpty {
            return filenames.joined(separator: "\n")
        }
        if let urls, !urls.isEmpty {
            return urls.joined(separator: "\n")
        }
        switch primaryPasteboardType {
        case .pdf:
            return "(PDF)"
        case .tiff, .clipMenuPICT:
            return "(Image)"
        case .clipMenuFilenames:
            return "(Filenames)"
        default:
            return ""
        }
    }

    var tooltipSource: String {
        text
    }

    var image: NSImage? {
        guard let imageData else { return nil }
        return NSImage(data: imageData)
    }

    var filePathsText: String? {
        filenames?.joined(separator: "\n")
    }

    var hasStringPasteboardType: Bool {
        types.contains(NSPasteboard.PasteboardType.string.rawValue)
    }

    var hasTextContent: Bool {
        !text.isEmpty
    }

    var hfsFilePathsText: String? {
        guard let filenames else { return nil }
        let paths = filenames.compactMap { filename -> String? in
            Self.hfsPath(forPOSIXPath: filename)
        }
        return paths.joined(separator: "\n")
    }

    private static func hfsPath(forPOSIXPath path: String) -> String? {
        let url = URL(fileURLWithPath: path) as CFURL
        guard let hfsPathStyle = CFURLPathStyle(rawValue: 1) else { return nil }
        return CFURLCopyFileSystemPath(url, hfsPathStyle) as String?
    }

    static func fromPasteboard(_ pasteboard: NSPasteboard) -> ClipItem? {
        let supportedTypes = pasteboard.types ?? []
        let storeTypes = normalizedStoreTypes(from: UserDefaults.standard.dictionary(forKey: CMPrefStoreTypesKey))
        var capturedTypes: [NSPasteboard.PasteboardType] = []

        func shouldStore(_ type: NSPasteboard.PasteboardType) -> Bool {
            guard let name = storeTypeName(for: type) else { return false }
            return storeTypes[name] == true
        }

        for type in supportedTypes where shouldStore(type) {
            let canonicalType = canonicalStoredType(for: type)
            if canonicalType == .tiff || canonicalType == .clipMenuPICT {
                if !capturedTypes.contains(.tiff) {
                    capturedTypes.append(.tiff)
                }
            } else if availablePasteboardTypes.contains(canonicalType), !capturedTypes.contains(canonicalType) {
                capturedTypes.append(canonicalType)
            }
        }

        guard !capturedTypes.isEmpty else { return nil }

        var text = ""
        var rtfData: Data?
        var pdfData: Data?
        var filenames: [String]?
        var urls: [String]?
        var imageData: Data?

        for type in capturedTypes {
            switch type {
            case .string:
                text = pasteboard.string(forType: .string) ?? ""
            case .rtfd:
                rtfData = pasteboard.data(forType: .rtfd)
            case .rtf:
                if rtfData == nil {
                    rtfData = pasteboard.data(forType: .rtf)
                }
            case .pdf:
                pdfData = pasteboard.data(forType: .pdf)
            case .clipMenuFilenames:
                filenames = filePaths(from: pasteboard)
            case .clipMenuURL:
                urls = Self.urls(from: pasteboard)
            case .tiff, .clipMenuPICT:
                if let image = NSImage(pasteboard: pasteboard) {
                    imageData = image.tiffRepresentation
                } else {
                    imageData = pasteboard.data(forType: .tiff)
                }
            default:
                break
            }
        }
        if text.isEmpty,
           capturedTypes.contains(where: Self.shouldCaptureStringFallback(for:)),
           let fallbackText = pasteboard.string(forType: .string) {
            text = fallbackText
        }
        guard hasCapturedPayload(
            text: text,
            rtfData: rtfData,
            pdfData: pdfData,
            filenames: filenames,
            urls: urls,
            imageData: imageData
        ) else {
            return nil
        }

        return ClipItem(
            types: capturedTypes.map(\.rawValue),
            text: text,
            rtfData: rtfData,
            pdfData: pdfData,
            filenames: filenames,
            urls: urls,
            imageData: imageData
        )
    }

    private static func hasCapturedPayload(
        text: String,
        rtfData: Data?,
        pdfData: Data?,
        filenames: [String]?,
        urls: [String]?,
        imageData: Data?
    ) -> Bool {
        if !text.isEmpty { return true }
        if rtfData?.isEmpty == false { return true }
        if pdfData?.isEmpty == false { return true }
        if filenames?.isEmpty == false { return true }
        if urls?.isEmpty == false { return true }
        if imageData?.isEmpty == false { return true }
        return false
    }

    private static func shouldCaptureStringFallback(for type: NSPasteboard.PasteboardType) -> Bool {
        switch type {
        case .rtf, .rtfd, .clipMenuURL:
            return true
        default:
            return false
        }
    }

    static func normalizedPasteboardType(_ rawValue: String) -> String {
        switch rawValue {
        case "NSStringPboardType":
            return NSPasteboard.PasteboardType.string.rawValue
        case "NSRTFPboardType":
            return NSPasteboard.PasteboardType.rtf.rawValue
        case "NeXT Rich Text Format v1.0 pasteboard type":
            return NSPasteboard.PasteboardType.rtf.rawValue
        case "NSRTFDPboardType":
            return NSPasteboard.PasteboardType.rtfd.rawValue
        case "NeXT RTFD pasteboard type":
            return NSPasteboard.PasteboardType.rtfd.rawValue
        case "NSPDFPboardType":
            return NSPasteboard.PasteboardType.pdf.rawValue
        case "NSTIFFPboardType":
            return NSPasteboard.PasteboardType.tiff.rawValue
        case "NeXT TIFF v4.0 pasteboard type":
            return NSPasteboard.PasteboardType.tiff.rawValue
        case "NSFilenamesPboardType":
            return NSPasteboard.PasteboardType.clipMenuFilenames.rawValue
        case "NSURLPboardType":
            return NSPasteboard.PasteboardType.clipMenuURL.rawValue
        case "Apple URL pasteboard type":
            return NSPasteboard.PasteboardType.clipMenuURL.rawValue
        case "public.file-url":
            return NSPasteboard.PasteboardType.clipMenuFilenames.rawValue
        case "public.url":
            return NSPasteboard.PasteboardType.clipMenuURL.rawValue
        case "NSPICTPboardType":
            return NSPasteboard.PasteboardType.tiff.rawValue
        case NSPasteboard.PasteboardType.clipMenuPICT.rawValue:
            return NSPasteboard.PasteboardType.tiff.rawValue
        default:
            return rawValue
        }
    }

    @discardableResult
    func write(to pasteboard: NSPasteboard) -> Int {
        let originalPasteboardTypes = types.map { NSPasteboard.PasteboardType($0) }
        var pasteboardTypes = originalPasteboardTypes
        let shouldWriteStringFallback = !text.isEmpty
            && !originalPasteboardTypes.contains(.string)
            && originalPasteboardTypes.contains(where: Self.shouldCaptureStringFallback(for:))
        if shouldWriteStringFallback {
            pasteboardTypes.append(.string)
        }
        pasteboard.clearContents()
        let ownershipGeneration = pasteboard.declareTypes(pasteboardTypes, owner: nil)

        for type in pasteboardTypes {
            switch type {
            case .string:
                pasteboard.setString(text, forType: .string)
            case .rtfd:
                if let rtfData {
                    pasteboard.setData(rtfData, forType: .rtfd)
                }
            case .rtf:
                if let rtfData {
                    pasteboard.setData(rtfData, forType: .rtf)
                }
            case .pdf:
                if let pdfData {
                    let representation = NSPDFImageRep(data: pdfData)?.pdfRepresentation ?? pdfData
                    pasteboard.setData(representation, forType: .pdf)
                }
            case .clipMenuFilenames:
                if let filenames {
                    pasteboard.setPropertyList(filenames, forType: .clipMenuFilenames)
                }
            case .clipMenuURL:
                if let urls {
                    pasteboard.setPropertyList(urls, forType: .clipMenuURL)
                }
            case .tiff, .clipMenuPICT:
                if let imageData {
                    pasteboard.setData(imageData, forType: .tiff)
                }
            default:
                break
            }
        }
        return ownershipGeneration
    }

    static let availablePasteboardTypes: [NSPasteboard.PasteboardType] = [
        .string,
        .rtf,
        .rtfd,
        .pdf,
        .clipMenuFilenames,
        .clipMenuURL,
        .tiff,
        .clipMenuPICT
    ]

    static func defaultStoreTypes() -> [String: Bool] {
        Dictionary(uniqueKeysWithValues: availableTypeNames.map { ($0, true) })
    }

    private static func normalizedStoreTypes(from rawStoreTypes: [String: Any]?) -> [String: Bool] {
        var storeTypes = defaultStoreTypes()
        guard let rawStoreTypes else { return storeTypes }

        for (key, value) in rawStoreTypes {
            guard let storeType = storeTypeName(forStoreTypeKey: key),
                  let enabled = storeTypeBoolValue(value) else {
                continue
            }
            storeTypes[storeType] = enabled
        }

        return storeTypes
    }

    private static func storeTypeBoolValue(_ value: Any) -> Bool? {
        if let bool = value as? Bool {
            return bool
        }
        if let number = value as? NSNumber {
            return number.boolValue
        }
        return nil
    }

    private static let availableTypeNames = [
        "String",
        "RTF",
        "RTFD",
        "PDF",
        "Filenames",
        "URL",
        "TIFF",
        "PICT"
    ]

    private static func storeTypeName(for type: NSPasteboard.PasteboardType) -> String? {
        switch type {
        case .string:
            return "String"
        case .rtf:
            return "RTF"
        case .rtfd:
            return "RTFD"
        case .pdf:
            return "PDF"
        case .clipMenuFilenames:
            return "Filenames"
        case .clipMenuFileURL:
            return "Filenames"
        case .clipMenuURL:
            return "URL"
        case .clipMenuPublicURL:
            return "URL"
        case .tiff:
            return "TIFF"
        case .clipMenuPICT:
            return "PICT"
        default:
            return nil
        }
    }

    private static func storeTypeName(forStoreTypeKey key: String) -> String? {
        if availableTypeNames.contains(key) {
            return key
        }
        switch key {
        case "NSStringPboardType":
            return "String"
        case "NSRTFPboardType":
            return "RTF"
        case "NSRTFDPboardType":
            return "RTFD"
        case "NSPDFPboardType":
            return "PDF"
        case "NSFilenamesPboardType":
            return "Filenames"
        case "NSURLPboardType":
            return "URL"
        case "NSTIFFPboardType":
            return "TIFF"
        case "NSPICTPboardType":
            return "PICT"
        default:
            break
        }
        return storeTypeName(for: NSPasteboard.PasteboardType(key))
    }

    private static func canonicalStoredType(for type: NSPasteboard.PasteboardType) -> NSPasteboard.PasteboardType {
        switch type {
        case .clipMenuFileURL:
            return .clipMenuFilenames
        case .clipMenuPublicURL:
            return .clipMenuURL
        case .clipMenuPICT:
            return .tiff
        default:
            return type
        }
    }

    private static func filePaths(from pasteboard: NSPasteboard) -> [String]? {
        if let filenames = pasteboard.propertyList(forType: .clipMenuFilenames) as? [String], !filenames.isEmpty {
            return filenames
        }

        if let fileURLString = pasteboard.string(forType: .clipMenuFileURL),
           let url = URL(string: fileURLString),
           url.isFileURL {
            return [url.path]
        }

        let fileURLReadingOptions: [NSPasteboard.ReadingOptionKey: Any] = [
            .urlReadingFileURLsOnly: true
        ]
        let fileURLs = pasteboard.readObjects(forClasses: [NSURL.self], options: fileURLReadingOptions)?
            .compactMap { object -> String? in
                guard let url = object as? URL, url.isFileURL else { return nil }
                return url.path
            } ?? []
        if !fileURLs.isEmpty {
            return fileURLs
        }

        return nil
    }

    private static func urls(from pasteboard: NSPasteboard) -> [String]? {
        if let urls = pasteboard.propertyList(forType: .clipMenuURL) as? [String], !urls.isEmpty {
            return urls
        }
        if let url = pasteboard.propertyList(forType: .clipMenuURL) as? String, !url.isEmpty {
            return [url]
        }
        if let url = pasteboard.string(forType: .clipMenuURL), !url.isEmpty {
            return [url]
        }
        if let url = pasteboard.string(forType: .clipMenuPublicURL), !url.isEmpty {
            return [url]
        }

        let urlObjects = pasteboard.readObjects(forClasses: [NSURL.self], options: nil)?
            .compactMap { object -> String? in
                guard let url = object as? URL, !url.isFileURL else { return nil }
                return url.absoluteString
            } ?? []
        if !urlObjects.isEmpty {
            return urlObjects
        }

        return nil
    }
}

@objc(CMScriptableActionClip)
final class ScriptableActionClip: NSObject {
    private(set) var clip: ClipItem

    var stringValue: String {
        clip.text
    }

    init(clip: ClipItem) {
        self.clip = clip
        super.init()
    }

    func setStringValue(_ value: String) {
        clip.text = value
        if !clip.types.contains(NSPasteboard.PasteboardType.string.rawValue) {
            clip.types.insert(NSPasteboard.PasteboardType.string.rawValue, at: 0)
        }
    }

    func setStringAttributes(_ attributes: JSValue) {
        changeStringAttributes(attributes, replaceExisting: true)
    }

    func addStringAttributes(_ attributes: JSValue) {
        changeStringAttributes(attributes, replaceExisting: false)
    }

    private func changeStringAttributes(_ attributes: JSValue, replaceExisting: Bool) {
        guard !clip.text.isEmpty else { return }

        var types = clip.types
        let containsRTFD = types.contains(NSPasteboard.PasteboardType.rtfd.rawValue)
        let attributedString: NSMutableAttributedString

        if let rtfData = clip.rtfData {
            if containsRTFD, let existing = NSAttributedString(rtfd: rtfData, documentAttributes: nil) {
                attributedString = NSMutableAttributedString(attributedString: existing)
            } else if let existing = NSAttributedString(rtf: rtfData, documentAttributes: nil) {
                attributedString = NSMutableAttributedString(attributedString: existing)
            } else {
                attributedString = NSMutableAttributedString(string: clip.text)
            }
        } else {
            attributedString = NSMutableAttributedString(string: clip.text)
            if let rtfIndex = types.firstIndex(of: NSPasteboard.PasteboardType.rtf.rawValue) {
                types.remove(at: rtfIndex)
            }
            types.insert(NSPasteboard.PasteboardType.rtf.rawValue, at: 0)
        }

        let range = NSRange(location: 0, length: attributedString.length)
        guard range.length > 0 else { return }

        var newAttributes: [NSAttributedString.Key: Any] = [:]
        if let foreground = color(from: attributes.objectForKeyedSubscript("color")?.objectForKeyedSubscript("foreground")) {
            newAttributes[.foregroundColor] = foreground
        }
        if let background = color(from: attributes.objectForKeyedSubscript("color")?.objectForKeyedSubscript("background")) {
            newAttributes[.backgroundColor] = background
        }
        if let font = font(from: attributes.objectForKeyedSubscript("font")) {
            newAttributes[.font] = font
        }
        if let underline = underlineStyle(from: attributes.objectForKeyedSubscript("underline")) {
            newAttributes[.underlineStyle] = underline
        }

        guard !newAttributes.isEmpty else { return }

        attributedString.beginEditing()
        if replaceExisting {
            attributedString.setAttributes(newAttributes, range: range)
        } else {
            attributedString.addAttributes(newAttributes, range: range)
        }
        attributedString.fixAttributes(in: range)
        attributedString.endEditing()

        clip.types = types
        clip.rtfData = containsRTFD
            ? attributedString.rtfd(from: range, documentAttributes: [:])
            : attributedString.rtf(from: range, documentAttributes: [:])
    }

    private func color(from value: JSValue?) -> NSColor? {
        guard let rawValue = value?.toString(),
              !rawValue.isEmpty else { return nil }
        let lowercased = rawValue.lowercased()

        if let named = Self.namedColors[lowercased] {
            return Self.color(hexValue: named, hasAlpha: false)
        }

        let cssString = lowercased.trimmingCharacters(in: .whitespaces)
        if cssString.hasPrefix("rgb") {
            let components = cssString
                .split(separator: "(", maxSplits: 1)
                .last?
                .split(separator: ")", maxSplits: 1)
                .first?
                .split { $0 == "," || $0 == " " }
                .compactMap { Double($0) } ?? []
            if components.count >= 3 {
                let alpha = components.count >= 4 ? components[3] : 1.0
                return NSColor(
                    calibratedRed: components[0] / 255.0,
                    green: components[1] / 255.0,
                    blue: components[2] / 255.0,
                    alpha: alpha
                )
            }
        }

        let hexDigits = lowercased
            .drop { !$0.isHexDigit }
            .prefix { $0.isHexDigit }
        guard hexDigits.count >= 6,
              let value = UInt64(hexDigits, radix: 16) else {
            return nil
        }

        return Self.color(hexValue: value, hasAlpha: hexDigits.count == 8)
    }

    private static func color(hexValue value: UInt64, hasAlpha: Bool) -> NSColor {
        let shifted = hasAlpha ? value >> 8 : value
        let alpha = hasAlpha ? CGFloat(value & 0xff) / 255.0 : 1.0
        return NSColor(
            calibratedRed: CGFloat((shifted >> 16) & 0xff) / 255.0,
            green: CGFloat((shifted >> 8) & 0xff) / 255.0,
            blue: CGFloat(shifted & 0xff) / 255.0,
            alpha: alpha
        )
    }

    private func font(from value: JSValue?) -> NSFont? {
        guard let fontObject = value,
              let name = fontObject.objectForKeyedSubscript("name")?.toString(),
              !name.isEmpty else {
            return nil
        }
        let size = CGFloat(fontObject.objectForKeyedSubscript("size")?.toDouble() ?? 0)
        guard size > 0 else { return nil }
        return NSFont(name: name, size: size)
    }

    private func underlineStyle(from value: JSValue?) -> NSNumber? {
        guard let underlineObject = value else { return nil }
        let styleName = underlineObject.objectForKeyedSubscript("style")?.toString()?.lowercased() ?? "none"
        let patternName = underlineObject.objectForKeyedSubscript("pattern")?.toString()?.lowercased() ?? "solid"
        let byWord = underlineObject.objectForKeyedSubscript("byWord")?.toBool() == true

        let style: NSUnderlineStyle = [
            "none": [],
            "single": .single,
            "thick": .thick,
            "double": .double
        ][styleName] ?? []

        let pattern: NSUnderlineStyle = [
            "solid": [],
            "dot": .patternDot,
            "dash": .patternDash,
            "dashdot": .patternDashDot,
            "dashdotdot": .patternDashDotDot
        ][patternName] ?? []

        var rawValue = style.rawValue | pattern.rawValue
        if byWord {
            rawValue |= NSUnderlineStyle.byWord.rawValue
        }
        return NSNumber(value: rawValue)
    }

