        coder.encode(urls, forKey: "Apple URL pasteboard type")
        coder.encode(imageData, forKey: "NSPICTPboardType")
    }

    static func archivedData(for clips: [DebugLegacyArchiveClip]) throws -> Data {
        let archiver = NSKeyedArchiver(requiringSecureCoding: false)
        archiver.setClassName("Clip", for: DebugLegacyArchiveClip.self)
        archiver.encode(clips, forKey: NSKeyedArchiveRootObjectKey)
        archiver.finishEncoding()
        return archiver.encodedData
    }
