        finishPasteActivity(reason: "deinit")
        removePopupNumericKeyEventTap()
    }

    func applicationWillFinishLaunching(_ notification: Notification) {
        if NSApp.mainMenu?.items.isEmpty != false {
            installMainMenu()
        }
    }

    func applicationDidFinishLaunching(_ notification: Notification) {
        let diagnosticVersion = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "unknown"
        CMTraceMenuPaste("launch version=\(diagnosticVersion) ax=\(AXIsProcessTrusted()) post=\(CGPreflightPostEventAccess()) appClass=\(NSStringFromClass(type(of: NSApp!)))")
        configureStatusItem()
#if DEBUG
        applyDebugPreferenceOverridesIfNeeded()
        writeDebugPasteAutomationReadinessForUITestingIfNeeded()
#endif
#if TESTING
        if ProcessInfo.processInfo.environment["CLIPMENU_EXERCISE_SWIFTUI_BODIES"] == "1" {
            _ = CMExerciseSwiftUIViewBodiesForTesting()
            _ = debugExerciseAppControllerSurfacesForTesting()
        }
#endif
        clipsStore.load()
        rebuildMenu()
        startClipboardPolling()
        startAutosaveTimer()
        installHotKeyEventHandler()
        registerHotKey()
        syncLoginItemState()
#if TESTING || CLIPMENU_TEST_HOST
        UpdateCoordinator.shared.configureFromDefaults()
#else
        if !promptToAddLoginItemIfNeeded() {
            UpdateCoordinator.shared.configureFromDefaults()
        }
#endif

        lastAppliedUserDefaultsSnapshot = effectiveUserDefaultsSnapshot()
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(handlePreferencePanelWillClose(_:)),
            name: .CMPreferencePanelWillClose,
            object: nil
        )
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(rebuildMenu),
            name: .CMSnippetEditorWillClose,
            object: nil
        )
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(userDefaultsDidChange(_:)),
            name: UserDefaults.didChangeNotification,
            object: nil
        )
        NSWorkspace.shared.notificationCenter.addObserver(
            self,
            selector: #selector(workspaceDidActivateApplication(_:)),
            name: NSWorkspace.didActivateApplicationNotification,
            object: nil
        )

#if DEBUG
