    func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
#if DEBUG
        if debugQuitMenuItemReportURL != nil {
            debugQuitMenuItemReport["applicationShouldTerminateCalled"] = true
        }
#endif
        guard persistHistoryForTermination() else {
            NSApp.activate(ignoringOtherApps: true)
            let alert = makeHistoryPersistenceFailureAlert()
            alert.runModal()
            terminationPersistenceHandled = true
            return .terminateNow
        }

        terminationPersistenceHandled = true
        return .terminateNow
    }

    func applicationWillTerminate(_ notification: Notification) {
        finishPasteActivity(reason: "termination")
#if DEBUG
        if debugQuitMenuItemReportURL != nil {
            debugQuitMenuItemReport["applicationWillTerminateCalled"] = true
            debugQuitMenuItemReport["terminationPersistenceHandledAtWillTerminate"] = terminationPersistenceHandled
        }
#endif
        unregisterHotKey()
        for menu in trackedPopupMenus.filter({ $0.supermenu == nil }) {
            stopTrackingPopupMenu(menu)
        }
        removePopupNumericKeyEventTap()
        endTrackingPopupInteraction()
        NSWorkspace.shared.notificationCenter.removeObserver(self)
        pollingTimer?.invalidate()
        autosaveTimer?.invalidate()
        if let hotKeyEventHandler {
            RemoveEventHandler(hotKeyEventHandler)
        }

        CMFlushEditorStoresForTermination()

#if DEBUG
        if debugQuitMenuItemReportURL != nil {
            finalizeDebugQuitMenuItemReport(fallbackTriggered: false)
        }
#endif

        guard !terminationPersistenceHandled else { return }
        if !persistHistoryForTermination() {
            NSApp.activate(ignoringOtherApps: true)
            let alert = makeHistoryPersistenceFailureAlert()
            alert.runModal()
        }
    }

#if DEBUG
    private func writeDebugPasteAutomationReadinessForUITestingIfNeeded() {
        guard let path = debugStringValue(forKey: "debugPasteAutomationReadinessPath"),
              !path.isEmpty else { return }
        let accessState = currentPasteAutomationAccessState()
        let report: [String: Any] = [
            "accessibilityGranted": accessState.accessibilityGranted,
            "postEventGranted": accessState.postEventGranted,
            "canSynthesizePaste": accessState.canSynthesizePaste
        ]
        guard let data = try? JSONSerialization.data(withJSONObject: report, options: [.sortedKeys]) else { return }
        try? data.write(to: URL(fileURLWithPath: path), options: .atomic)
    }

    private func scheduleDebugAutoSelectFirstClipIfNeeded() {
        let delay = debugDoubleValue(forKey: "debugAutoSelectFirstClipAfterLaunchDelay")
        guard delay > 0 else { return }

        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            self?.runDebugAutoSelectFirstClip()
        }
    }

    private func runDebugAutoSelectFirstClip() {
        let targetText = debugStringValue(forKey: "debugAutoSelectClipText")
        if let targetText, !targetText.isEmpty,
           !clipsStore.clips.contains(where: { $0.text == targetText }) {
            clipsStore.add(ClipItem(text: targetText))
            rebuildMenu()
            debugPasteFlow("runDebugAutoSelectFirstClip seeded targetText=\(targetText)")
        }

        let clip = targetText.flatMap { text in
            clipsStore.orderedClips.first { $0.text == text }
        } ?? clipsStore.orderedClips.first

        guard let clip else {
            debugPasteFlow("runDebugAutoSelectFirstClip noClips")
            return
        }

        rememberPasteTargetApplication()
        let item = makeClipMenuItem(clip: clip, globalIndex: 0, listNumber: 1)
        debugPasteFlow("runDebugAutoSelectFirstClip firing title=\(item.title)")
        selectClip(item)
    }

