    private func runDebugLoginPromptReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugStringValue(forKey: "debugLoginPromptReportPath")
            ?? "/tmp/clipmenu-login-prompt-report.json")
        let beforeLoginItem = defaults.bool(forKey: CMPrefLoginItemKey)
        let beforeSuppressed = defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)
        let shouldPrompt = shouldPromptToAddLoginItem(defaults: defaults)
        let alert = makeLoginItemPrompt()
        let alertButtonTitles = alert.buttons.map(\.title)
        let accessoryTextValues: [String] = {
            guard let accessoryView = alert.accessoryView else { return [] }
            var values: [String] = []
            func collect(from view: NSView) {
                if let textField = view as? NSTextField {
                    let value = textField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
                    if !value.isEmpty {
                        values.append(value)
                    }
                }
                for subview in view.subviews {
                    collect(from: subview)
                }
            }
            collect(from: accessoryView)
            return Array(NSOrderedSet(array: values)) as? [String] ?? values
        }()
        let simulatedResponse = (debugStringValue(forKey: "debugSimulateLoginPromptResponse") ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        let simulatedSuppression = debugBoolArgumentValue(forKey: "debugSimulateLoginPromptSuppression") ?? false

        func resetPromptState() {
            defaults.set(false, forKey: CMPrefLoginItemKey)
            defaults.set(false, forKey: CMPrefSuppressAlertForLoginItemKey)
        }

        resetPromptState()
        let launchPathShouldPrompt = shouldPromptToAddLoginItem(defaults: defaults)
        applyLoginItemPromptDecision(launchOnStartup: true, suppressPrompt: true, defaults: defaults)
        let launchPath: [String: Any] = [
            "shouldPrompt": launchPathShouldPrompt,
            "after": [
                "loginItem": defaults.bool(forKey: CMPrefLoginItemKey),
                "suppressAlertForLoginItem": defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)
            ]
        ]

        resetPromptState()
        let dontLaunchPathShouldPrompt = shouldPromptToAddLoginItem(defaults: defaults)
        applyLoginItemPromptDecision(launchOnStartup: false, suppressPrompt: true, defaults: defaults)
        let dontLaunchPath: [String: Any] = [
            "shouldPrompt": dontLaunchPathShouldPrompt,
            "after": [
                "loginItem": defaults.bool(forKey: CMPrefLoginItemKey),
                "suppressAlertForLoginItem": defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)
            ]
        ]

        defaults.set(beforeLoginItem, forKey: CMPrefLoginItemKey)
        defaults.set(beforeSuppressed, forKey: CMPrefSuppressAlertForLoginItemKey)

        var appliedResponse: String? = nil
        if shouldPrompt {
            switch simulatedResponse {
            case "launch", "yes", "enable":
                applyLoginItemPromptDecision(launchOnStartup: true, suppressPrompt: simulatedSuppression, defaults: defaults)
                appliedResponse = "launch"
            case "dontlaunch", "don'tlaunch", "no", "disable":
                applyLoginItemPromptDecision(launchOnStartup: false, suppressPrompt: simulatedSuppression, defaults: defaults)
                appliedResponse = "dontLaunch"
            default:
                break
            }
        }

        let afterLoginItem = defaults.bool(forKey: CMPrefLoginItemKey)
        let afterSuppressed = defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)
        let simulatedResponseMatchesExpected: Bool = {
            switch appliedResponse {
            case "launch":
                return afterLoginItem == true && afterSuppressed == simulatedSuppression
            case "dontLaunch":
                return afterLoginItem == false && afterSuppressed == simulatedSuppression
            default:
                return afterLoginItem == beforeLoginItem && afterSuppressed == beforeSuppressed
            }
        }()
        let expectedLaunchPath: [String: Any] = [
            "shouldPrompt": true,
            "after": [
                "loginItem": true,
                "suppressAlertForLoginItem": true
            ]
        ]
        let expectedDontLaunchPath: [String: Any] = [
            "shouldPrompt": true,
            "after": [
                "loginItem": false,
                "suppressAlertForLoginItem": true
            ]
        ]
        let expectedAlertState: [String: Any] = [
            "messageText": NSLocalizedString("Launch ClipMenu on system startup?", comment: ""),
            "informativeText": NSLocalizedString("You can change this setting in the Preferences if you want.", comment: ""),
            "buttonTitles": [
                NSLocalizedString("Launch on system startup", comment: ""),
                NSLocalizedString("Don't Launch", comment: "")
            ],
            "showsSuppressionButton": true,
            "hasAccessoryView": true,
            "accessoryTextValues": [
                NSLocalizedString("768.title", tableName: "Preferences", bundle: .main, value: "Launch on Login", comment: ""),
                localizedLoginItemPromptAccessoryDetail()
            ]
        ]
        let expectedAfterState: [String: Any] = {
            switch appliedResponse {
            case "launch":
                return [
                    "loginItem": true,
                    "suppressAlertForLoginItem": simulatedSuppression
                ]
            case "dontLaunch":
                return [
                    "loginItem": false,
                    "suppressAlertForLoginItem": simulatedSuppression
                ]
            default:
                return [
                    "loginItem": beforeLoginItem,
                    "suppressAlertForLoginItem": beforeSuppressed
                ]
            }
        }()
        let actualAfterState: [String: Any] = [
            "loginItem": afterLoginItem,
            "suppressAlertForLoginItem": afterSuppressed
        ]
        let actualAlertState: [String: Any] = [
            "messageText": alert.messageText,
            "informativeText": alert.informativeText,
            "buttonTitles": alertButtonTitles,
            "showsSuppressionButton": alert.showsSuppressionButton,
            "hasAccessoryView": alert.accessoryView != nil,
            "accessoryTextValues": accessoryTextValues
        ]
        let matchesExpected = (launchPath as NSDictionary).isEqual(to: expectedLaunchPath)
            && (dontLaunchPath as NSDictionary).isEqual(to: expectedDontLaunchPath)
            && (actualAlertState as NSDictionary).isEqual(to: expectedAlertState)
            && (actualAfterState as NSDictionary).isEqual(to: expectedAfterState)
            && simulatedResponseMatchesExpected

        let report: [String: Any] = [
            "supportsMainAppLoginItem": LoginItemManager.supportsMainAppLoginItem,
            "before": [
                "loginItem": beforeLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "shouldPrompt": shouldPrompt,
            "simulatedResponse": appliedResponse as Any,
            "simulatedSuppression": simulatedSuppression,
            "launchPath": launchPath,
            "expectedLaunchPath": expectedLaunchPath,
            "dontLaunchPath": dontLaunchPath,
            "expectedDontLaunchPath": expectedDontLaunchPath,
            "bothChoicesPersistExpectedState": (launchPath as NSDictionary).isEqual(to: expectedLaunchPath)
                && (dontLaunchPath as NSDictionary).isEqual(to: expectedDontLaunchPath),
            "alertState": actualAlertState,
            "expectedAlertState": expectedAlertState,
            "after": actualAfterState,
            "expectedAfter": expectedAfterState,
            "loginItemMutationBypassed": debugBypassLoginItemMutation(),
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        debugTerminateApplication()
    }

    private func runDebugPreferencesLoginItemTimingReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPreferencesLoginItemTimingReportPath")
            ?? "/tmp/clipmenu-preferences-login-item-timing-report.json")
        let originalLoginItem = defaults.bool(forKey: CMPrefLoginItemKey)
        let originalSuppressed = defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)
        let originalLastRequested = lastRequestedLoginItemState
        let originalDeferred = deferredLoginItemSyncRequired

        defer {
            defaults.set(originalLoginItem, forKey: CMPrefLoginItemKey)
            defaults.set(originalSuppressed, forKey: CMPrefSuppressAlertForLoginItemKey)
            lastRequestedLoginItemState = originalLastRequested
            deferredLoginItemSyncRequired = originalDeferred
            SwiftUIPreferencesWindowController.shared.close()
            debugTerminateApplication()
        }

        defaults.set(false, forKey: CMPrefSuppressAlertForLoginItemKey)
        lastRequestedLoginItemState = originalLoginItem
        deferredLoginItemSyncRequired = false

        showPreferencePanel(nil)
        let toggledValue = !originalLoginItem
        defaults.set(toggledValue, forKey: CMPrefLoginItemKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let beforeClose: [String: Any] = [
            "requestedLoginItem": defaults.bool(forKey: CMPrefLoginItemKey),
            "lastRequestedLoginItemState": lastRequestedLoginItemState as Any,
            "deferredLoginItemSyncRequired": deferredLoginItemSyncRequired
        ]

        handlePreferencePanelWillClose(Notification(name: .CMPreferencePanelWillClose))

        let afterClose: [String: Any] = [
            "requestedLoginItem": defaults.bool(forKey: CMPrefLoginItemKey),
            "lastRequestedLoginItemState": lastRequestedLoginItemState as Any,
            "deferredLoginItemSyncRequired": deferredLoginItemSyncRequired
        ]
        let expectedBeforeClose: [String: Any] = [
            "requestedLoginItem": toggledValue,
            "lastRequestedLoginItemState": originalLoginItem,
            "deferredLoginItemSyncRequired": true
        ]
        let expectedAfterClose: [String: Any] = [
            "requestedLoginItem": toggledValue,
            "lastRequestedLoginItemState": toggledValue,
            "deferredLoginItemSyncRequired": false
        ]
        let deferredUntilClose = (beforeClose["lastRequestedLoginItemState"] as? Bool) == originalLoginItem
            && (beforeClose["deferredLoginItemSyncRequired"] as? Bool) == true
            && (afterClose["lastRequestedLoginItemState"] as? Bool) == toggledValue
            && (afterClose["deferredLoginItemSyncRequired"] as? Bool) == false
        let matchesExpected = (beforeClose as NSDictionary).isEqual(to: expectedBeforeClose)
            && (afterClose as NSDictionary).isEqual(to: expectedAfterClose)
            && deferredUntilClose

        let report: [String: Any] = [
            "originalLoginItem": originalLoginItem,
            "toggledLoginItem": toggledValue,
            "beforeClose": beforeClose,
            "afterClose": afterClose,
            "expectedBeforeClose": expectedBeforeClose,
            "expectedAfterClose": expectedAfterClose,
            "deferredUntilClose": deferredUntilClose,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugPreferencesAutosaveTimingReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPreferencesAutosaveTimingReportPath")
            ?? "/tmp/clipmenu-preferences-autosave-timing-report.json")
        let originalDelay = defaults.double(forKey: CMPrefAutosaveDelayKey)
        let originalAppliedInterval = lastAppliedAutosaveInterval
        let originalDeferred = deferredAutosaveRestartRequired

        defer {
            defaults.set(originalDelay, forKey: CMPrefAutosaveDelayKey)
            lastAppliedAutosaveInterval = originalAppliedInterval
            deferredAutosaveRestartRequired = originalDeferred
            syncAutosaveTimer(force: true)
            SwiftUIPreferencesWindowController.shared.close()
            debugTerminateApplication()
        }

        showPreferencePanel(nil)
        let toggledDelay: Double = originalDelay == 0 ? 1800 : (originalDelay >= 1800 ? 300 : 1800)
        defaults.set(toggledDelay, forKey: CMPrefAutosaveDelayKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let beforeClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefAutosaveDelayKey),
            "lastAppliedInterval": lastAppliedAutosaveInterval as Any,
            "activeTimerInterval": autosaveTimer?.timeInterval as Any,
            "deferredAutosaveRestartRequired": deferredAutosaveRestartRequired
        ]

        handlePreferencePanelWillClose(Notification(name: .CMPreferencePanelWillClose))

        let afterClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefAutosaveDelayKey),
            "lastAppliedInterval": lastAppliedAutosaveInterval as Any,
            "activeTimerInterval": autosaveTimer?.timeInterval as Any,
            "deferredAutosaveRestartRequired": deferredAutosaveRestartRequired
        ]

        let originalEffectiveInterval = originalDelay > 0 ? max(originalDelay, CMMinimumAutosaveInterval) : 0
        let toggledEffectiveInterval = toggledDelay > 0 ? max(toggledDelay, CMMinimumAutosaveInterval) : 0
        let expectedBeforeClose: [String: Any] = [
            "requestedInterval": toggledDelay,
            "lastAppliedInterval": originalEffectiveInterval,
            "activeTimerInterval": originalEffectiveInterval,
            "deferredAutosaveRestartRequired": true
        ]
        let expectedAfterClose: [String: Any] = [
            "requestedInterval": toggledDelay,
            "lastAppliedInterval": toggledEffectiveInterval,
            "activeTimerInterval": toggledEffectiveInterval,
            "deferredAutosaveRestartRequired": false
        ]
        let deferredUntilClose = abs(((beforeClose["lastAppliedInterval"] as? Double) ?? 0) - originalEffectiveInterval) < 0.0001
            && abs(((beforeClose["activeTimerInterval"] as? Double) ?? 0) - originalEffectiveInterval) < 0.0001
            && (beforeClose["deferredAutosaveRestartRequired"] as? Bool) == true
            && abs(((afterClose["lastAppliedInterval"] as? Double) ?? 0) - toggledEffectiveInterval) < 0.0001
            && abs(((afterClose["activeTimerInterval"] as? Double) ?? 0) - toggledEffectiveInterval) < 0.0001
            && (afterClose["deferredAutosaveRestartRequired"] as? Bool) == false
        defaults.set(120, forKey: CMPrefAutosaveDelayKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))
        let malformedBeforeClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefAutosaveDelayKey),
            "lastAppliedInterval": lastAppliedAutosaveInterval as Any,
            "activeTimerInterval": autosaveTimer?.timeInterval as Any,
            "deferredAutosaveRestartRequired": deferredAutosaveRestartRequired
        ]
        handlePreferencePanelWillClose(Notification(name: .CMPreferencePanelWillClose))
        let malformedAfterClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefAutosaveDelayKey),
            "lastAppliedInterval": lastAppliedAutosaveInterval as Any,
            "activeTimerInterval": autosaveTimer?.timeInterval as Any,
            "deferredAutosaveRestartRequired": deferredAutosaveRestartRequired
        ]
        let malformedNormalizedDelay = defaults.integer(forKey: CMPrefAutosaveDelayKey)
        let malformedEffectiveInterval = autosaveTimer?.timeInterval ?? 0
        let malformedRequestedInterval = (malformedBeforeClose["requestedInterval"] as? Double) ?? -1
        let malformedBeforeDeferred = (malformedBeforeClose["deferredAutosaveRestartRequired"] as? Bool) ?? false
        let malformedAfterDeferred = (malformedAfterClose["deferredAutosaveRestartRequired"] as? Bool) ?? true
        let expectedMalformedBeforeClose: [String: Any] = [
            "requestedInterval": 60.0,
            "lastAppliedInterval": toggledEffectiveInterval,
            "activeTimerInterval": toggledEffectiveInterval,
            "deferredAutosaveRestartRequired": true
        ]
        let expectedMalformedAfterClose: [String: Any] = [
            "requestedInterval": 60.0,
            "lastAppliedInterval": max(60.0, CMMinimumAutosaveInterval),
            "activeTimerInterval": max(60.0, CMMinimumAutosaveInterval),
            "deferredAutosaveRestartRequired": false
        ]
        let matchesExpected = (beforeClose as NSDictionary).isEqual(to: expectedBeforeClose)
            && (afterClose as NSDictionary).isEqual(to: expectedAfterClose)
            && deferredUntilClose
            && malformedNormalizedDelay == 60
            && (malformedBeforeClose as NSDictionary).isEqual(to: expectedMalformedBeforeClose)
            && (malformedAfterClose as NSDictionary).isEqual(to: expectedMalformedAfterClose)
            && abs(malformedEffectiveInterval - max(60.0, CMMinimumAutosaveInterval)) < 0.0001

        let report: [String: Any] = [
            "originalInterval": originalDelay,
            "toggledInterval": toggledDelay,
            "beforeClose": beforeClose,
            "afterClose": afterClose,
            "expectedBeforeClose": expectedBeforeClose,
            "expectedAfterClose": expectedAfterClose,
            "malformedBeforeClose": malformedBeforeClose,
            "malformedAfterClose": malformedAfterClose,
            "expectedMalformedBeforeClose": expectedMalformedBeforeClose,
            "expectedMalformedAfterClose": expectedMalformedAfterClose,
            "malformedNormalizedDelay": malformedNormalizedDelay,
            "malformedEffectiveInterval": malformedEffectiveInterval,
            "malformedDelayNormalizesToLegacyMinute": malformedNormalizedDelay == 60
                && abs(malformedRequestedInterval - 60) < 0.0001
                && malformedBeforeDeferred
                && (malformedAfterClose as NSDictionary).isEqual(to: expectedMalformedAfterClose)
                && malformedAfterDeferred == false,
            "deferredUntilClose": deferredUntilClose,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugPreferencesObserveIntervalTimingReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPreferencesObserveIntervalTimingReportPath")
            ?? "/tmp/clipmenu-preferences-observe-interval-timing-report.json")
        let originalInterval = defaults.double(forKey: CMPrefTimeIntervalKey)
        let originalAppliedInterval = lastAppliedClipboardPollingInterval
        let originalDeferred = deferredClipboardPollingRestartRequired

        func timerMatchesRequestedInterval(_ activeTimerInterval: Double?, requestedInterval: Double) -> Bool {
            let active = activeTimerInterval ?? -1
            if requestedInterval == 0 {
                return active > 0 && active <= 0.0001
            }
            return abs(active - requestedInterval) < 0.0001
        }

        defer {
            defaults.set(originalInterval, forKey: CMPrefTimeIntervalKey)
            lastAppliedClipboardPollingInterval = originalAppliedInterval
            deferredClipboardPollingRestartRequired = originalDeferred
            startClipboardPolling()
            SwiftUIPreferencesWindowController.shared.close()
            debugTerminateApplication()
        }

        showPreferencePanel(nil)
        let toggledInterval = originalInterval >= 0.95 ? 0.25 : min(originalInterval + 0.2, 1.0)
        defaults.set(toggledInterval, forKey: CMPrefTimeIntervalKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let beforeClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefTimeIntervalKey),
            "lastAppliedInterval": lastAppliedClipboardPollingInterval as Any,
            "activeTimerInterval": pollingTimer?.timeInterval as Any,
            "deferredClipboardPollingRestartRequired": deferredClipboardPollingRestartRequired
        ]

        handlePreferencePanelWillClose(Notification(name: .CMPreferencePanelWillClose))

        let afterClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefTimeIntervalKey),
            "lastAppliedInterval": lastAppliedClipboardPollingInterval as Any,
            "activeTimerInterval": pollingTimer?.timeInterval as Any,
            "deferredClipboardPollingRestartRequired": deferredClipboardPollingRestartRequired
        ]
        let expectedBeforeClose: [String: Any] = [
            "requestedInterval": toggledInterval,
            "lastAppliedInterval": originalInterval,
            "activeTimerInterval": originalInterval == 0 ? 0.0001 : originalInterval,
            "deferredClipboardPollingRestartRequired": true
        ]
        let expectedAfterClose: [String: Any] = [
            "requestedInterval": toggledInterval,
            "lastAppliedInterval": toggledInterval,
            "activeTimerInterval": toggledInterval == 0 ? 0.0001 : toggledInterval,
            "deferredClipboardPollingRestartRequired": false
        ]
        let deferredUntilClose = abs(((beforeClose["lastAppliedInterval"] as? Double) ?? -1) - originalInterval) < 0.0001
            && timerMatchesRequestedInterval(beforeClose["activeTimerInterval"] as? Double, requestedInterval: originalInterval)
            && (beforeClose["deferredClipboardPollingRestartRequired"] as? Bool) == true
            && abs(((afterClose["lastAppliedInterval"] as? Double) ?? -1) - toggledInterval) < 0.0001
            && timerMatchesRequestedInterval(afterClose["activeTimerInterval"] as? Double, requestedInterval: toggledInterval)
            && (afterClose["deferredClipboardPollingRestartRequired"] as? Bool) == false

        showPreferencePanel(nil)
        defaults.set(-0.25, forKey: CMPrefTimeIntervalKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let malformedLowBeforeClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefTimeIntervalKey),
            "lastAppliedInterval": lastAppliedClipboardPollingInterval as Any,
            "activeTimerInterval": pollingTimer?.timeInterval as Any,
            "deferredClipboardPollingRestartRequired": deferredClipboardPollingRestartRequired
        ]
        handlePreferencePanelWillClose(Notification(name: .CMPreferencePanelWillClose))
        let malformedLowAfterClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefTimeIntervalKey),
            "lastAppliedInterval": lastAppliedClipboardPollingInterval as Any,
            "activeTimerInterval": pollingTimer?.timeInterval as Any,
            "deferredClipboardPollingRestartRequired": deferredClipboardPollingRestartRequired
        ]

        showPreferencePanel(nil)
        defaults.set(1.2, forKey: CMPrefTimeIntervalKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let malformedHighBeforeClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefTimeIntervalKey),
            "lastAppliedInterval": lastAppliedClipboardPollingInterval as Any,
            "activeTimerInterval": pollingTimer?.timeInterval as Any,
            "deferredClipboardPollingRestartRequired": deferredClipboardPollingRestartRequired
        ]
        handlePreferencePanelWillClose(Notification(name: .CMPreferencePanelWillClose))
        let malformedHighAfterClose: [String: Any] = [
            "requestedInterval": defaults.double(forKey: CMPrefTimeIntervalKey),
            "lastAppliedInterval": lastAppliedClipboardPollingInterval as Any,
            "activeTimerInterval": pollingTimer?.timeInterval as Any,
            "deferredClipboardPollingRestartRequired": deferredClipboardPollingRestartRequired
        ]
        let expectedMalformedLowBeforeClose: [String: Any] = [
            "requestedInterval": 0.0,
            "lastAppliedInterval": toggledInterval,
            "activeTimerInterval": toggledInterval == 0 ? 0.0001 : toggledInterval,
            "deferredClipboardPollingRestartRequired": true
        ]
        let expectedMalformedLowAfterClose: [String: Any] = [
            "requestedInterval": 0.0,
            "lastAppliedInterval": 0.0,
            "activeTimerInterval": 0.0001,
            "deferredClipboardPollingRestartRequired": false
        ]
        let expectedMalformedHighBeforeClose: [String: Any] = [
            "requestedInterval": 1.0,
            "lastAppliedInterval": 0.0,
            "activeTimerInterval": 0.0001,
            "deferredClipboardPollingRestartRequired": true
        ]
        let expectedMalformedHighAfterClose: [String: Any] = [
            "requestedInterval": 1.0,
            "lastAppliedInterval": 1.0,
            "activeTimerInterval": 1.0,
            "deferredClipboardPollingRestartRequired": false
        ]
        let malformedLowNormalizesToMinimum = abs(((malformedLowBeforeClose["requestedInterval"] as? Double) ?? -1) - 0.0) < 0.0001
            && abs(((malformedLowBeforeClose["lastAppliedInterval"] as? Double) ?? -1) - toggledInterval) < 0.0001
            && timerMatchesRequestedInterval(malformedLowBeforeClose["activeTimerInterval"] as? Double, requestedInterval: toggledInterval)
            && (malformedLowBeforeClose["deferredClipboardPollingRestartRequired"] as? Bool) == true
            && abs(((malformedLowAfterClose["requestedInterval"] as? Double) ?? -1) - 0.0) < 0.0001
            && abs(((malformedLowAfterClose["lastAppliedInterval"] as? Double) ?? -1) - 0.0) < 0.0001
            && timerMatchesRequestedInterval(malformedLowAfterClose["activeTimerInterval"] as? Double, requestedInterval: 0.0)
            && (malformedLowAfterClose["deferredClipboardPollingRestartRequired"] as? Bool) == false
        let malformedHighNormalizesToMaximum = abs(((malformedHighBeforeClose["requestedInterval"] as? Double) ?? -1) - 1.0) < 0.0001
            && abs(((malformedHighBeforeClose["lastAppliedInterval"] as? Double) ?? -1) - 0.0) < 0.0001
            && timerMatchesRequestedInterval(malformedHighBeforeClose["activeTimerInterval"] as? Double, requestedInterval: 0.0)
            && (malformedHighBeforeClose["deferredClipboardPollingRestartRequired"] as? Bool) == true
            && abs(((malformedHighAfterClose["requestedInterval"] as? Double) ?? -1) - 1.0) < 0.0001
            && abs(((malformedHighAfterClose["lastAppliedInterval"] as? Double) ?? -1) - 1.0) < 0.0001
            && timerMatchesRequestedInterval(malformedHighAfterClose["activeTimerInterval"] as? Double, requestedInterval: 1.0)
            && (malformedHighAfterClose["deferredClipboardPollingRestartRequired"] as? Bool) == false
        let matchesExpected = (beforeClose as NSDictionary).isEqual(to: expectedBeforeClose)
            && (afterClose as NSDictionary).isEqual(to: expectedAfterClose)
            && deferredUntilClose
            && (malformedLowBeforeClose as NSDictionary).isEqual(to: expectedMalformedLowBeforeClose)
            && (malformedLowAfterClose as NSDictionary).isEqual(to: expectedMalformedLowAfterClose)
            && (malformedHighBeforeClose as NSDictionary).isEqual(to: expectedMalformedHighBeforeClose)
            && (malformedHighAfterClose as NSDictionary).isEqual(to: expectedMalformedHighAfterClose)
            && malformedLowNormalizesToMinimum
            && malformedHighNormalizesToMaximum

        let report: [String: Any] = [
            "originalInterval": originalInterval,
            "toggledInterval": toggledInterval,
            "beforeClose": beforeClose,
            "afterClose": afterClose,
            "expectedBeforeClose": expectedBeforeClose,
            "expectedAfterClose": expectedAfterClose,
            "deferredUntilClose": deferredUntilClose,
            "malformedLowBeforeClose": malformedLowBeforeClose,
            "malformedLowAfterClose": malformedLowAfterClose,
            "malformedHighBeforeClose": malformedHighBeforeClose,
            "malformedHighAfterClose": malformedHighAfterClose,
            "expectedMalformedLowBeforeClose": expectedMalformedLowBeforeClose,
            "expectedMalformedLowAfterClose": expectedMalformedLowAfterClose,
            "expectedMalformedHighBeforeClose": expectedMalformedHighBeforeClose,
            "expectedMalformedHighAfterClose": expectedMalformedHighAfterClose,
            "malformedLowNormalizesToMinimum": malformedLowNormalizesToMinimum,
            "malformedHighNormalizesToMaximum": malformedHighNormalizesToMaximum,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugMaxHistorySizeNormalizationReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugMaxHistorySizeNormalizationReportPath")
            ?? "/tmp/clipmenu-max-history-size-normalization-report.json")
        let originalHistory = clipsStore.debugSnapshotForTesting
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)
        let originalReorderClipsAfterPasting = defaults.object(forKey: CMPrefReorderClipsAfterPasting)

        func makeDeterministicClip(text: String, seconds: TimeInterval) -> ClipItem {
            let date = Date(timeIntervalSinceReferenceDate: seconds)
            return ClipItem(text: text, createdAt: date, lastUsedAt: date)
        }

        func seedClips() {
            clipsStore.clear()
            [
                makeDeterministicClip(text: "history-alpha", seconds: 100),
                makeDeterministicClip(text: "history-beta", seconds: 200),
                makeDeterministicClip(text: "history-gamma", seconds: 300)
            ].forEach { clipsStore.add($0) }
        }

        defer {
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            restoreDefault(originalReorderClipsAfterPasting, forKey: CMPrefReorderClipsAfterPasting)
            clipsStore.debugRestoreSnapshotForTesting(originalHistory)
            rebuildMenu()
            debugTerminateApplication()
        }

        defaults.set(true, forKey: CMPrefReorderClipsAfterPasting)
        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        seedClips()

        defaults.set(0, forKey: CMPrefMaxHistorySizeKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let zeroState: [String: Any] = [
            "normalizedStoredLimit": defaults.integer(forKey: CMPrefMaxHistorySizeKey),
            "remainingOrderedTexts": clipsStore.orderedClips.map(\.text)
        ]

        seedClips()
        defaults.set(-3, forKey: CMPrefMaxHistorySizeKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let negativeState: [String: Any] = [
            "normalizedStoredLimit": defaults.integer(forKey: CMPrefMaxHistorySizeKey),
            "remainingOrderedTexts": clipsStore.orderedClips.map(\.text)
        ]

        let expectedRemainingTexts = ["history-gamma"]
        let expectedZeroState: [String: Any] = [
            "normalizedStoredLimit": 1,
            "remainingOrderedTexts": expectedRemainingTexts
        ]
        let expectedNegativeState: [String: Any] = [
            "normalizedStoredLimit": 1,
            "remainingOrderedTexts": expectedRemainingTexts
        ]
        let zeroNormalizesToMinimum = (zeroState as NSDictionary).isEqual(to: expectedZeroState)
        let negativeNormalizesToMinimum = (negativeState as NSDictionary).isEqual(to: expectedNegativeState)
        let report: [String: Any] = [
            "zeroState": zeroState,
            "expectedZeroState": expectedZeroState,
            "negativeState": negativeState,
            "expectedNegativeState": expectedNegativeState,
            "zeroNormalizesToMinimum": zeroNormalizesToMinimum,
            "negativeNormalizesToMinimum": negativeNormalizesToMinimum,
            "matchesExpected": zeroNormalizesToMinimum && negativeNormalizesToMinimum
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugExportSeparatorNormalizationReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugExportSeparatorNormalizationReportPath")
            ?? "/tmp/clipmenu-export-separator-normalization-report.json")
        let exportURL = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("clipmenu-export-separator-normalization.txt")
        let originalClips = clipsStore.clips
        let originalExportSeparator = defaults.object(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        let originalExportAsSingleFile = defaults.object(forKey: CMPrefExportHistoryAsSingleFileKey)
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)

        func makeDeterministicClip(text: String, seconds: TimeInterval) -> ClipItem {
            let date = Date(timeIntervalSinceReferenceDate: seconds)
            return ClipItem(text: text, createdAt: date, lastUsedAt: date)
        }

        defer {
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalExportSeparator, forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
            restoreDefault(originalExportAsSingleFile, forKey: CMPrefExportHistoryAsSingleFileKey)
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            try? FileManager.default.removeItem(at: exportURL)
            debugTerminateApplication()
        }

        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        defaults.set(true, forKey: CMPrefExportHistoryAsSingleFileKey)
        clipsStore.clear()
        [
            makeDeterministicClip(text: "alpha", seconds: 100),
            makeDeterministicClip(text: "beta", seconds: 200)
        ].forEach { clipsStore.add($0) }

        defaults.set(0, forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))
        try? FileManager.default.removeItem(at: exportURL)
        try? clipsStore.exportTextClipsAsSingleFile(to: exportURL)
        let noneExportedContents = (try? String(contentsOf: exportURL, encoding: .utf8)) ?? ""
        let noneState: [String: Any] = [
            "normalizedStoredSeparator": defaults.integer(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey),
            "exportedContents": noneExportedContents
        ]
        let expectedNoneState: [String: Any] = [
            "normalizedStoredSeparator": 0,
            "exportedContents": "betaalpha"
        ]

        defaults.set(9, forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))
        try? FileManager.default.removeItem(at: exportURL)
        try? clipsStore.exportTextClipsAsSingleFile(to: exportURL)
        let invalidExportedContents = (try? String(contentsOf: exportURL, encoding: .utf8)) ?? ""
        let invalidState: [String: Any] = [
            "normalizedStoredSeparator": defaults.integer(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey),
            "exportedContents": invalidExportedContents
        ]
        let expectedInvalidState: [String: Any] = [
            "normalizedStoredSeparator": 1,
            "exportedContents": "beta\nalpha\n"
        ]

        let report: [String: Any] = [
            "noneState": noneState,
            "expectedNoneState": expectedNoneState,
            "invalidState": invalidState,
            "expectedInvalidState": expectedInvalidState,
            "noneSeparatorRemovesDelimiters": (noneState as NSDictionary).isEqual(to: expectedNoneState),
            "invalidSeparatorFallsBackToLF": (invalidState as NSDictionary).isEqual(to: expectedInvalidState),
            "matchesExpected": (noneState as NSDictionary).isEqual(to: expectedNoneState)
                && (invalidState as NSDictionary).isEqual(to: expectedInvalidState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugExportModeNormalizationReport() {
        let defaults = UserDefaults.standard
