    private func runDebugSortOrderNormalizationReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSortOrderNormalizationReportPath")
            ?? "/tmp/clipmenu-sort-order-normalization-report.json")
        let originalClips = clipsStore.clips
        let originalSortOrder = defaults.object(forKey: CMPrefReorderClipsAfterPasting)
        let originalInputPasteCommand = defaults.object(forKey: CMPrefInputPasteCommandKey)
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)

        func makeDeterministicClip(text: String, created: TimeInterval, lastUsed: TimeInterval) -> ClipItem {
            ClipItem(
                text: text,
                createdAt: Date(timeIntervalSinceReferenceDate: created),
                lastUsedAt: Date(timeIntervalSinceReferenceDate: lastUsed)
            )
        }

        defer {
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalSortOrder, forKey: CMPrefReorderClipsAfterPasting)
            restoreDefault(originalInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            rebuildMenu()
            debugTerminateApplication()
        }

        defaults.set(false, forKey: CMPrefInputPasteCommandKey)
        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        clipsStore.clear()
        [
            makeDeterministicClip(text: "alpha", created: 100, lastUsed: 300),
            makeDeterministicClip(text: "beta", created: 200, lastUsed: 200),
            makeDeterministicClip(text: "gamma", created: 300, lastUsed: 100)
        ].forEach { clipsStore.add($0) }

        defaults.set(2, forKey: CMPrefReorderClipsAfterPasting)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let beforeSelectOrderedTexts = clipsStore.orderedClips.map(\.text)
        var afterSelectOrderedTexts = beforeSelectOrderedTexts
        var selectedText = ""
        if let selectedClip = clipsStore.orderedClips.last {
            let item = makeClipMenuItem(clip: selectedClip, globalIndex: 2, listNumber: 3)
            selectedText = selectedClip.text
            selectClip(item)
            afterSelectOrderedTexts = clipsStore.orderedClips.map(\.text)
        }
        let expectedBeforeSelectOrderedTexts = ["alpha", "beta", "gamma"]
        let expectedAfterSelectOrderedTexts = selectedText.isEmpty ? expectedBeforeSelectOrderedTexts : [selectedText, "alpha", "beta"]
        let actualState: [String: Any] = [
            "normalizedStoredSortOrder": defaults.bool(forKey: CMPrefReorderClipsAfterPasting),
            "beforeSelectOrderedTexts": beforeSelectOrderedTexts,
            "afterSelectOrderedTexts": afterSelectOrderedTexts
        ]
        let expectedState: [String: Any] = [
            "normalizedStoredSortOrder": true,
            "beforeSelectOrderedTexts": expectedBeforeSelectOrderedTexts,
            "afterSelectOrderedTexts": expectedAfterSelectOrderedTexts
        ]

        let report: [String: Any] = [
            "normalizedStoredSortOrder": defaults.object(forKey: CMPrefReorderClipsAfterPasting) as Any,
            "normalizedSortOrderIsLastUsed": defaults.bool(forKey: CMPrefReorderClipsAfterPasting),
            "beforeSelectOrderedTexts": beforeSelectOrderedTexts,
            "expectedBeforeSelectOrderedTexts": expectedBeforeSelectOrderedTexts,
            "selectedText": selectedText,
            "afterSelectOrderedTexts": afterSelectOrderedTexts,
            "expectedAfterSelectOrderedTexts": expectedAfterSelectOrderedTexts,
            "state": actualState,
            "expectedState": expectedState,
            "selectionPromotedToTop": afterSelectOrderedTexts.first == selectedText,
            "matchesExpected": (actualState as NSDictionary).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

