    private func runDebugPreferencesActionBehaviorTimingReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPreferencesActionBehaviorTimingReportPath")
            ?? "/tmp/clipmenu-preferences-action-behavior-timing-report.json")
        let originalControl = defaults.object(forKey: CMPrefContorlClickBehaviorKey)
        let originalShift = defaults.object(forKey: CMPrefShiftClickBehaviorKey)
        let stagedShift: [String: String] = [
            "type": "builtin",
            "name": "removeAction"
        ]

        defer {
            ActionBehaviorDraft.shared.discardPendingSelections()
            defaults.set(originalControl, forKey: CMPrefContorlClickBehaviorKey)
            defaults.set(originalShift, forKey: CMPrefShiftClickBehaviorKey)
            SwiftUIPreferencesWindowController.shared.close()
            debugTerminateApplication()
        }

        defaults.set("", forKey: CMPrefContorlClickBehaviorKey)
        defaults.set("", forKey: CMPrefShiftClickBehaviorKey)
        showPreferencePanel(nil)
        ActionBehaviorDraft.shared.stageDefaultsObject("popUpActionMenu", defaultsKey: CMPrefContorlClickBehaviorKey)
        ActionBehaviorDraft.shared.controlClickBehaviorID = "string:popUpActionMenu"
        ActionBehaviorDraft.shared.stageDefaultsObject(stagedShift, defaultsKey: CMPrefShiftClickBehaviorKey)

        let beforeClose: [String: Any] = [
            "controlDefaultsValue": defaults.object(forKey: CMPrefContorlClickBehaviorKey) as Any,
            "shiftDefaultsValue": defaults.object(forKey: CMPrefShiftClickBehaviorKey) as Any
        ]

        SwiftUIPreferencesWindowController.shared.windowWillClose(
            Notification(name: NSWindow.willCloseNotification, object: SwiftUIPreferencesWindowController.shared.window)
        )

        let afterClose: [String: Any] = [
            "controlDefaultsValue": defaults.object(forKey: CMPrefContorlClickBehaviorKey) as Any,
            "shiftDefaultsValue": defaults.object(forKey: CMPrefShiftClickBehaviorKey) as Any
        ]
        let expectedBeforeClose: [String: Any] = [
            "controlDefaultsValue": "",
            "shiftDefaultsValue": ""
        ]
        let expectedAfterClose: [String: Any] = [
            "controlDefaultsValue": "popUpActionMenu",
            "shiftDefaultsValue": stagedShift
        ]
        let deferredUntilClose = (beforeClose["controlDefaultsValue"] as? String) != "popUpActionMenu"
            && (afterClose["controlDefaultsValue"] as? String) == "popUpActionMenu"
            && ((afterClose["shiftDefaultsValue"] as? [String: String])?["name"] == stagedShift["name"])
        let matchesExpected = (beforeClose as NSDictionary).isEqual(to: expectedBeforeClose)
            && (afterClose as NSDictionary).isEqual(to: expectedAfterClose)
            && deferredUntilClose

        let report: [String: Any] = [
            "beforeClose": beforeClose,
            "afterClose": afterClose,
            "expectedBeforeClose": expectedBeforeClose,
            "expectedAfterClose": expectedAfterClose,
            "deferredUntilClose": deferredUntilClose,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugPreferencesStoreTypesTimingReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPreferencesStoreTypesTimingReportPath")
            ?? "/tmp/clipmenu-preferences-store-types-timing-report.json")
        let originalStoreTypesObject = defaults.object(forKey: CMPrefStoreTypesKey)
        let baselineStoreTypes = ClipItem.defaultStoreTypes()
        let toggledKey = baselineStoreTypes.keys.sorted().first ?? "NSStringPboardType"
        let originalToggleValue = baselineStoreTypes[toggledKey] ?? true
        let toggledValue = !originalToggleValue
        let normalizedStoreTypes: ([String: Any]?) -> [String: Bool] = { rawStoreTypes in
            var storeTypes = baselineStoreTypes
            guard let rawStoreTypes else { return storeTypes }

            for (key, value) in rawStoreTypes {
                if let bool = value as? Bool {
                    storeTypes[key] = bool
                } else if let number = value as? NSNumber {
                    storeTypes[key] = number.boolValue
                }
            }

            return storeTypes
        }

        defer {
            CMRevertRecordingStoreTypes()
            if let originalStoreTypesObject {
                defaults.set(originalStoreTypesObject, forKey: CMPrefStoreTypesKey)
            } else {
                defaults.removeObject(forKey: CMPrefStoreTypesKey)
            }
            CMReloadRecordingPreferences()
            SwiftUIPreferencesWindowController.shared.close()
            debugTerminateApplication()
        }

        defaults.set(baselineStoreTypes, forKey: CMPrefStoreTypesKey)
        CMReloadRecordingPreferences()
        showPreferencePanel(nil)

        CMStageRecordingStoreType(toggledKey, enabled: toggledValue)

        let beforeCloseStoreTypes = normalizedStoreTypes(defaults.dictionary(forKey: CMPrefStoreTypesKey))
        let expectedBeforeCloseStoreTypes = normalizedStoreTypes(baselineStoreTypes)

        SwiftUIPreferencesWindowController.shared.windowWillClose(
            Notification(name: NSWindow.willCloseNotification, object: SwiftUIPreferencesWindowController.shared.window)
        )

        let afterCloseStoreTypes = normalizedStoreTypes(defaults.dictionary(forKey: CMPrefStoreTypesKey))
        var expectedAfterCloseStoreTypes = expectedBeforeCloseStoreTypes
        expectedAfterCloseStoreTypes[toggledKey] = toggledValue
        let actualState: [String: Any] = [
            "beforeCloseStoreTypes": beforeCloseStoreTypes,
            "afterCloseStoreTypes": afterCloseStoreTypes
        ]
        let expectedState: [String: Any] = [
            "beforeCloseStoreTypes": expectedBeforeCloseStoreTypes,
            "afterCloseStoreTypes": expectedAfterCloseStoreTypes
        ]
        let deferredUntilClose = beforeCloseStoreTypes == expectedBeforeCloseStoreTypes
            && afterCloseStoreTypes == expectedAfterCloseStoreTypes
        let matchesExpected = (actualState as NSDictionary).isEqual(to: expectedState)
            && deferredUntilClose
        let report: [String: Any] = [
            "toggledStoreTypeKey": toggledKey,
            "originalValue": originalToggleValue,
            "toggledValue": toggledValue,
            "beforeCloseStoreTypes": beforeCloseStoreTypes,
            "afterCloseStoreTypes": afterCloseStoreTypes,
            "expectedBeforeCloseStoreTypes": expectedBeforeCloseStoreTypes,
            "expectedAfterCloseStoreTypes": expectedAfterCloseStoreTypes,
            "state": actualState,
            "expectedState": expectedState,
            "deferredUntilClose": deferredUntilClose,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

