    private func runDebugLoginItemSyncReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugStringValue(forKey: "debugLoginItemSyncReportPath")
            ?? "/tmp/clipmenu-login-item-sync-report.json")
        let requestedLoginItemState = debugBoolArgumentValue(forKey: "debugRequestedLoginItemState") ?? true
        let beforeLoginItem = defaults.bool(forKey: CMPrefLoginItemKey)
        let beforeSuppressed = defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)

        defaults.set(requestedLoginItemState, forKey: CMPrefLoginItemKey)
        lastRequestedLoginItemState = nil
        syncLoginItemState()
        let afterLoginItem = defaults.bool(forKey: CMPrefLoginItemKey)
        let afterSuppressed = defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)
        let simulatedMutationFailure = debugSimulateLoginItemMutationFailure()
        let loginItemMutationBypassed = debugBypassLoginItemMutation()
        let expectedLastRequestedState: Bool = {
            if simulatedMutationFailure && requestedLoginItemState {
                return false
            }
            return requestedLoginItemState
        }()
        let expectedStoredLoginItem: Bool = {
            if simulatedMutationFailure && requestedLoginItemState {
                return false
            }
            return requestedLoginItemState
        }()
        let actualState: [String: Any] = [
            "before": [
                "loginItem": beforeLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "requestedLoginItemState": requestedLoginItemState,
            "simulatedMutationFailure": simulatedMutationFailure,
            "loginItemMutationBypassed": loginItemMutationBypassed,
            "after": [
                "loginItem": afterLoginItem,
                "suppressAlertForLoginItem": afterSuppressed
            ],
            "lastRequestedLoginItemState": lastRequestedLoginItemState as Any
        ]
        let expectedState: [String: Any] = [
            "before": [
                "loginItem": beforeLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "requestedLoginItemState": requestedLoginItemState,
            "simulatedMutationFailure": simulatedMutationFailure,
            "loginItemMutationBypassed": loginItemMutationBypassed,
            "after": [
                "loginItem": expectedStoredLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "lastRequestedLoginItemState": expectedLastRequestedState
        ]
        let matchesExpected = (actualState as NSDictionary).isEqual(to: expectedState)

        let report: [String: Any] = [
            "before": [
                "loginItem": beforeLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "requestedLoginItemState": requestedLoginItemState,
            "simulatedMutationFailure": simulatedMutationFailure,
            "loginItemMutationBypassed": loginItemMutationBypassed,
            "after": [
                "loginItem": afterLoginItem,
                "suppressAlertForLoginItem": afterSuppressed
            ],
            "lastRequestedLoginItemState": lastRequestedLoginItemState as Any,
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        debugTerminateApplication()
    }

