    private func runDebugPreferencesWindowReport() {
        showPreferencePanel(nil)

        let settleDelay = debugOneShotDoubleValue(forKey: "debugPreferencesWindowReportSettleDelay") ?? 0.75
        DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
            let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPreferencesWindowReportPath")
                ?? "/tmp/clipmenu-preferences-window-report.json")
            var report: [String: Any] = [:]
            if let window = SwiftUIPreferencesWindowController.shared.window {
                let currentApplication = NSRunningApplication.current
                let activationDeadline = Date(timeIntervalSinceNow: 2.0)

                while Date() < activationDeadline {
                    currentApplication.activate(options: [.activateIgnoringOtherApps])
                    NSApp.activate(ignoringOtherApps: true)
                    window.orderFrontRegardless()
                    window.makeMain()
                    window.makeKeyAndOrderFront(nil)
                    RunLoop.main.run(until: Date(timeIntervalSinceNow: 0.05))
                    if currentApplication.isActive && window.isKeyWindow && window.isMainWindow {
                        break
                    }
                }

                let visibleTextValues = self.debugVisibleTextValues(in: window.contentView, window: window)
                let expectedPaneTitles = self.debugExpectedPreferencePaneTitles()
                let shellSnapshot = SwiftUIPreferencesWindowController.shared.debugShellSnapshot()
                let visiblePaneTitles = shellSnapshot["visiblePaneTitles"] as? [String] ?? []
                let visiblePaneIconSources = shellSnapshot["visiblePaneIconSources"] as? [String: String] ?? [:]
                let configuredPaneTitles = CMConfiguredPreferencePaneTitlesForDebug()
                let expectedPaneIconSources: [String: String] = [
                    NSLocalizedString("General", comment: ""): "systemSymbol",
                    NSLocalizedString("Menu", comment: ""): "systemSymbol",
                    NSLocalizedString("1086.label", tableName: "Preferences", bundle: .main, value: "Type", comment: ""): "systemSymbol",
                    NSLocalizedString("Action", comment: ""): "systemSymbol",
                    NSLocalizedString("1366.title", tableName: "Preferences", bundle: .main, value: "Shortcuts", comment: ""): "systemSymbol",
                    NSLocalizedString("Updates", comment: ""): "systemSymbol"
                ]
                let expectedSelectedTabRawValue = debugStringValue(forKey: "debugShowPreferencesTab")?.lowercased() ?? "general"
                let expectedSelectedPaneTitle: String
                switch expectedSelectedTabRawValue {
                case "menu":
                    expectedSelectedPaneTitle = NSLocalizedString("Menu", comment: "")
                case "types", "type":
                    expectedSelectedPaneTitle = NSLocalizedString("1086.label", tableName: "Preferences", bundle: .main, value: "Type", comment: "")
                case "actions", "action":
                    expectedSelectedPaneTitle = NSLocalizedString("Action", comment: "")
                case "shortcuts", "shortcut":
                    expectedSelectedPaneTitle = NSLocalizedString("1366.title", tableName: "Preferences", bundle: .main, value: "Shortcuts", comment: "")
                case "updates", "update":
                    expectedSelectedPaneTitle = NSLocalizedString("Updates", comment: "")
                default:
                    expectedSelectedPaneTitle = NSLocalizedString("General", comment: "")
                }
                let expectedSelectedToolbarItemSuffix: String
                switch expectedSelectedTabRawValue {
                case "type": expectedSelectedToolbarItemSuffix = "types"
                case "action": expectedSelectedToolbarItemSuffix = "actions"
                case "shortcut": expectedSelectedToolbarItemSuffix = "shortcuts"
                case "update": expectedSelectedToolbarItemSuffix = "updates"
                default: expectedSelectedToolbarItemSuffix = expectedSelectedTabRawValue
                }
                let layoutHeightWithinExpectedBounds = window.screen?.visibleFrame.contains(window.frame) == true
                let appIsActive = currentApplication.isActive || NSApp.isActive
                report = [
                    "appIsActive": appIsActive,
                    "keyWindowTitle": NSApp.keyWindow?.title as Any,
                    "mainWindowTitle": NSApp.mainWindow?.title as Any,
                    "title": window.title,
                    "frameAutosaveName": window.frameAutosaveName,
                    "titleVisibility": self.debugPreferencesWindowTitleVisibilityName(window.titleVisibility),
                    "titlebarAppearsTransparent": window.titlebarAppearsTransparent,
                    "isMovableByWindowBackground": window.isMovableByWindowBackground,
                    "toolbarStyle": self.debugToolbarStyleName(window.toolbarStyle),
                    "styleMasks": self.debugWindowStyleMaskNames(window.styleMask),
                    "isVisible": window.isVisible,
                    "isKeyWindow": window.isKeyWindow,
                    "isMainWindow": window.isMainWindow,
                    "frame": [
                        "x": window.frame.origin.x,
                        "y": window.frame.origin.y,
                        "width": window.frame.size.width,
                        "height": window.frame.size.height
                    ],
                    "contentSize": [
                        "width": window.contentLayoutRect.size.width,
                        "height": window.contentLayoutRect.size.height
                    ],
                    "selectedPaneTitle": SwiftUIPreferencesWindowController.shared.debugSelectedTabTitle() as Any,
                    "expectedPaneTitles": expectedPaneTitles,
                    "configuredPaneTitles": configuredPaneTitles,
                    "configuredPaneTitlesMatchExpected": configuredPaneTitles == expectedPaneTitles,
                    "shellSnapshot": shellSnapshot,
                    "visiblePaneTitles": visiblePaneTitles,
                    "visiblePaneIconSources": visiblePaneIconSources,
                    "expectedPaneIconSources": expectedPaneIconSources,
                    "visibleTextValues": visibleTextValues,
                    "allExpectedPaneTitlesVisible": visiblePaneTitles == expectedPaneTitles,
                    "layoutHeightWithinExpectedBounds": layoutHeightWithinExpectedBounds,
                    "matchesExpected": window.title == expectedSelectedPaneTitle
                        && appIsActive
                        && window.frameAutosaveName.isEmpty
                        && self.debugToolbarStyleName(window.toolbarStyle) == "preference"
                        && window.isKeyWindow
                        && window.isMainWindow
                        && configuredPaneTitles == expectedPaneTitles
                        && visiblePaneTitles == expectedPaneTitles
                        && visiblePaneIconSources == expectedPaneIconSources
                        && (shellSnapshot["selectedPaneTitle"] as? String) == expectedSelectedPaneTitle
                        && (shellSnapshot["windowTitle"] as? String) == expectedSelectedPaneTitle
                        && (shellSnapshot["selectedToolbarItemIdentifier"] as? String)?.hasSuffix(expectedSelectedToolbarItemSuffix) == true
                        && (shellSnapshot["toolbarAllowsUserCustomization"] as? Bool) == false
                        && (shellSnapshot["toolbarAutosavesConfiguration"] as? Bool) == false
                        && (shellSnapshot["miniaturizeButtonEnabled"] as? Bool) == false
                        && (shellSnapshot["zoomButtonEnabled"] as? Bool) == false
                        && layoutHeightWithinExpectedBounds
                ]
            } else {
                report["error"] = "Preferences window not available"
                report["matchesExpected"] = false
            }

            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }

            debugTerminateApplication()
        }
    }

    private func runDebugPreferencesReopenSelectionReport() {
        let controller = SwiftUIPreferencesWindowController.shared
        let settleDelay = debugOneShotDoubleValue(forKey: "debugPreferencesReopenSelectionReportSettleDelay") ?? 0.25
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPreferencesReopenSelectionReportPath")
            ?? "/tmp/clipmenu-preferences-reopen-selection-report.json")
        let expectedPaneTitles = debugExpectedPreferencePaneTitles()
        let expectedInitialPaneTitle = controller.debugSelectedTabTitle()
        let expectedUpdatesPaneTitle = expectedPaneTitles.last

        showPreferencePanel(nil)

        DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
            let initialSelectedPaneTitle = controller.debugSelectedTabTitle()
            controller.debugSelectTab(rawValue: "updates")
            let mutatedSelectedPaneTitle = controller.debugSelectedTabTitle()
            controller.close()

            DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
                self.showPreferencePanel(nil)

                DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
                    let reopenedSelectedPaneTitle = controller.debugSelectedTabTitle()
                    let report: [String: Any] = [
                        "initialSelectedPaneTitle": initialSelectedPaneTitle as Any,
                        "mutatedSelectedPaneTitle": mutatedSelectedPaneTitle as Any,
                        "reopenedSelectedPaneTitle": reopenedSelectedPaneTitle as Any,
                        "matchesExpected": initialSelectedPaneTitle == expectedInitialPaneTitle
                            && mutatedSelectedPaneTitle == expectedUpdatesPaneTitle
                            && reopenedSelectedPaneTitle == expectedUpdatesPaneTitle
                    ]

                    if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                        try? data.write(to: reportURL, options: .atomic)
                    }

                    debugTerminateApplication()
                }
            }
        }
    }

