                        let expectedMode = expected.selectionTag == 1
                            ? NSLocalizedString("File Type Code", comment: "")
                            : NSLocalizedString("File Extension", comment: "")
                        let trimmedValue = expected.value.trimmingCharacters(in: .whitespacesAndNewlines)
                        let displayValue = trimmedValue.isEmpty ? expected.defaultValue : trimmedValue
                        let expectedSummary = expected.selectionTag == 1
                            ? String(format: NSLocalizedString("Currently resolving %@ icons with HFS code '%@'.", comment: ""), expected.id, displayValue)
