                ], "icons.controlTitles")
                require(iconUnitTitle == NSLocalizedString("711.title", tableName: "Preferences", bundle: .main, value: "pixel", comment: ""), "icons.unitTitle")
                require(imageToggleTitle == NSLocalizedString("737.title", tableName: "Preferences", bundle: .main, value: "Show Image", comment: ""), "images.toggleTitle")
                require(imagePreviewTitle == NSLocalizedString("Current Thumbnail Frame", comment: ""), "images.previewTitle")
                require(imageDimensionBadges == expectedImageDimensionBadges, "images.dimensionBadges")
                require(iconToggleTitle == NSLocalizedString("934.title", tableName: "Preferences", bundle: .main, value: "Show Icon in the Menu", comment: ""), "icons.toggleTitle")
                require(iconPreviewTitle == NSLocalizedString("Current Icon Size", comment: ""), "icons.previewTitle")
