                require(thumbnailHeight == expectedThumbnailHeight, "images.state.thumbnailHeight")
                require(fileTypeIconsSectionTitle == NSLocalizedString("File Type Icons", comment: ""), "fileTypeIcons.sectionTitle")
                require(mappingSelectionTags.allSatisfy { $0 == 0 || $0 == 1 }, "fileTypeIcons.mappingSelectionTags")
                require(rowTitles == expectedRowTitles, "fileTypeIcons.rowTitles")
                require(mappingsMatchExpected, "fileTypeIcons.mappings")
                require(customMappingCount == mappingDefaultFlags.filter { !$0 }.count, "fileTypeIcons.customMappingCount")
                require(hfsMappingCount == mappingSelectionTags.filter { $0 == 1 }.count, "fileTypeIcons.hfsMappingCount")

                let matchesExpected = mismatchReasons.isEmpty

                report = [
                    "title": window.title,
                    "toolbarStyle": self.debugToolbarStyleName(window.toolbarStyle),
                    "isVisible": window.isVisible,
                    "selectedPaneTitle": selectedPaneTitle as Any,
                    "paneSnapshot": paneSnapshot,
                    "mismatchReasons": mismatchReasons,
                    "matchesExpected": matchesExpected
                ]
            } else {
                report["error"] = "Preferences window not available"
                report["matchesExpected"] = false
            }

            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
        }
    }

    private func runDebugSnippetsPreferencesReport() {
        showPreferencePanel(nil)
        SwiftUIPreferencesWindowController.shared.debugSelectTab(rawValue: "general")

        let settleDelay = debugOneShotDoubleValue(forKey: "debugSnippetsPreferencesReportSettleDelay") ?? 0.25
        DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
            let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetsPreferencesReportPath")
                ?? "/tmp/clipmenu-snippets-preferences-report.json")
