                let rowLabel = paneSnapshot["rowLabel"] as? String
                let previewLabel = paneSnapshot["previewLabel"] as? String
                let pickerTitles = paneSnapshot["pickerTitles"] as? [String] ?? []
                let selectedPosition = paneSnapshot["selectedPosition"] as? Int ?? -1
                let options = paneSnapshot["options"] as? [[String: Any]] ?? []
                let optionTitles = options.compactMap { $0["title"] as? String }
                let optionDetails = options.compactMap { $0["detail"] as? String }
                let optionPreviewRows = options.compactMap { $0["previewRows"] as? [String] }
                let optionSelectedStates = options.compactMap { $0["selected"] as? Bool }
                let selectedOptionCount = options.filter { ($0["selected"] as? Bool) == true }.count
                let expectedPickerTitles = [
                    NSLocalizedString("907.title", tableName: "Preferences", bundle: .main, value: "None", comment: ""),
                    NSLocalizedString("908.title", tableName: "Preferences", bundle: .main, value: "Above the clipboard history", comment: ""),
                    NSLocalizedString("909.title", tableName: "Preferences", bundle: .main, value: "Below the clipboard history", comment: "")
