    private func runDebugUpdatesPreferencesReport() {
        showPreferencePanel(nil)
        SwiftUIPreferencesWindowController.shared.debugSelectTab(rawValue: "updates")

        let settleDelay = debugOneShotDoubleValue(forKey: "debugUpdatesPreferencesReportSettleDelay") ?? 0.25
        DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
            let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugUpdatesPreferencesReportPath")
                ?? "/tmp/clipmenu-updates-preferences-report.json")
            var report: [String: Any] = [:]

            if let window = SwiftUIPreferencesWindowController.shared.window {
                let paneSnapshot = CMUpdatesPreferencesSnapshotForDebug()
                let selectedPaneTitle = SwiftUIPreferencesWindowController.shared.debugSelectedTabTitle()
                let controlTitles = paneSnapshot["controlTitles"] as? [String] ?? []
                let intervalTitles = paneSnapshot["intervalTitles"] as? [String] ?? []
                let sectionTitles = paneSnapshot["sectionTitles"] as? [String] ?? []
                let states = paneSnapshot["states"] as? [String: Any] ?? [:]
                let statusActionTitle = paneSnapshot["statusActionTitle"] as? String ?? ""
                let automaticChecks = states["automaticChecks"] as? Bool ?? false
                let interval = states["interval"] as? Int ?? 86_400
                let visibleIntervalSelection = states["visibleIntervalSelection"] as? Int ?? 86_400
                let showsImportedIntervalNotice = states["showsImportedIntervalNotice"] as? Bool ?? false
                let importedIntervalNoticeTitle = states["importedIntervalNoticeTitle"] as? String ?? ""
                let hasFeedURL = states["hasFeedURL"] as? Bool ?? false
                let isChecking = states["isChecking"] as? Bool ?? false
                let preReleases = states["preReleases"] as? Bool ?? false
                let availability = states["availability"] as? [String: Bool] ?? [:]
                let expectedHasFeedURL = UpdateCoordinator.shared.feedURL != nil
                let expectedIsChecking = UpdateCoordinator.shared.isChecking
                let expectedFeedStatusTitle: String = {
                    guard UpdateCoordinator.shared.isConfiguredForUpdates else {
                        return NSLocalizedString("Unavailable", comment: "")
                    }
                    return preReleases
                        ? NSLocalizedString("Pre-release", comment: "")
                        : NSLocalizedString("Stable", comment: "")
                }()
                let expectedCheckingStatusTitle: String = {
                    guard UpdateCoordinator.shared.isConfiguredForUpdates else {
                        return NSLocalizedString("Unavailable", comment: "")
                    }
                    if isChecking {
                        return NSLocalizedString("Update in progress", comment: "")
                    }
                    return automaticChecks
                        ? NSLocalizedString("Automatic checks on", comment: "")
                        : NSLocalizedString("Manual only", comment: "")
                }()
                let expectedLastCheckedDisplay = UpdateCoordinator.shared.lastCheckDate.map { date in
                    let formatter = DateFormatter()
                    formatter.dateStyle = .medium
                    formatter.timeStyle = .short
                    return formatter.string(from: date)
                } ?? CMLocalizedModernString("Never checked", japanese: "未確認")
                let expectedControlTitles = [
                    NSLocalizedString("1337.title", tableName: "Preferences", bundle: .main, value: "Automatically check for updates:", comment: ""),
                    NSLocalizedString("1426.title", tableName: "Preferences", bundle: .main, value: "Include pre-releases", comment: ""),
                    NSLocalizedString("Automatically download and install updates", comment: ""),
                    NSLocalizedString("1279.title", tableName: "Preferences", bundle: .main, value: "Time interval", comment: ""),
                    NSLocalizedString("1331.title", tableName: "Preferences", bundle: .main, value: "Check Now", comment: "")
                ]
                let expectedAvailability = CMUpdatePreferencesAvailabilityReport(
                    automaticChecks: automaticChecks,
                    feedURLPresent: expectedHasFeedURL,
                    isChecking: expectedIsChecking,
                    configurationAvailable: UpdateCoordinator.shared.isConfiguredForUpdates,
                    canCheckForUpdates: UpdateCoordinator.shared.canCheckForUpdates
                )
                let matchesExpected = window.title == (paneSnapshot["paneTitle"] as? String)
                    && self.debugToolbarStyleName(window.toolbarStyle) == "preference"
                    && window.isVisible
                    && selectedPaneTitle == (paneSnapshot["paneTitle"] as? String)
                    && sectionTitles == [
                        NSLocalizedString("Updates", comment: ""),
                        NSLocalizedString("Status", comment: "")
                    ]
                    && controlTitles == expectedControlTitles
                    && statusActionTitle == NSLocalizedString("1331.title", tableName: "Preferences", bundle: .main, value: "Check Now", comment: "")
                    && intervalTitles == CMVisibleUpdateIntervalOptions().map { $0.title }
                    && visibleIntervalSelection == CMVisibleUpdateIntervalSelectionValue(for: interval)
                    && showsImportedIntervalNotice == (CMVisibleUpdateIntervalOptions().contains(where: { $0.value == interval }) == false)
                    && importedIntervalNoticeTitle == (showsImportedIntervalNotice ? CMImportedUpdateIntervalNoticeTitle(for: interval) : "")
                    && hasFeedURL == expectedHasFeedURL
                    && isChecking == expectedIsChecking
                    && availability == expectedAvailability
                    && (states["checkingStatusTitle"] as? String) == expectedCheckingStatusTitle
                    && (states["feedStatusTitle"] as? String) == expectedFeedStatusTitle
                    && (states["lastCheckedDisplay"] as? String) == expectedLastCheckedDisplay

                report = [
                    "title": window.title,
                    "toolbarStyle": self.debugToolbarStyleName(window.toolbarStyle),
                    "isVisible": window.isVisible,
                    "selectedPaneTitle": selectedPaneTitle as Any,
                    "paneSnapshot": paneSnapshot,
                    "matchesExpected": matchesExpected
                ]
            } else {
                report["error"] = "Preferences window not available"
                report["matchesExpected"] = false
            }

            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }

            debugTerminateApplication()
        }
    }

    private func runDebugGeneralPreferencesReport() {
