    @discardableResult
    private func populateSnippetStoreForDebugWorkflowSeed(
        persistReset: Bool,
        persistSeededState: Bool = false
    ) -> (qaFolderID: UUID, docsFolderID: UUID, greetingSnippetID: UUID?) {
        let snippetStore = SnippetFileStore.shared
        snippetStore.folders = []
        snippetStore.selectedFolderIDs = []
        snippetStore.selectedSnippetIDs = []

        if persistReset {
            snippetStore.save()
            snippetStore.reload()
        }

        let qaFolderID = snippetStore.addFolder()
        if let qaIndex = snippetStore.folders.firstIndex(where: { $0.id == qaFolderID }) {
            var qaFolder = snippetStore.folders[qaIndex]
            qaFolder.title = "QA"
            snippetStore.updateFolder(id: qaFolderID, to: qaFolder)
        }

        snippetStore.selectedFolderIDs = [qaFolderID]
        snippetStore.notePrimaryFolder(qaFolderID)
        let greetingSnippetID = snippetStore.addSnippet()
        if let greetingSnippetID,
           let qaIndex = snippetStore.folders.firstIndex(where: { $0.id == qaFolderID }),
           let snippetIndex = snippetStore.folders[qaIndex].snippets.firstIndex(where: { $0.id == greetingSnippetID }) {
            var greeting = snippetStore.folders[qaIndex].snippets[snippetIndex]
            greeting.title = "Greeting"
            greeting.content = "Hello from snippet"
            snippetStore.updateSnippet(folderID: qaFolderID, snippetID: greetingSnippetID, to: greeting)
        }

        let docsFolderID = snippetStore.addFolder()
        if let docsIndex = snippetStore.folders.firstIndex(where: { $0.id == docsFolderID }) {
            var docsFolder = snippetStore.folders[docsIndex]
            docsFolder.title = "Docs"
            snippetStore.updateFolder(id: docsFolderID, to: docsFolder)
        }

        if let greetingSnippetID {
            snippetStore.selectedFolderIDs = [qaFolderID]
            snippetStore.notePrimaryFolder(qaFolderID)
            snippetStore.selectedSnippetIDs = [greetingSnippetID]
            snippetStore.notePrimarySnippet(greetingSnippetID)
        }

        if persistSeededState {
            snippetStore.save()
            snippetStore.reload()
            snippetStore.selectedFolderIDs = [qaFolderID]
            snippetStore.notePrimaryFolder(qaFolderID)
            if let greetingSnippetID {
                snippetStore.selectedSnippetIDs = [greetingSnippetID]
                snippetStore.notePrimarySnippet(greetingSnippetID)
            }
        }

        return (qaFolderID: qaFolderID, docsFolderID: docsFolderID, greetingSnippetID: greetingSnippetID)
    }

