        let settleDelay = debugOneShotDoubleValue(forKey: "debugSnippetEditorWindowReportSettleDelay") ?? 0.25
        let requestedSearchScopeRawValue = debugOneShotStringValue(forKey: "debugSnippetEditorWindowReportSearchScope")
