            let requestedSelectionModeApplied = self.applyDebugSnippetEditorSelectionModeIfNeeded(requestedSelectionMode)
            let writeReport = {
                let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetEditorWindowReportPath")
