                let browserTextAppearance = paneSnapshot["browserTextAppearance"] as? [String: [String: Any]] ?? [:]
                let folderBrowserStructure = paneSnapshot["folderBrowserStructure"] as? [String: Any] ?? [:]
                let folderActionBarIconSources = paneSnapshot["folderActionBarIconSources"] as? [String: String] ?? [:]
                let folderActionBarStates = paneSnapshot["folderActionBarStates"] as? [String: Bool] ?? [:]
                let expectedFolderActionBarIconSources = [
                    NSLocalizedString("Add Folder", comment: ""): "legacyTemplate",
                    NSLocalizedString("Delete Folder", comment: ""): "legacyTemplate",
                    NSLocalizedString("Enable/Disable Folder", comment: ""): "legacyTemplate",
                    NSLocalizedString("Snippet Actions", comment: ""): "legacyTemplate"
                ]
                let snippetActionsMenuTitles = paneSnapshot["snippetActionsMenuTitles"] as? [String] ?? []
                let snippetActionsMenuStates = paneSnapshot["snippetActionsMenuStates"] as? [String: Bool] ?? [:]
                let expectedSnippetActionsMenuTitles = [
                    NSLocalizedString("Import Snippets...", comment: ""),
                    NSLocalizedString("Export Snippets...", comment: "")
                ]
                let rowIconSources = paneSnapshot["rowIconSources"] as? [String: String] ?? [:]
                let expectedRowIconSources = [
                    "folder": "workspaceGenericFolderIcon",
                    "snippet": "workspaceClippingTextIcon"
                ]
                let footerButtonIconSources = paneSnapshot["footerButtonIconSources"] as? [String: String] ?? [:]
                let expectedFooterButtonIconSources: [String: String] = [:]
                let snippetStore = SnippetFileStore.shared
                let expectedSnippetActionsMenuStates = [
                    NSLocalizedString("Import Snippets...", comment: ""): true,
                    NSLocalizedString("Export Snippets...", comment: ""): !snippetStore.folders.isEmpty
                ]
                let expectedFolderActionBarStates = [
                    NSLocalizedString("Add Folder", comment: ""): true,
                    NSLocalizedString("Delete Folder", comment: ""): !snippetStore.selectedFolderIDs.isEmpty,
                    NSLocalizedString("Enable/Disable Folder", comment: ""): !snippetStore.selectedFolderIDs.isEmpty,
                    NSLocalizedString("Snippet Actions", comment: ""): true
