                    NSLocalizedString("Delete Snippet", comment: ""): true,
                    NSLocalizedString("Enable/Disable Snippet", comment: ""): !snippetStore.selectedSnippetIDs.isEmpty
                ]
                let selectedFolder = snippetStore.selectedFolderIndex.flatMap {
                    snippetStore.folders.indices.contains($0) ? snippetStore.folders[$0] : nil
