                        return nil
                    }
                    return snippetStore.folders[folderIndex].snippets[snippetIndex]
                }()
                let effectiveSelectedSnippet: Snippet? = {
                    guard snippetStore.selectedFolderIDs.count == 1,
                          snippetStore.selectedSnippetIDs.count == 1 else {
                        return nil
                    }
                    return selectedSnippet
                }()
                let visibleSnippetCount: Int = {
                    guard let folderIndex = snippetStore.selectedFolderIndex,
                          snippetStore.folders.indices.contains(folderIndex) else {
                        return 0
                    }
                    let normalizedScopeRawValue = self.snippetSearchScope(rawValue: requestedSearchScopeRawValue ?? "all")
                    let trimmedQuery = requestedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
                    let snippets = Array(snippetStore.folders[folderIndex].snippets.enumerated())
                    guard normalizedScopeRawValue != "all" || !trimmedQuery.isEmpty else {
                        return snippets.count
                    }
                    if trimmedQuery.isEmpty {
                        return snippets.count
                    }
                    return snippets.filter { entry in
                        switch normalizedScopeRawValue {
                        case "title":
                            return entry.element.title.localizedCaseInsensitiveContains(trimmedQuery)
                        case "content":
                            return entry.element.content.localizedCaseInsensitiveContains(trimmedQuery)
                        default:
                            return String(entry.offset).localizedCaseInsensitiveContains(trimmedQuery)
                                || entry.element.title.localizedCaseInsensitiveContains(trimmedQuery)
                                || entry.element.content.localizedCaseInsensitiveContains(trimmedQuery)
                        }
                    }.count
                }()
