                            "fontSize": 13
                        ]
                    }
                    if visibleSnippetCount > 0 {
                        appearance["snippetTable"] = [
                            "fontName": "LucidaGrande",
                            "fontSize": 13
                        ]
                    }
                    return appearance
                }()
                let expectedSearchScopeRawValue = requestedSearchScopeRawValue ?? "all"
                let expectedSearchScopeTitle = self.localizedSnippetSearchScopeTitle(for: expectedSearchScopeRawValue)
                let expectedSnippetListState: [String: String] = {
                    if snippetStore.selectedFolderIDs.count > 1 {
                        return [
                            "mode": "multipleFolders",
                            "systemImage": "checklist",
                            "title": NSLocalizedString("Multiple Folders Selected", comment: ""),
                            "message": NSLocalizedString("Choose a single folder to browse its snippets.", comment: "")
                        ]
                    }
                    if snippetStore.selectedFolderIndex == nil {
                        return [
                            "mode": "noFolder",
                            "systemImage": "sidebar.left",
                            "title": NSLocalizedString("Choose a Folder", comment: ""),
                            "message": NSLocalizedString("Select a folder to browse its snippets.", comment: "")
                        ]
                    }
                    if visibleSnippetCount == 0 {
                        let trimmedQuery = requestedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
                        return [
                            "mode": trimmedQuery.isEmpty ? "noSnippets" : "noMatches",
                            "systemImage": trimmedQuery.isEmpty ? "doc.text" : "magnifyingglass",
                            "title": trimmedQuery.isEmpty ? NSLocalizedString("No Snippets", comment: "") : NSLocalizedString("No Matches", comment: ""),
                            "message": trimmedQuery.isEmpty
                                ? NSLocalizedString("Add a snippet to the selected folder.", comment: "")
                                : NSLocalizedString("Try a different search term.", comment: "")
                        ]
                    }
                    return [
                        "mode": "results",
                        "systemImage": "list.bullet",
                        "title": CMModernLocalizationIsJapanese()
                            ? "\(visibleSnippetCount)件を表示"
                            : (visibleSnippetCount == 1 ? "1 visible" : "\(visibleSnippetCount) visible"),
                            "message": {
                            if let snippetTitle = effectiveSelectedSnippet?.title {
                                return snippetTitle
                            }
                            if let folderTitle = selectedFolder?.title {
                                return folderTitle
                            }
                            return CMLocalizedModernString("No folder selected", japanese: "フォルダ未選択")
                        }()
                    ]
                }()
                let expectedVisibleSnippetTitles: [String] = {
                    guard let folderIndex = snippetStore.selectedFolderIndex,
                          snippetStore.folders.indices.contains(folderIndex) else {
                        return []
                    }
                    let normalizedScopeRawValue = self.snippetSearchScope(rawValue: requestedSearchScopeRawValue ?? "all")
                    let trimmedQuery = requestedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
                    let snippets = Array(snippetStore.folders[folderIndex].snippets.enumerated())
                    let filtered: [Snippet]
                    if trimmedQuery.isEmpty {
                        filtered = snippets.map(\.element)
                    } else {
                        filtered = snippets.compactMap { entry in
                            let matches: Bool
                            switch normalizedScopeRawValue {
                            case "title":
                                matches = entry.element.title.localizedCaseInsensitiveContains(trimmedQuery)
                            case "content":
                                matches = entry.element.content.localizedCaseInsensitiveContains(trimmedQuery)
                            default:
                                matches = String(entry.offset).localizedCaseInsensitiveContains(trimmedQuery)
                                    || entry.element.title.localizedCaseInsensitiveContains(trimmedQuery)
                                    || entry.element.content.localizedCaseInsensitiveContains(trimmedQuery)
                            }
                            return matches ? entry.element : nil
                        }
                    }
                    return filtered.map(\.title)
                }()
                let expectedDetailPaneState: [String: String] = {
                    if snippetStore.selectedFolderIDs.count > 1 {
                        return [
                            "mode": "multipleFolders",
                            "systemImage": "checklist",
                            "title": NSLocalizedString("Multiple Folders Selected", comment: ""),
                            "message": NSLocalizedString("Choose a single folder to browse its snippets.", comment: "")
                        ]
                    }
                    if snippetStore.selectedSnippetIDs.count > 1 {
                        return [
                            "mode": "multipleSnippets",
                            "systemImage": "checklist",
                            "title": NSLocalizedString("Multiple Snippets Selected", comment: ""),
                            "message": NSLocalizedString("Choose a single snippet to edit its content.", comment: "")
                        ]
                    }
                    if effectiveSelectedSnippet == nil {
                        return [
                            "mode": "noSnippet",
                            "systemImage": "doc.text",
                            "title": NSLocalizedString("No Snippet Selected", comment: ""),
                            "message": NSLocalizedString("Choose a snippet to edit its content.", comment: "")
                        ]
                    }
                    return [
                        "mode": "editor",
                        "systemImage": "square.and.pencil",
                        "title": effectiveSelectedSnippet?.title ?? NSLocalizedString("No Snippet Selected", comment: ""),
                        "message": {
                            if let snippetTitle = effectiveSelectedSnippet?.title {
                                return snippetTitle
                            }
                            if let folderTitle = selectedFolder?.title {
                                return folderTitle
                            }
                            return CMLocalizedModernString("No folder selected", japanese: "フォルダ未選択")
