                ]
                } else {
                    report["error"] = "Snippet Editor window not available"
                    report["requestedSearchScopeRawValue"] = requestedSearchScopeRawValue as Any
                    report["requestedSearchScopeApplied"] = requestedSearchScopeApplied
                    report["requestedSearchQuery"] = requestedSearchQuery
                    report["requestedSearchQueryApplied"] = requestedSearchQueryApplied
                    report["requestedSelectionMode"] = requestedSelectionMode as Any
                    report["requestedSelectionModeApplied"] = requestedSelectionModeApplied
                    report["matchesExpected"] = false
                }

                if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                    try? data.write(to: reportURL, options: .atomic)
                }

                debugTerminateApplication()
            }

            let needsExtraSettle = requestedSearchScopeApplied || !requestedSearchQuery.isEmpty || requestedSelectionMode != nil
            if needsExtraSettle {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                    writeReport()
                }
            } else {
                writeReport()
            }
        }
    }

