    private func runDebugSnippetWorkflowReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetWorkflowReportPath")
            ?? "/tmp/clipmenu-snippet-workflow-report.json")
        let snippetStore = SnippetFileStore.shared
        let originalFolders = snippetStore.folders
        let originalSelection = snippetStore.currentSelectionSnapshot()
        let originalInputPasteCommand = defaults.object(forKey: CMPrefInputPasteCommandKey)
        let originalPositionOfSnippets = defaults.object(forKey: CMPrefPositionOfSnippetsKey)

        func topLevelTitles(from menu: NSMenu) -> [String] {
            menu.items.map { $0.isSeparatorItem ? "<separator>" : $0.title }
        }

        defer {
            restoreDefault(originalInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            restoreDefault(originalPositionOfSnippets, forKey: CMPrefPositionOfSnippetsKey)
            snippetStore.folders = originalFolders
            snippetStore.save()
            snippetStore.reload()
            snippetStore.restoreSelectionSnapshot(originalSelection)
            snippetEditorController?.close()
            debugTerminateApplication()
        }

        defaults.set(false, forKey: CMPrefInputPasteCommandKey)
        defaults.set(CMPositionOfSnippets.aboveClips.rawValue, forKey: CMPrefPositionOfSnippetsKey)
        showSnippetEditor(nil)

        let expectedEditorWindowTitle = NSLocalizedString("Snippet Editor", comment: "")
        let editorWindowVisible = snippetEditorController?.window?.isVisible == true
        let editorWindowTitle = snippetEditorController?.window?.title ?? ""
        let seed = populateSnippetStoreForDebugWorkflowSeed(persistReset: true)
        let qaFolderID = seed.qaFolderID
        let docsFolderID = seed.docsFolderID
        let greetingSnippetID = seed.greetingSnippetID

        let folderTitlesAfterAdd = snippetStore.folders.map(\.title)
        let snippetTitlesByFolderAfterAdd = snippetStore.folders.map { $0.snippets.map(\.title) }

        var pastedSnippetText = ""
        if let greetingSnippetID,
           let qaIndex = snippetStore.folders.firstIndex(where: { $0.id == qaFolderID }),
           let snippet = snippetStore.folders[qaIndex].snippets.first(where: { $0.id == greetingSnippetID }) {
            pasteboard.clearContents()
            let item = NSMenuItem(title: "Greeting", action: nil, keyEquivalent: "")
            item.representedObject = SnippetActionReference(
                folderID: qaFolderID,
                snippetID: greetingSnippetID,
                content: snippet.content
            )
            selectSnippet(item)
            pastedSnippetText = pasteboard.string(forType: .string) ?? ""
        }

        if let greetingSnippetID {
            snippetStore.selectedFolderIDs = [qaFolderID]
            snippetStore.notePrimaryFolder(qaFolderID)
            snippetStore.selectedSnippetIDs = [greetingSnippetID]
            snippetStore.notePrimarySnippet(greetingSnippetID)
            snippetStore.toggleSelectedSnippetEnabled()
        }
        let snippetsMenuAfterSnippetDisable = makeSnippetsMenu()
        let qaSubmenuTitlesAfterSnippetDisable = snippetsMenuAfterSnippetDisable.items
            .first(where: { $0.title == "QA" })?
            .submenu?.items.map(\.title) ?? []

        if let greetingSnippetID {
            snippetStore.selectedFolderIDs = [qaFolderID]
            snippetStore.notePrimaryFolder(qaFolderID)
            snippetStore.selectedSnippetIDs = [greetingSnippetID]
            snippetStore.notePrimarySnippet(greetingSnippetID)
            snippetStore.toggleSelectedSnippetEnabled()
        }

        snippetStore.selectedFolderIDs = [qaFolderID]
        snippetStore.notePrimaryFolder(qaFolderID)
        snippetStore.toggleSelectedFolderEnabled()
        let snippetsMenuAfterFolderDisableTitles = makeSnippetsMenu().items.map(\.title)
        snippetStore.toggleSelectedFolderEnabled()

        snippetStore.moveFolders(from: IndexSet(integer: 1), to: 0)

        if let greetingSnippetID {
            snippetStore.moveSnippetForTesting(
                sourceFolderID: qaFolderID,
                snippetID: greetingSnippetID,
                targetFolderID: docsFolderID,
                destinationIndex: 0
            )
        }

        snippetStore.save()
        snippetStore.reload()

        let folderTitlesAfterReload = snippetStore.folders.map(\.title)
        let snippetTitlesByFolderAfterReload = snippetStore.folders.map { $0.snippets.map(\.title) }
        let mainMenuTitlesAfterReload = topLevelTitles(from: makeMainMenu())
        let expectedMainMenuTitlesAfterReload = [
            NSLocalizedString("Snippets", comment: ""),
            "Docs",
            NSLocalizedString("History", comment: ""),
            "<separator>",
            NSLocalizedString("Clear History", comment: ""),
            NSLocalizedString("Edit Snippets...", comment: ""),
            NSLocalizedString("Preferences...", comment: ""),
            "<separator>",
            NSLocalizedString("Quit ClipMenu", comment: "")
        ]

        let report: [String: Any] = [
            "editorWindowVisible": editorWindowVisible,
            "editorWindowTitle": editorWindowTitle,
            "folderTitlesAfterAdd": folderTitlesAfterAdd,
            "snippetTitlesByFolderAfterAdd": snippetTitlesByFolderAfterAdd,
            "pastedSnippetText": pastedSnippetText,
            "qaSubmenuTitlesAfterSnippetDisable": qaSubmenuTitlesAfterSnippetDisable,
            "snippetsMenuTitlesAfterFolderDisable": snippetsMenuAfterFolderDisableTitles,
            "folderTitlesAfterReload": folderTitlesAfterReload,
            "snippetTitlesByFolderAfterReload": snippetTitlesByFolderAfterReload,
            "mainMenuTitlesAfterReload": mainMenuTitlesAfterReload,
            "expectedMainMenuTitlesAfterReload": expectedMainMenuTitlesAfterReload,
            "matchesExpected": editorWindowVisible
                && editorWindowTitle == expectedEditorWindowTitle
                && folderTitlesAfterAdd == ["QA", "Docs"]
                && snippetTitlesByFolderAfterAdd == [["Greeting"], []]
                && pastedSnippetText == "Hello from snippet"
                && qaSubmenuTitlesAfterSnippetDisable.isEmpty
                && !snippetsMenuAfterFolderDisableTitles.contains("QA")
                && folderTitlesAfterReload == ["Docs", "QA"]
                && snippetTitlesByFolderAfterReload == [["Greeting"], []]
                && mainMenuTitlesAfterReload == expectedMainMenuTitlesAfterReload
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

