    private func runDebugSnippetEditorDocumentCommandReport() {
        func flushMainRunLoop() {
            RunLoop.main.run(until: Date(timeIntervalSinceNow: 0.05))
        }

        func fileMenu() -> NSMenu? {
            if NSApp.mainMenu == nil || NSApp.mainMenu?.items.isEmpty != false {
                installMainMenu()
            }
            return NSApp.mainMenu?.items.first(where: { $0.title == NSLocalizedString("File", comment: "") })?.submenu
        }


        func enabledStateMap(for menu: NSMenu, titles: [String]) -> [String: Bool] {
            menu.update()
            return Dictionary(uniqueKeysWithValues: titles.map { title in
                (title, menu.items.first(where: { $0.title == title })?.isEnabled ?? false)
            })
        }

        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetEditorDocumentCommandReportPath")
            ?? "/tmp/clipmenu-snippet-editor-document-command-report.json")
        let fileMenuTitles = [
            NSLocalizedString("Save", comment: ""),
            NSLocalizedString("Save As...", comment: ""),
            NSLocalizedString("Revert", comment: "")
        ]
        var report: [String: Any] = [
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
            return
        }

        let store = SnippetFileStore.shared
        let originalFolders = store.folders

        defer {
            store.folders = originalFolders
            store.save()
            store.reload()
            snippetEditorController?.close()
            debugTerminateApplication()
        }

        if store.folders.isEmpty {
            store.folders = [
                SnippetFolder(
                    title: "Debug Folder",
                    isEnabled: true,
                    snippets: [
                        Snippet(title: "Debug Snippet", content: "Original content", isEnabled: true)
                    ]
                )
            ]
            store.save()
        } else if store.folders[0].snippets.isEmpty {
            var firstFolder = store.folders[0]
            firstFolder.snippets = [Snippet(title: "Debug Snippet", content: "Original content", isEnabled: true)]
            store.updateFolder(id: firstFolder.id, to: firstFolder)
            store.save()
        }

        store.reload()
        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)

        guard let firstFolder = store.folders.first,
              let originalSnippet = firstFolder.snippets.first else {
            let report = ["error": "Snippet fixture not available"]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        store.selectedFolderIDs = [firstFolder.id]
        store.notePrimaryFolder(firstFolder.id)
        store.selectedSnippetIDs = [originalSnippet.id]
        store.notePrimarySnippet(originalSnippet.id)

        let baselineStates = fileMenu().map { enabledStateMap(for: $0, titles: fileMenuTitles) } ?? [:]

        var editedSnippet = originalSnippet
        editedSnippet.content += "\nEdited once"
        store.updateSnippet(folderID: firstFolder.id, snippetID: originalSnippet.id, to: editedSnippet)
        flushMainRunLoop()

        let dirtyStates = fileMenu().map { enabledStateMap(for: $0, titles: fileMenuTitles) } ?? [:]
        let dirtyWindowEdited = snippetEditorController?.window?.isDocumentEdited == true
        let saveHandled = NSApp.sendAction(#selector(self.saveDocument(_:)), to: nil, from: nil)
        flushMainRunLoop()
        let afterSaveStates = fileMenu().map { enabledStateMap(for: $0, titles: fileMenuTitles) } ?? [:]
        let afterSaveWindowEdited = snippetEditorController?.window?.isDocumentEdited == true
        let afterSaveSnippetContent = store.folders.first?.snippets.first?.content ?? ""
        let persistedSaveContent = (try? String(contentsOf: clipMenuApplicationSupportDirectory().appendingPathComponent("snippets.json"), encoding: .utf8)) ?? ""

        var secondEdit = store.folders.first?.snippets.first ?? editedSnippet
        secondEdit.content += "\nEdited twice"
        store.updateSnippet(folderID: firstFolder.id, snippetID: originalSnippet.id, to: secondEdit)
        flushMainRunLoop()

        let secondDirtyStates = fileMenu().map { enabledStateMap(for: $0, titles: fileMenuTitles) } ?? [:]
        let revertHandled = NSApp.sendAction(#selector(self.revertDocumentToSaved(_:)), to: nil, from: nil)
        flushMainRunLoop()
        let afterRevertStates = fileMenu().map { enabledStateMap(for: $0, titles: fileMenuTitles) } ?? [:]
        let afterRevertWindowEdited = snippetEditorController?.window?.isDocumentEdited == true
        let afterRevertSnippetContent = store.folders.first?.snippets.first?.content ?? ""
        let expectedBaselineStates = [
            NSLocalizedString("Save", comment: ""): false,
            NSLocalizedString("Save As...", comment: ""): true,
            NSLocalizedString("Revert", comment: ""): false
        ]
        let expectedDirtyStates = [
            NSLocalizedString("Save", comment: ""): true,
            NSLocalizedString("Save As...", comment: ""): true,
            NSLocalizedString("Revert", comment: ""): true
        ]
        let matchesExpected =
            baselineStates == expectedBaselineStates
            && dirtyStates == expectedDirtyStates
            && dirtyWindowEdited
            && saveHandled
            && afterSaveStates == expectedBaselineStates
            && afterSaveWindowEdited == false
            && store.hasUnsavedChanges == false
            && persistedSaveContent.contains("Edited once")
            && secondDirtyStates == expectedDirtyStates
            && revertHandled
            && afterRevertStates == expectedBaselineStates
            && afterRevertWindowEdited == false
            && afterRevertSnippetContent == afterSaveSnippetContent

        report.merge([
            "baselineStates": baselineStates,
            "dirtyStates": dirtyStates,
            "dirtyWindowEdited": dirtyWindowEdited,
            "saveHandled": saveHandled,
            "afterSaveStates": afterSaveStates,
            "afterSaveWindowEdited": afterSaveWindowEdited,
            "afterSaveHasUnsavedChanges": store.hasUnsavedChanges,
            "afterSaveSnippetContent": afterSaveSnippetContent,
            "persistedSaveContainsEditedContent": persistedSaveContent.contains("Edited once"),
            "secondDirtyStates": secondDirtyStates,
            "revertHandled": revertHandled,
            "afterRevertStates": afterRevertStates,
            "afterRevertWindowEdited": afterRevertWindowEdited,
            "afterRevertHasUnsavedChanges": store.hasUnsavedChanges,
            "afterRevertSnippetContent": afterRevertSnippetContent,
            "revertRestoredSavedContent": afterRevertSnippetContent == afterSaveSnippetContent,
            "matchesExpected": matchesExpected
        ]) { _, new in new }

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugSnippetPersistenceTimingReport() {
        func flushMainRunLoop() {
            RunLoop.main.run(until: Date(timeIntervalSinceNow: 0.05))
        }

        func persistedFolders(at url: URL) -> [SnippetFolder] {
            guard let data = try? Data(contentsOf: url),
                  let decoded = try? JSONDecoder().decode([SnippetFolder].self, from: data) else {
                return []
            }
            return decoded
        }

        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetPersistenceTimingReportPath")
            ?? "/tmp/clipmenu-snippet-persistence-timing-report.json")
        var report: [String: Any] = [
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
            return
        }

        let snippetStore = SnippetFileStore.shared
        let originalFolders = snippetStore.folders
        let originalSelection = snippetStore.currentSelectionSnapshot()
        let snippetsURL = clipMenuApplicationSupportDirectory().appendingPathComponent("snippets.json")

        defer {
            snippetStore.folders = originalFolders
            snippetStore.restoreSelectionSnapshot(originalSelection)
            snippetStore.save()
            snippetStore.reload()
            snippetEditorController?.close()
            debugTerminateApplication()
        }

        let baselineFolders = [
            SnippetFolder(
                title: "Persist Folder",
                isEnabled: true,
                snippets: [
                    Snippet(title: "Persist Snippet", content: "Original body", isEnabled: true)
                ]
            ),
            SnippetFolder(
                title: "Second Folder",
                isEnabled: true,
                snippets: [
                    Snippet(title: "Second Snippet", content: "Second body", isEnabled: true)
                ]
            )
        ]

        snippetStore.folders = baselineFolders
        snippetStore.save()
        snippetStore.reload()
        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)

        guard let folder = snippetStore.folders.first,
              let snippet = folder.snippets.first else {
            let report: [String: Any] = [
                "error": "Snippet persistence fixture not available",
                "matchesExpected": false
            ]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        snippetStore.selectedFolderIDs = [folder.id]
        snippetStore.notePrimaryFolder(folder.id)
        snippetStore.selectedSnippetIDs = [snippet.id]
        snippetStore.notePrimarySnippet(snippet.id)

        var editedSnippet = snippet
        editedSnippet.content = "Draft body"
        snippetStore.updateSnippet(folderID: folder.id, snippetID: snippet.id, to: editedSnippet)
        let addedFolderID = snippetStore.addFolder()
        if let addedIndex = snippetStore.folders.firstIndex(where: { $0.id == addedFolderID }) {
            var addedFolder = snippetStore.folders[addedIndex]
            addedFolder.title = "Draft Folder"
            snippetStore.updateFolder(id: addedFolderID, to: addedFolder)
        }
        if snippetStore.folders.count >= 2 {
            let secondFolderID = snippetStore.folders[1].id
            snippetStore.selectedFolderIDs = [secondFolderID]
            snippetStore.notePrimaryFolder(secondFolderID)
            snippetStore.toggleSelectedFolderEnabled()
        }
        if snippetStore.folders.count >= 3 {
            snippetStore.moveFolders(from: IndexSet(integer: 2), to: 1)
        }
        flushMainRunLoop()

        let beforeClosePersistedFolders = persistedFolders(at: snippetsURL)
        let beforeCloseFolderTitles = beforeClosePersistedFolders.map(\.title)
        let beforeCloseFolderEnabledStates = beforeClosePersistedFolders.map(\.isEnabled)
        let beforeCloseSnippetContent = beforeClosePersistedFolders.first?.snippets.first?.content ?? ""
        let inMemoryFolderTitlesBeforeClose = snippetStore.folders.map(\.title)
        let inMemoryFolderEnabledStatesBeforeClose = snippetStore.folders.map(\.isEnabled)
        let inMemorySnippetContentBeforeClose = snippetStore.folders.first?.snippets.first?.content ?? ""
        let beforeCloseHasUnsavedChanges = snippetStore.hasUnsavedChanges
        let inMemoryDiffersBeforeClose = beforeCloseFolderTitles != inMemoryFolderTitlesBeforeClose
            || beforeCloseFolderEnabledStates != inMemoryFolderEnabledStatesBeforeClose
            || beforeCloseSnippetContent != inMemorySnippetContentBeforeClose

        snippetEditorController?.close()
        flushMainRunLoop()

        let afterClosePersistedFolders = persistedFolders(at: snippetsURL)
        let afterCloseFolderTitles = afterClosePersistedFolders.map(\.title)
        let afterCloseFolderEnabledStates = afterClosePersistedFolders.map(\.isEnabled)
        let afterCloseSnippetContent = afterClosePersistedFolders.first?.snippets.first?.content ?? ""

        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)
        flushMainRunLoop()

        guard let reopenedFolder = snippetStore.folders.first,
              let reopenedSnippet = reopenedFolder.snippets.first else {
            let report: [String: Any] = [
                "error": "Snippet persistence fixture missing after reopen",
                "matchesExpected": false
            ]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        snippetStore.selectedFolderIDs = [reopenedFolder.id]
        snippetStore.notePrimaryFolder(reopenedFolder.id)
        snippetStore.selectedSnippetIDs = [reopenedSnippet.id]
        snippetStore.notePrimarySnippet(reopenedSnippet.id)

        var terminationSnippet = reopenedSnippet
        terminationSnippet.content = "Termination draft"
        snippetStore.updateSnippet(folderID: reopenedFolder.id, snippetID: reopenedSnippet.id, to: terminationSnippet)
        flushMainRunLoop()

        let beforeTerminationPersistedFolders = persistedFolders(at: snippetsURL)
        let beforeTerminationSnippetContent = beforeTerminationPersistedFolders.first?.snippets.first?.content ?? ""

        CMFlushEditorStoresForTermination()
        flushMainRunLoop()

        let afterTerminationPersistedFolders = persistedFolders(at: snippetsURL)
        let afterTerminationSnippetContent = afterTerminationPersistedFolders.first?.snippets.first?.content ?? ""
        let deferredUntilClose = beforeCloseFolderTitles == ["Persist Folder", "Second Folder"]
            && beforeCloseFolderEnabledStates == [true, true]
            && beforeCloseSnippetContent == "Original body"
            && inMemoryFolderTitlesBeforeClose == ["Persist Folder", "Draft Folder", "Second Folder"]
            && inMemoryFolderEnabledStatesBeforeClose == [true, true, false]
            && inMemorySnippetContentBeforeClose == "Draft body"
            && afterCloseFolderTitles == ["Persist Folder", "Draft Folder", "Second Folder"]
            && afterCloseFolderEnabledStates == [true, true, false]
            && afterCloseSnippetContent == "Draft body"
        let terminationFlushPersistsUnsavedEdits = beforeTerminationSnippetContent == "Draft body"
            && afterTerminationSnippetContent == "Termination draft"
        let matchesExpected = beforeCloseHasUnsavedChanges
            && inMemoryDiffersBeforeClose
            && deferredUntilClose
            && terminationFlushPersistsUnsavedEdits

        report.merge([
            "baselineFolderTitles": baselineFolders.map(\.title),
            "baselineFolderEnabledStates": baselineFolders.map(\.isEnabled),
            "inMemoryFolderTitlesBeforeClose": inMemoryFolderTitlesBeforeClose,
            "inMemoryFolderEnabledStatesBeforeClose": inMemoryFolderEnabledStatesBeforeClose,
            "beforeClosePersistedFolderTitles": beforeCloseFolderTitles,
            "beforeClosePersistedFolderEnabledStates": beforeCloseFolderEnabledStates,
            "beforeCloseSnippetContent": beforeCloseSnippetContent,
            "inMemorySnippetContentBeforeClose": inMemorySnippetContentBeforeClose,
            "beforeCloseHasUnsavedChanges": beforeCloseHasUnsavedChanges,
            "inMemoryDiffersBeforeClose": inMemoryDiffersBeforeClose,
            "afterClosePersistedFolderTitles": afterCloseFolderTitles,
            "afterClosePersistedFolderEnabledStates": afterCloseFolderEnabledStates,
            "afterCloseSnippetContent": afterCloseSnippetContent,
            "beforeTerminationSnippetContent": beforeTerminationSnippetContent,
            "afterTerminationSnippetContent": afterTerminationSnippetContent,
            "deferredUntilClose": deferredUntilClose,
            "terminationFlushPersistsUnsavedEdits": terminationFlushPersistsUnsavedEdits,
            "matchesExpected": matchesExpected
        ]) { _, new in new }

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

