    private func runDebugSnippetEditorSelectionPersistenceReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetEditorSelectionPersistenceReportPath")
            ?? "/tmp/clipmenu-snippet-editor-selection-persistence-report.json")
        let store = SnippetFileStore.shared
        let originalFolders = store.folders
        let originalSelectionSnapshot = store.currentSelectionSnapshot()

        defer {
            store.folders = originalFolders
            store.restoreSelectionSnapshot(originalSelectionSnapshot)
            store.save()
            store.reload()
            snippetEditorController?.close()
            debugTerminateApplication()
        }

        let seed = populateSnippetStoreForDebugWorkflowSeed(persistReset: true)
        let targetFolderID = seed.docsFolderID
        store.selectedFolderIDs = [targetFolderID]
        store.notePrimaryFolder(targetFolderID)
        let targetSnippetID = store.addSnippet()
        if let targetSnippetID,
           let folderIndex = store.folders.firstIndex(where: { $0.id == targetFolderID }),
           let snippetIndex = store.folders[folderIndex].snippets.firstIndex(where: { $0.id == targetSnippetID }) {
            var snippet = store.folders[folderIndex].snippets[snippetIndex]
            snippet.title = "Second Snippet"
            snippet.content = "Two"
            store.updateSnippet(folderID: targetFolderID, snippetID: targetSnippetID, to: snippet)
        }
        store.save()
        store.reload()
        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)

        guard let targetFolderIndex = store.folders.firstIndex(where: { $0.id == targetFolderID }),
              let targetSnippet = targetSnippetID.flatMap({ snippetID in
                  store.folders[targetFolderIndex].snippets.first(where: { $0.id == snippetID })
              }) else {
            let report: [String: Any] = [
                "error": "Selection fixture not available",
                "matchesExpected": false
            ]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        let targetFolder = store.folders[targetFolderIndex]
        store.selectedFolderIDs = [targetFolder.id]
        store.notePrimaryFolder(targetFolder.id)
        store.selectedSnippetIDs = [targetSnippet.id]
        store.notePrimarySnippet(targetSnippet.id)

        let beforeCloseSnapshot = store.currentSelectionSnapshot()
        let beforeCloseTitles: [String: Any] = [
            "folderTitle": targetFolder.title,
            "snippetTitle": targetSnippet.title
        ]

        snippetEditorController?.close()
        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)

        let afterReopenSnapshot = store.currentSelectionSnapshot()
        let reopenedFolderTitle = store.selectedFolderIndex.map { store.folders[$0].title }
        let reopenedSnippetTitle = {
            guard let folderIndex = store.selectedFolderIndex,
                  let snippetIndex = store.selectedSnippetIndex else { return nil as String? }
            return store.folders[folderIndex].snippets[snippetIndex].title
        }()
        let selectionRestored = beforeCloseSnapshot.primarySelectedFolderID == afterReopenSnapshot.primarySelectedFolderID
            && beforeCloseSnapshot.primarySelectedSnippetID == afterReopenSnapshot.primarySelectedSnippetID
            && beforeCloseSnapshot.selectedFolderIDs == afterReopenSnapshot.selectedFolderIDs
            && beforeCloseSnapshot.selectedSnippetIDs == afterReopenSnapshot.selectedSnippetIDs
        let matchesExpected = selectionRestored
            && reopenedFolderTitle == targetFolder.title
            && reopenedSnippetTitle == targetSnippet.title

        let report: [String: Any] = [
            "beforeClose": [
                "selectedFolderIDs": beforeCloseSnapshot.selectedFolderIDs.map(\.uuidString).sorted(),
                "selectedSnippetIDs": beforeCloseSnapshot.selectedSnippetIDs.map(\.uuidString).sorted(),
                "primarySelectedFolderID": beforeCloseSnapshot.primarySelectedFolderID?.uuidString as Any,
                "primarySelectedSnippetID": beforeCloseSnapshot.primarySelectedSnippetID?.uuidString as Any,
                "titles": beforeCloseTitles
            ],
            "afterReopen": [
                "selectedFolderIDs": afterReopenSnapshot.selectedFolderIDs.map(\.uuidString).sorted(),
                "selectedSnippetIDs": afterReopenSnapshot.selectedSnippetIDs.map(\.uuidString).sorted(),
                "primarySelectedFolderID": afterReopenSnapshot.primarySelectedFolderID?.uuidString as Any,
                "primarySelectedSnippetID": afterReopenSnapshot.primarySelectedSnippetID?.uuidString as Any,
                "folderTitle": reopenedFolderTitle as Any,
                "snippetTitle": reopenedSnippetTitle as Any
            ],
            "selectionRestored": selectionRestored,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

