    private func runDebugSnippetEditingGuardReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetEditingGuardReportPath")
            ?? "/tmp/clipmenu-snippet-editing-guard-report.json")
        let store = SnippetFileStore.shared
        let originalFolders = store.folders
        let originalSelection = store.currentSelectionSnapshot()

        let seed = populateSnippetStoreForDebugWorkflowSeed(persistReset: true, persistSeededState: true)
        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)
        store.restoreSelectionSnapshot(.init(
            selectedFolderIDs: [seed.qaFolderID],
            selectedSnippetIDs: seed.greetingSnippetID.map { [$0] } ?? [],
            primarySelectedFolderID: seed.qaFolderID,
            primarySelectedSnippetID: seed.greetingSnippetID
        ))

        let settleDelay = debugOneShotDoubleValue(forKey: "debugSnippetEditingGuardSettleDelay") ?? 0.25
        DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
            CMResetLastAlertForDebug()
            CMSetBypassAlertPresentationForDebug(true)
            let snippetWindow = self.snippetEditorController?.window

            let folderCountBeforeAddFolder = store.folders.count
            let didBeginEditingForAddFolder = CMBeginDebugInvalidEditing(in: snippetWindow)
            let didReplaceTextForAddFolder = CMReplaceDebugInvalidEditingText("")
            let invokedAddFolderAction = CMSnippetEditorActionDebugRegistry.invoke(.addFolder)
            let folderCountAfterAddFolder = store.folders.count
            let addFolderAlertSnapshot = CMLastAlertSnapshotForDebug()

            CMResetLastAlertForDebug()
            let snippetCountBeforeAddSnippet = store.folders.first(where: { $0.title == "QA" })?.snippets.count ?? 0
            let invokedAddSnippetAction = CMSnippetEditorActionDebugRegistry.invoke(.addSnippet)
            let snippetCountAfterAddSnippet = store.folders.first(where: { $0.title == "QA" })?.snippets.count ?? 0
            let addSnippetAlertSnapshot = CMLastAlertSnapshotForDebug()

            CMResetLastAlertForDebug()
            CMEndDebugInvalidEditing()
            let folderCountBeforeImport = store.folders.count
            let didBeginEditingForImport = CMBeginDebugInvalidEditing(in: snippetWindow)
            let didReplaceTextForImport = CMReplaceDebugInvalidEditingText("")
            let invokedImportAction = CMSnippetEditorActionDebugRegistry.invoke(.importSnippets)
            let folderCountAfterImport = store.folders.count
            let importAlertSnapshot = CMLastAlertSnapshotForDebug()

            let report: [String: Any] = [
                "addFolder": [
                    "didBeginEditing": didBeginEditingForAddFolder,
                    "didReplaceText": didReplaceTextForAddFolder,
                    "invokedAction": invokedAddFolderAction,
                    "folderCountBefore": folderCountBeforeAddFolder,
                    "folderCountAfter": folderCountAfterAddFolder,
                    "alert": addFolderAlertSnapshot as Any
                ],
                "addSnippet": [
                    "invokedAction": invokedAddSnippetAction,
                    "snippetCountBefore": snippetCountBeforeAddSnippet,
                    "snippetCountAfter": snippetCountAfterAddSnippet,
                    "alert": addSnippetAlertSnapshot as Any
                ],
                "importSnippets": [
                    "didBeginEditing": didBeginEditingForImport,
                    "didReplaceText": didReplaceTextForImport,
                    "invokedAction": invokedImportAction,
                    "folderCountBefore": folderCountBeforeImport,
                    "folderCountAfter": folderCountAfterImport,
                    "alert": importAlertSnapshot as Any
                ],
                "matchesExpected": didBeginEditingForAddFolder
                    && didReplaceTextForAddFolder
                    && invokedAddFolderAction
                    && folderCountBeforeAddFolder == folderCountAfterAddFolder
                    && (addFolderAlertSnapshot?["messageText"] as? String) == NSLocalizedString("Unable to end editing", comment: "")
                    && invokedAddSnippetAction
                    && snippetCountBeforeAddSnippet == snippetCountAfterAddSnippet
                    && (addSnippetAlertSnapshot?["messageText"] as? String) == NSLocalizedString("Unable to end editing", comment: "")
                    && didBeginEditingForImport
                    && didReplaceTextForImport
                    && invokedImportAction
                    && folderCountBeforeImport == folderCountAfterImport
                    && (importAlertSnapshot?["messageText"] as? String) == NSLocalizedString("Unable to end editing", comment: "")
            ]

            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }

            CMEndDebugInvalidEditing()
            CMSetBypassAlertPresentationForDebug(false)
            CMResetLastAlertForDebug()
            store.folders = originalFolders
            store.restoreSelectionSnapshot(originalSelection)
            store.save()
            store.reload()
            self.snippetEditorController?.close()
            debugTerminateApplication()
        }
    }

