        store.toggleSelectedFolderEnabled()

        let after: [String: Any] = [
            "selectedFolderIDs": store.selectedFolderIDs.map(\.uuidString).sorted(),
            "selectedSnippetIDs": store.selectedSnippetIDs.map(\.uuidString).sorted(),
            "primarySelectedFolderID": store.selectedFolderID?.uuidString as Any,
            "primarySelectedSnippetID": store.selectedSnippetID?.uuidString as Any
        ]

        let report: [String: Any] = [
            "beforeToggle": before,
            "afterToggle": after,
            "matchesExpected": hadFolderSelectionBefore
                && store.selectedFolderIDs.isEmpty
                && store.selectedSnippetIDs.isEmpty
                && store.selectedFolderID == nil
                && store.selectedSnippetID == nil
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

