    private func runDebugSnippetDisabledInlineEditReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetDisabledInlineEditReportPath")
            ?? "/tmp/clipmenu-snippet-disabled-inline-edit-report.json")
        let settleDelay = debugOneShotDoubleValue(forKey: "debugSnippetDisabledInlineEditSettleDelay") ?? 0.25
        let store = SnippetFileStore.shared
        let originalFolders = store.folders
        let originalSelection = store.currentSelectionSnapshot()

        func writeReport(_ report: [String: Any]) {
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
        }

        func restoreAndQuit() {
            store.folders = originalFolders
            store.restoreSelectionSnapshot(originalSelection)
            store.save()
            store.reload()
            snippetEditorController?.close()
            debugTerminateApplication()
        }

        func snippetTableView(in window: NSWindow?) -> CMSnippetTableView? {
            guard let rootView = window?.contentViewController?.view ?? window?.contentView else {
                return nil
            }
            return CMCollectTableViews(in: rootView).dropFirst().first as? CMSnippetTableView
        }

        func inlineEditState(for tableView: CMSnippetTableView) -> [String: Any] {
            let selectedRow = tableView.selectedRow
            let textField = (selectedRow >= 0
                ? tableView.view(atColumn: 0, row: selectedRow, makeIfNecessary: false) as? NSTableCellView
                : nil)?.textField
            return [
                "selectedRow": selectedRow,
                "textFieldIsEditable": textField?.isEditable as Any,
                "textFieldIsSelectable": textField?.isSelectable as Any
            ]
        }

        let seed = populateSnippetStoreForDebugWorkflowSeed(persistReset: true, persistSeededState: true)
        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)

        store.selectedFolderIDs = [seed.qaFolderID]
        store.notePrimaryFolder(seed.qaFolderID)
        if let greetingSnippetID = seed.greetingSnippetID {
            store.selectedSnippetIDs = [greetingSnippetID]
            store.notePrimarySnippet(greetingSnippetID)
        }

        DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) { [weak self] in
            guard let self,
                  let window = self.snippetEditorController?.window,
                  let enabledTableView = snippetTableView(in: window) else {
                writeReport([
                    "error": "Snippet table view not available",
                    "matchesExpected": false
                ])
                restoreAndQuit()
                return
            }

            DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
                let enabledState = inlineEditState(for: enabledTableView)

                store.toggleSelectedSnippetEnabled()
                window.contentView?.layoutSubtreeIfNeeded()

                DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
                    guard let disabledTableView = snippetTableView(in: window) else {
                        writeReport([
                            "error": "Snippet table view unavailable after disable",
                            "enabledState": enabledState,
                            "matchesExpected": false
                        ])
                        restoreAndQuit()
                        return
                    }

                    DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
                        let disabledState = inlineEditState(for: disabledTableView)
                        let report: [String: Any] = [
                            "enabledState": enabledState,
                            "disabledState": disabledState,
                            "matchesExpected": (enabledState["textFieldIsEditable"] as? Bool) == true
                                && (disabledState["textFieldIsEditable"] as? Bool) == false
                                && (disabledState["textFieldIsSelectable"] as? Bool) == false
                        ]
                        writeReport(report)
                        restoreAndQuit()
                    }
                }
            }
