    private func runDebugCommandSurfaceReport() {
        func enabledStateMap(for menu: NSMenu, titles: [String]) -> [String: Bool] {
            menu.update()
            return Dictionary(uniqueKeysWithValues: titles.map { title in
                (title, menu.items.first(where: { $0.title == title })?.isEnabled ?? false)
            })
        }

        func fileMenu() -> NSMenu? {
            if NSApp.mainMenu == nil || NSApp.mainMenu?.items.isEmpty != false {
                installMainMenu()
            }
            return NSApp.mainMenu?.items.first(where: { $0.title == NSLocalizedString("File", comment: "") })?.submenu
        }

        func appMenu() -> NSMenu? {
            if NSApp.mainMenu == nil || NSApp.mainMenu?.items.isEmpty != false {
                installMainMenu()
            }
            let expectedPreferencesTitle = NSLocalizedString("Preferences...", comment: "")
            return NSApp.mainMenu?.items
                .compactMap(\.submenu)
                .first(where: { menu in
                    menu.items.contains(where: { $0.title == expectedPreferencesTitle })
                })
                ?? NSApp.mainMenu?.items.first?.submenu
        }

        func editMenu() -> NSMenu? {
            if NSApp.mainMenu == nil || NSApp.mainMenu?.items.isEmpty != false {
                installMainMenu()
            }
            return NSApp.mainMenu?.items.first(where: { $0.title == NSLocalizedString("Edit", comment: "") })?.submenu
        }

        func helpMenu() -> NSMenu? {
            if NSApp.mainMenu == nil || NSApp.mainMenu?.items.isEmpty != false {
                installMainMenu()
            }
            return NSApp.mainMenu?.items.first(where: { $0.title == NSLocalizedString("Help", comment: "") })?.submenu
        }

        func menuItemReport(_ item: NSMenuItem?) -> [String: Any] {
            guard let item else {
                return [:]
            }
            return [
                "title": visibleMenuItemTitle(item),
                "action": item.action.map(NSStringFromSelector(_:)) as Any,
                "targetClass": item.target.map { String(describing: type(of: $0)) } as Any,
                "keyEquivalent": item.keyEquivalent,
                "modifierMask": item.keyEquivalentModifierMask.rawValue
            ]
        }

        func menuItem(withTitle title: String, in menu: NSMenu) -> NSMenuItem? {
            menu.items.first(where: { $0.title == title })
        }

        func menuItem(withAction action: Selector, in menu: NSMenu) -> NSMenuItem? {
            menu.items.first(where: { $0.action == action })
        }

        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugCommandSurfaceReportPath")
            ?? "/tmp/clipmenu-command-surface-report.json")
        let newMenuTitle = NSLocalizedString("New", comment: "")
        let openMenuTitle = NSLocalizedString("Open...", comment: "")
        let openRecentMenuTitle = NSLocalizedString("Open Recent", comment: "")
        let closeMenuTitle = NSLocalizedString("Close", comment: "")
        let closeAllMenuTitle = NSLocalizedString("Close All", comment: "")
        let saveMenuTitle = NSLocalizedString("Save", comment: "")
        let saveAsMenuTitle = NSLocalizedString("Save As...", comment: "")
        let revertMenuTitle = NSLocalizedString("Revert", comment: "")
        let pageSetupMenuTitle = NSLocalizedString("Page Setup...", comment: "")
        let printMenuTitle = NSLocalizedString("Print...", comment: "")
        let preferencesMenuTitle = NSLocalizedString("Preferences...", comment: "")
        let checkForUpdatesMenuTitle = NSLocalizedString("Check for Updates...", comment: "")
        let clipMenuHelpTitle = NSLocalizedString("ClipMenu Help", comment: "")
        let fileMenuTitles = [
            newMenuTitle,
            openMenuTitle,
            openRecentMenuTitle,
            closeMenuTitle,
            closeAllMenuTitle,
            saveMenuTitle,
            saveAsMenuTitle,
            revertMenuTitle,
            pageSetupMenuTitle,
            printMenuTitle
        ]
        let statusMenuTitles = [
            NSLocalizedString("Clear History", comment: ""),
            NSLocalizedString("Edit Snippets...", comment: ""),
            preferencesMenuTitle,
            NSLocalizedString("Quit ClipMenu", comment: "")
        ]

        let defaults = UserDefaults.standard
        let originalShowLabels = defaults.bool(forKey: CMPrefShowLabelsInMenuKey)
        let originalAddClearHistory = defaults.bool(forKey: CMPrefAddClearHistoryMenuItemKey)
        let originalSnippetsPosition = defaults.integer(forKey: CMPrefPositionOfSnippetsKey)
        let originalFolders = SnippetFileStore.shared.folders

        defer {
            defaults.set(originalShowLabels, forKey: CMPrefShowLabelsInMenuKey)
            defaults.set(originalAddClearHistory, forKey: CMPrefAddClearHistoryMenuItemKey)
            defaults.set(originalSnippetsPosition, forKey: CMPrefPositionOfSnippetsKey)
            SnippetFileStore.shared.folders = originalFolders
            SnippetFileStore.shared.save()
            snippetEditorController?.close()
            SwiftUIPreferencesWindowController.shared.close()
            debugTerminateApplication()
        }

        defaults.set(false, forKey: CMPrefShowLabelsInMenuKey)
        defaults.set(true, forKey: CMPrefAddClearHistoryMenuItemKey)
        defaults.set(CMPositionOfSnippets.none.rawValue, forKey: CMPrefPositionOfSnippetsKey)
        clipsStore.clear()
        let snippetStore = SnippetFileStore.shared
        snippetStore.folders = []
        snippetStore.save()
        snippetStore.reload()

        let bareMainMenu = makeMainMenu()
        let bareFileStates = fileMenu().map { enabledStateMap(for: $0, titles: fileMenuTitles) } ?? [:]
        let bareStatusStates = enabledStateMap(for: bareMainMenu, titles: statusMenuTitles)
        let bareStatusTopLevelTitles = bareMainMenu.items.map { $0.isSeparatorItem ? "<separator>" : $0.title }
        let syntheticClearHistoryItem = NSMenuItem(
            title: NSLocalizedString("Clear History", comment: ""),
            action: #selector(clearHistory(_:)),
            keyEquivalent: ""
        )
        syntheticClearHistoryItem.target = self
        let installedMainMenuTopLevelTitles = NSApp.mainMenu?.items.map { $0.isSeparatorItem ? "<separator>" : $0.title } ?? []
        let bareAppMenu = appMenu()
        let bareAppMenuTitles: [String] = bareAppMenu?.items.map {
            if $0.isSeparatorItem { return "<separator>" }
            return visibleMenuItemTitle($0)
        } ?? []
        let bareFileMenu = fileMenu()
        let bareEditMenu = editMenu()
        let bareHelpMenu = helpMenu()
        let preferencesMenuItem = bareAppMenu.flatMap { menuItem(withTitle: preferencesMenuTitle, in: $0) }
            ?? bareAppMenu.flatMap { menuItem(withAction: #selector(showPreferencePanel(_:)), in: $0) }
        let statusClearHistoryMenuItem = menuItem(withTitle: NSLocalizedString("Clear History", comment: ""), in: bareMainMenu)
        let statusSnippetEditorMenuItem = menuItem(withTitle: NSLocalizedString("Edit Snippets...", comment: ""), in: bareMainMenu)
        let statusPreferencesMenuItem = menuItem(withTitle: preferencesMenuTitle, in: bareMainMenu)
        let closeMenuItem = bareFileMenu.flatMap { menuItem(withTitle: closeMenuTitle, in: $0) }
        let saveAsMenuItem = bareFileMenu.flatMap { menuItem(withTitle: saveAsMenuTitle, in: $0) }
        let saveMenuItem = bareFileMenu.flatMap { menuItem(withTitle: saveMenuTitle, in: $0) }
        let revertMenuItem = bareFileMenu.flatMap { menuItem(withTitle: revertMenuTitle, in: $0) }
        let pageSetupMenuItem = bareFileMenu.flatMap { menuItem(withTitle: pageSetupMenuTitle, in: $0) }
        let printMenuItem = bareFileMenu.flatMap { menuItem(withTitle: printMenuTitle, in: $0) }
        let redoMenuItem = bareEditMenu.flatMap { menuItem(withTitle: NSLocalizedString("Redo", comment: ""), in: $0) }
        let helpMenuItem = bareHelpMenu.flatMap { menuItem(withTitle: clipMenuHelpTitle, in: $0) }
        let sampleClipMenuItem = makeClipMenuItem(clip: ClipItem(text: "router-clip"), globalIndex: 0, listNumber: 1)
        let sampleSnippetMenuItem: NSMenuItem = {
            let item = NSMenuItem(
                title: "1. router-snippet",
                action: #selector(selectSnippet(_:)),
                keyEquivalent: ""
            )
            item.target = statusMenuCommandRouter
            item.representedObject = SnippetActionReference(folderID: UUID(), snippetID: UUID(), content: "router-snippet")
            return item
        }()
        let sampleActionMenuItem = makeActionMenuItem(
            from: RuntimeActionNode(
                nodeTitle: NSLocalizedString("Remove", comment: ""),
                action: ["type": "builtin", "name": "remove:"]
            )
        )

        showPreferencePanel(nil)
        NSApp.activate(ignoringOtherApps: true)
        SwiftUIPreferencesWindowController.shared.window?.makeMain()
        SwiftUIPreferencesWindowController.shared.window?.makeKeyAndOrderFront(nil)
        let preferencesFileStates = fileMenu().map { enabledStateMap(for: $0, titles: fileMenuTitles) } ?? [:]
        let preferencesWindowVisible = SwiftUIPreferencesWindowController.shared.window?.isVisible == true
        let preferencesKeyWindowTitle = NSApp.keyWindow?.title
        let preferencesMainWindowTitle = NSApp.mainWindow?.title

        SwiftUIPreferencesWindowController.shared.close()
        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)
        let snippetEditorFileStates = fileMenu().map { enabledStateMap(for: $0, titles: fileMenuTitles) } ?? [:]
        let snippetEditorWindowVisible = snippetEditorController?.window?.isVisible == true
        let snippetEditorKeyWindowTitle = NSApp.keyWindow?.title
        let snippetEditorMainWindowTitle = NSApp.mainWindow?.title
        let statusClearHistoryMenuItemReport = menuItemReport(statusClearHistoryMenuItem)
        let statusSnippetEditorMenuItemReport = menuItemReport(statusSnippetEditorMenuItem)
        let statusPreferencesMenuItemReport = menuItemReport(statusPreferencesMenuItem)
        let preferencesMenuItemReport = menuItemReport(preferencesMenuItem)
        let closeMenuItemReport = menuItemReport(closeMenuItem)
        let saveMenuItemReport = menuItemReport(saveMenuItem)
        let saveAsMenuItemReport = menuItemReport(saveAsMenuItem)
        let revertMenuItemReport = menuItemReport(revertMenuItem)
        let pageSetupMenuItemReport = menuItemReport(pageSetupMenuItem)
        let printMenuItemReport = menuItemReport(printMenuItem)
        let redoMenuItemReport = menuItemReport(redoMenuItem)
        let helpMenuItemReport = menuItemReport(helpMenuItem)
        let sampleClipMenuItemReport = menuItemReport(sampleClipMenuItem)
        let sampleSnippetMenuItemReport = menuItemReport(sampleSnippetMenuItem)
        let sampleActionMenuItemReport = menuItemReport(sampleActionMenuItem)
        let expectedInstalledMainMenuTopLevelTitles = [
            "ClipMenu",
            NSLocalizedString("File", comment: ""),
            NSLocalizedString("Edit", comment: ""),
            NSLocalizedString("Help", comment: "")
        ]
        let expectedBareAppMenuTitles = [
            NSLocalizedString("About ClipMenu", comment: ""),
            "<separator>",
            preferencesMenuTitle,
            "<separator>",
            NSLocalizedString("Services", comment: ""),
            "<separator>",
            NSLocalizedString("Hide ClipMenu", comment: ""),
            NSLocalizedString("Hide Others", comment: ""),
            NSLocalizedString("Show All", comment: ""),
            "<separator>",
            NSLocalizedString("Quit ClipMenu", comment: "")
        ]
        let expectedBareStatusTopLevelTitles = [
            NSLocalizedString("Clear History", comment: ""),
            NSLocalizedString("Edit Snippets...", comment: ""),
            preferencesMenuTitle,
            "<separator>",
            NSLocalizedString("Quit ClipMenu", comment: "")
        ]
        let expectedBareFileStates: [String: Bool] = [
            newMenuTitle: false,
            openMenuTitle: false,
            openRecentMenuTitle: true,
            closeMenuTitle: false,
            closeAllMenuTitle: true,
            saveMenuTitle: false,
            saveAsMenuTitle: false,
            revertMenuTitle: false,
            pageSetupMenuTitle: false,
            printMenuTitle: false
        ]
        let expectedBareStatusStates: [String: Bool] = [
            NSLocalizedString("Clear History", comment: ""): true,
            NSLocalizedString("Edit Snippets...", comment: ""): true,
            preferencesMenuTitle: true,
            NSLocalizedString("Quit ClipMenu", comment: ""): true
        ]
        let expectedPreferencesFileStates: [String: Bool] = [
            newMenuTitle: false,
            openMenuTitle: false,
            openRecentMenuTitle: true,
            closeMenuTitle: true,
            closeAllMenuTitle: true,
            saveMenuTitle: false,
            saveAsMenuTitle: false,
            revertMenuTitle: false,
            pageSetupMenuTitle: false,
            printMenuTitle: false
        ]
        let expectedSnippetEditorFileStates: [String: Bool] = [
            newMenuTitle: false,
            openMenuTitle: false,
            openRecentMenuTitle: true,
            closeMenuTitle: true,
            closeAllMenuTitle: true,
            saveMenuTitle: false,
            saveAsMenuTitle: true,
            revertMenuTitle: false,
            pageSetupMenuTitle: false,
            printMenuTitle: true
        ]
        let commandSurfaceMatchesExpected =
            bareFileStates == expectedBareFileStates
            && bareStatusStates == expectedBareStatusStates
            && bareStatusTopLevelTitles == expectedBareStatusTopLevelTitles
            && bareAppMenuTitles == expectedBareAppMenuTitles
            && bareStatusStates[NSLocalizedString("Clear History", comment: "")] == true
            && validateMenuItem(syntheticClearHistoryItem) == false
            && statusMenuTitles.allSatisfy { bareStatusStates[$0] == true }
            && !bareStatusTopLevelTitles.contains(checkForUpdatesMenuTitle)
            && installedMainMenuTopLevelTitles == expectedInstalledMainMenuTopLevelTitles
            && normalizedMenuItemTitle(preferencesMenuItem.map(visibleMenuItemTitle) ?? "") == normalizedMenuItemTitle(preferencesMenuTitle)
            && normalizedMenuItemTitle(saveAsMenuItem?.title ?? "") == normalizedMenuItemTitle(saveAsMenuTitle)
            && normalizedMenuItemTitle(pageSetupMenuItem?.title ?? "") == normalizedMenuItemTitle(pageSetupMenuTitle)
            && normalizedMenuItemTitle(printMenuItem?.title ?? "") == normalizedMenuItemTitle(printMenuTitle)
            && preferencesMenuItem?.keyEquivalent == ","
            && preferencesMenuItem?.keyEquivalentModifierMask.rawValue == NSEvent.ModifierFlags.command.rawValue
            && saveAsMenuItem?.keyEquivalent == "S"
            && saveAsMenuItem?.keyEquivalentModifierMask.rawValue == NSEvent.ModifierFlags.command.rawValue
            && pageSetupMenuItem?.keyEquivalent == "P"
            && pageSetupMenuItem?.keyEquivalentModifierMask.rawValue == NSEvent.ModifierFlags.command.rawValue
            && printMenuItem?.keyEquivalent == "p"
            && printMenuItem?.keyEquivalentModifierMask.rawValue == NSEvent.ModifierFlags.command.rawValue
            && redoMenuItem?.keyEquivalent == "Z"
            && redoMenuItem?.keyEquivalentModifierMask.rawValue == NSEvent.ModifierFlags.command.rawValue
            && preferencesFileStates == expectedPreferencesFileStates
            && snippetEditorFileStates == expectedSnippetEditorFileStates
            && preferencesWindowVisible
            && snippetEditorWindowVisible
            && preferencesKeyWindowTitle == nil
            && preferencesMainWindowTitle == nil
            && snippetEditorKeyWindowTitle == nil
            && snippetEditorMainWindowTitle == nil
            && (preferencesMenuItemReport["action"] as? String) == "showPreferencePanel:"
            && (preferencesMenuItemReport["targetClass"] as? String) == "AppController"
            && (statusClearHistoryMenuItemReport["action"] as? String) == "clearHistory:"
