    private func runDebugClearHistoryMenuReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugClearHistoryMenuReportPath")
            ?? "/tmp/clipmenu-clear-history-menu-report.json")
        let originalAddClearHistory = defaults.object(forKey: CMPrefAddClearHistoryMenuItemKey)
        let originalAlertBeforeClear = defaults.object(forKey: CMPrefShowAlertBeforeClearHistoryKey)
        let originalShowLabels = defaults.object(forKey: CMPrefShowLabelsInMenuKey)
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)
        let originalClips = clipsStore.clips

        defer {
            restoreDefault(originalAddClearHistory, forKey: CMPrefAddClearHistoryMenuItemKey)
            restoreDefault(originalAlertBeforeClear, forKey: CMPrefShowAlertBeforeClearHistoryKey)
            restoreDefault(originalShowLabels, forKey: CMPrefShowLabelsInMenuKey)
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            rebuildMenu()
            debugTerminateApplication()
        }

        defaults.set(true, forKey: CMPrefAddClearHistoryMenuItemKey)
        defaults.set(true, forKey: CMPrefShowAlertBeforeClearHistoryKey)
        defaults.set(false, forKey: CMPrefShowLabelsInMenuKey)
        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        clipsStore.clear()
        clipsStore.add(
            ClipItem(
                text: "clear-menu-one",
                createdAt: Date(timeIntervalSinceReferenceDate: 100),
                lastUsedAt: Date(timeIntervalSinceReferenceDate: 100)
            )
        )
        clipsStore.add(
            ClipItem(
                text: "clear-menu-two",
                createdAt: Date(timeIntervalSinceReferenceDate: 200),
                lastUsedAt: Date(timeIntervalSinceReferenceDate: 200)
            )
        )

        let title = NSLocalizedString("Clear History", comment: "")
        let menuBefore = makeMainMenu()
        menuBefore.update()
        let clearItemBefore = menuBefore.items.first { $0.title == title }
        let historyTextsBefore = clipsStore.orderedClips.map(\.text)
        let clearHistorySucceeded = performClearHistory {
            ClearHistoryAlertResolution(confirmed: true, suppressFutureAlerts: false)
        }
        let historyTextsAfter = clipsStore.orderedClips.map(\.text)
        let menuAfter = makeMainMenu()
        menuAfter.update()
        let clearItemAfter = menuAfter.items.first { $0.title == title }

        let report: [String: Any] = [
            "mainMenuTitlesBefore": menuBefore.items.map { $0.isSeparatorItem ? "<separator>" : $0.title },
            "mainMenuTitlesAfter": menuAfter.items.map { $0.isSeparatorItem ? "<separator>" : $0.title },
            "historyTextsBefore": historyTextsBefore,
            "historyTextsAfter": historyTextsAfter,
            "clearHistoryEnabledBefore": clearItemBefore?.isEnabled as Any,
            "clearHistoryEnabledAfter": clearItemAfter?.isEnabled as Any,
            "clearHistorySucceeded": clearHistorySucceeded,
            "matchesExpected": historyTextsBefore == ["clear-menu-two", "clear-menu-one"]
                && clearHistorySucceeded
                && historyTextsAfter.isEmpty
                && clearItemBefore?.isEnabled == true
                && clearItemAfter?.isEnabled == true
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugClearHistorySuppressionReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugClearHistorySuppressionReportPath")
            ?? "/tmp/clipmenu-clear-history-suppression-report.json")
        let originalAlertBeforeClear = defaults.bool(forKey: CMPrefShowAlertBeforeClearHistoryKey)
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)
        let originalClips = clipsStore.clips
        let alert = makeClearHistoryPrompt()
        let alertButtonTitles = alert.buttons.map(\.title)
        let accessoryTextValues: [String] = {
            guard let accessoryView = alert.accessoryView else { return [] }
            var values: [String] = []
            func collect(from view: NSView) {
                if let textField = view as? NSTextField {
                    let value = textField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
                    if !value.isEmpty {
                        values.append(value)
                    }
                }
                for subview in view.subviews {
                    collect(from: subview)
                }
            }
            collect(from: accessoryView)
            return Array(NSOrderedSet(array: values)) as? [String] ?? values
        }()

        defer {
            defaults.set(originalAlertBeforeClear, forKey: CMPrefShowAlertBeforeClearHistoryKey)
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            rebuildMenu()
            debugTerminateApplication()
        }

        defaults.set(true, forKey: CMPrefShowAlertBeforeClearHistoryKey)
        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        clipsStore.clear()
        clipsStore.add(
            ClipItem(
                text: "clear-one",
                createdAt: Date(timeIntervalSinceReferenceDate: 100),
                lastUsedAt: Date(timeIntervalSinceReferenceDate: 100)
            )
        )
        clipsStore.add(
            ClipItem(
                text: "clear-two",
                createdAt: Date(timeIntervalSinceReferenceDate: 200),
                lastUsedAt: Date(timeIntervalSinceReferenceDate: 200)
            )
        )

        let initialTexts = clipsStore.orderedClips.map(\.text)
        let firstInvocationCleared = performClearHistory {
            ClearHistoryAlertResolution(confirmed: true, suppressFutureAlerts: true)
        }
        let afterFirstTexts = clipsStore.orderedClips.map(\.text)
        let alertDisabledAfterSuppression = defaults.bool(forKey: CMPrefShowAlertBeforeClearHistoryKey) == false

        clipsStore.add(
            ClipItem(
                text: "clear-three",
                createdAt: Date(timeIntervalSinceReferenceDate: 300),
                lastUsedAt: Date(timeIntervalSinceReferenceDate: 300)
            )
        )
        let beforeSecondTexts = clipsStore.orderedClips.map(\.text)
        let secondInvocationCleared = performClearHistory {
            ClearHistoryAlertResolution(confirmed: false, suppressFutureAlerts: false)
        }
        let afterSecondTexts = clipsStore.orderedClips.map(\.text)
        let alertState: [String: Any] = [
            "messageText": alert.messageText,
            "informativeText": alert.informativeText,
            "buttonTitles": alertButtonTitles,
            "showsSuppressionButton": alert.showsSuppressionButton,
            "hasAccessoryView": alert.accessoryView != nil,
            "accessoryTextValues": accessoryTextValues
        ]
        let expectedAlertState: [String: Any] = [
            "messageText": NSLocalizedString("Clear History", comment: ""),
            "informativeText": NSLocalizedString("Are you sure you want to clear your clipboard history?", comment: ""),
            "buttonTitles": [
                NSLocalizedString("Clear History", comment: ""),
                NSLocalizedString("Cancel", comment: "")
            ],
            "showsSuppressionButton": true,
            "hasAccessoryView": true,
            "accessoryTextValues": [
                localizedClearHistoryPromptAccessoryTitle(),
                localizedClearHistoryPromptAccessoryDetail()
            ]
        ]
        let alertStateMatchesExpected = (alertState as NSDictionary).isEqual(to: expectedAlertState)
        let suppressionFlowMatchesExpected = alertStateMatchesExpected
            && initialTexts == ["clear-two", "clear-one"]
            && firstInvocationCleared
            && afterFirstTexts.isEmpty
            && alertDisabledAfterSuppression
            && beforeSecondTexts == ["clear-three"]
            && secondInvocationCleared
            && afterSecondTexts.isEmpty

        let report: [String: Any] = [
            "alertState": alertState,
            "expectedAlertState": expectedAlertState,
            "alertStateMatchesExpected": alertStateMatchesExpected,
            "initialTexts": initialTexts,
            "firstInvocationCleared": firstInvocationCleared,
            "afterFirstTexts": afterFirstTexts,
            "alertDisabledAfterSuppression": alertDisabledAfterSuppression,
            "beforeSecondTexts": beforeSecondTexts,
            "secondInvocationCleared": secondInvocationCleared,
            "afterSecondTexts": afterSecondTexts,
            "suppressionSkipsSecondConfirmation": afterSecondTexts.isEmpty && secondInvocationCleared,
            "suppressionFlowMatchesExpected": suppressionFlowMatchesExpected,
            "matchesExpected": suppressionFlowMatchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugPastePermissionPromptReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPastePermissionPromptReportPath")
            ?? "/tmp/clipmenu-paste-permission-prompt-report.json")
        let appName = legacyApplicationName()
        let missingAllAccessState = PasteAutomationAccessState(accessibilityGranted: false, postEventGranted: false)
        let accessibilityOnlyAccessState = PasteAutomationAccessState(accessibilityGranted: true, postEventGranted: false)
        let alert = makePastePermissionPrompt(appName: appName, accessState: missingAllAccessState)
        let accessibilityOnlyAlert = makePastePermissionPrompt(appName: appName, accessState: accessibilityOnlyAccessState)
        let alertButtonTitles = alert.buttons.map(\.title)
        func accessoryTextValues(for alert: NSAlert) -> [String] {
            guard let accessoryView = alert.accessoryView else { return [] }
            var values: [String] = []
            func collect(from view: NSView) {
                if let textField = view as? NSTextField {
                    let value = textField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
                    if !value.isEmpty {
                        values.append(value)
                    }
                }
                for subview in view.subviews {
                    collect(from: subview)
                }
            }
            collect(from: accessoryView)
            return Array(NSOrderedSet(array: values)) as? [String] ?? values
        }
        let alertAccessoryTextValues = accessoryTextValues(for: alert)
        let accessibilityOnlyAccessoryTextValues = accessoryTextValues(for: accessibilityOnlyAlert)
        let actualAlertState: [String: Any] = [
            "messageText": alert.messageText,
            "informativeText": alert.informativeText,
            "buttonTitles": alertButtonTitles,
            "hasAccessoryView": alert.accessoryView != nil,
            "accessoryTextValues": alertAccessoryTextValues
        ]
        let expectedAlertState: [String: Any] = [
            "messageText": NSLocalizedString("Allow Paste Automation", comment: ""),
            "informativeText": String(
                format: NSLocalizedString("%@ needs Accessibility access to paste into the frontmost app. Allow access in System Settings, then relaunch %@.", comment: ""),
                appName,
                appName
            ),
            "buttonTitles": [
                NSLocalizedString("Open Settings", comment: ""),
                NSLocalizedString("Later", comment: "")
            ],
            "hasAccessoryView": true,
            "accessoryTextValues": [
                localizedPastePermissionPromptAccessoryTitle(),
                localizedPastePermissionPromptAccessoryDetail(appName: appName, accessState: missingAllAccessState)
            ]
        ]
        let accessibilityOnlyAlertState: [String: Any] = [
            "messageText": accessibilityOnlyAlert.messageText,
            "informativeText": accessibilityOnlyAlert.informativeText,
            "buttonTitles": accessibilityOnlyAlert.buttons.map(\.title),
            "hasAccessoryView": accessibilityOnlyAlert.accessoryView != nil,
            "accessoryTextValues": accessibilityOnlyAccessoryTextValues
        ]
        let expectedAccessibilityOnlyAlertState: [String: Any] = [
            "messageText": NSLocalizedString("Allow Paste Automation", comment: ""),
            "informativeText": localizedPastePermissionPromptInformativeText(
                appName: appName,
                accessState: accessibilityOnlyAccessState
            ),
            "buttonTitles": [
                NSLocalizedString("Open Settings", comment: ""),
                NSLocalizedString("Later", comment: "")
            ],
            "hasAccessoryView": true,
            "accessoryTextValues": [
                localizedPastePermissionPromptAccessoryTitle(),
                localizedPastePermissionPromptAccessoryDetail(appName: appName, accessState: accessibilityOnlyAccessState)
            ]
        ]
        let openSettingsState: [String: Any] = [
            "requested": pastePermissionPromptOpenSettingsRequested(response: .alertFirstButtonReturn),
            "url": pastePermissionSettingsURL()?.absoluteString as Any
        ]
        let laterState: [String: Any] = [
            "requested": pastePermissionPromptOpenSettingsRequested(response: .alertSecondButtonReturn),
            "url": pastePermissionPromptOpenSettingsRequested(response: .alertSecondButtonReturn)
                ? pastePermissionSettingsURL()?.absoluteString as Any
                : "" as Any
        ]
        let expectedOpenSettingsState: [String: Any] = [
            "requested": true,
            "url": "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility"
        ]
        let expectedLaterState: [String: Any] = [
            "requested": false,
            "url": ""
        ]
        let matchesExpected = (actualAlertState as NSDictionary).isEqual(to: expectedAlertState)
            && (accessibilityOnlyAlertState as NSDictionary).isEqual(to: expectedAccessibilityOnlyAlertState)
            && (openSettingsState as NSDictionary).isEqual(to: expectedOpenSettingsState)
            && (laterState as NSDictionary).isEqual(to: expectedLaterState)
        let report: [String: Any] = [
            "alertState": actualAlertState,
            "expectedAlertState": expectedAlertState,
            "accessibilityOnlyAlertState": accessibilityOnlyAlertState,
            "expectedAccessibilityOnlyAlertState": expectedAccessibilityOnlyAlertState,
            "openSettingsState": openSettingsState,
            "expectedOpenSettingsState": expectedOpenSettingsState,
            "laterState": laterState,
            "expectedLaterState": expectedLaterState,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        debugTerminateApplication()
    }

