        defaults.set(2, forKey: CMPrefMaxHistorySizeKey)
        seedBaselineHistoryVerificationClips()
        clipsStore.trimToCurrentHistoryLimit()
        let trimmedOrderedTexts = clipsStore.orderedClips.map(\.text)
        let saveSucceeded = clipsStore.save()

        let reloadedStore = ClipStore()
        reloadedStore.load()
        let reloadedOrderedTexts = reloadedStore.orderedClips.map(\.text)

        reloadedStore.removeSavedHistory()
        let clearedStore = ClipStore()
        clearedStore.load()
        let clearedReloadCount = clearedStore.clips.count
        let clearedReloadEmpty = clearedStore.clips.isEmpty

        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        clipsStore.clear()
        clipsStore.add(ClipItem(text: "quit-save-alpha"))
        clipsStore.add(ClipItem(text: "quit-save-beta"))
        let quitSaveExpectedTexts = clipsStore.orderedClips.map(\.text)
        defaults.set(true, forKey: CMPrefSaveHistoryOnQuitKey)
        let quitSavePersistSucceeded = persistHistoryForTermination()
        let quitSaveReloadStore = ClipStore()
        quitSaveReloadStore.load()
        let quitSaveReloadTexts = quitSaveReloadStore.orderedClips.map(\.text)

        clipsStore.clear()
        clipsStore.add(ClipItem(text: "quit-discard-alpha"))
        defaults.set(false, forKey: CMPrefSaveHistoryOnQuitKey)
        let quitDiscardPersistSucceeded = persistHistoryForTermination()
        let quitDiscardReloadStore = ClipStore()
        quitDiscardReloadStore.load()
        let quitDiscardReloadCount = quitDiscardReloadStore.clips.count
        let quitDiscardReloadEmpty = quitDiscardReloadStore.clips.isEmpty

        clipsStore.clear()
        clipsStore.removeSavedHistory()
        defaults.set(true, forKey: CMPrefSaveHistoryOnQuitKey)
        clipsStore.add(ClipItem(text: "capture-flush-alpha"))
        let captureFlushPersistSucceeded = persistCapturedHistoryIfPreferred()
        let captureFlushReloadStore = ClipStore()
        captureFlushReloadStore.load()
        let captureFlushReloadTexts = captureFlushReloadStore.orderedClips.map(\.text)

        let expectedTrimmedOrderedTexts = ["fixture-delta", "fixture-gamma"]
        let expectedQuitSaveReloadTexts = ["quit-save-beta", "quit-save-alpha"]
        let expectedCaptureFlushReloadTexts = ["capture-flush-alpha"]

        report["trimmedOrderedTextsBeforeSave"] = trimmedOrderedTexts
        report["saveSucceeded"] = saveSucceeded
        report["reloadedOrderedTexts"] = reloadedOrderedTexts
        report["reloadMatchesTrimmedState"] = reloadedOrderedTexts == trimmedOrderedTexts
        report["clearedReloadCount"] = clearedReloadCount
        report["clearedReloadEmpty"] = clearedReloadEmpty
        report["quitSavePersistSucceeded"] = quitSavePersistSucceeded
        report["quitSaveExpectedTexts"] = quitSaveExpectedTexts
        report["quitSaveReloadTexts"] = quitSaveReloadTexts
        report["quitSaveReloadMatchesExpected"] = quitSaveReloadTexts == quitSaveExpectedTexts
        report["quitDiscardPersistSucceeded"] = quitDiscardPersistSucceeded
        report["quitDiscardReloadCount"] = quitDiscardReloadCount
        report["quitDiscardReloadEmpty"] = quitDiscardReloadEmpty
        report["captureFlushPersistSucceeded"] = captureFlushPersistSucceeded
        report["captureFlushReloadTexts"] = captureFlushReloadTexts
        report["captureFlushReloadMatchesExpected"] = captureFlushReloadTexts == expectedCaptureFlushReloadTexts
        report["expectedState"] = [
            "trimmedOrderedTextsBeforeSave": expectedTrimmedOrderedTexts,
            "reloadedOrderedTexts": expectedTrimmedOrderedTexts,
            "clearedReloadCount": 0,
            "quitSaveReloadTexts": expectedQuitSaveReloadTexts,
            "quitDiscardReloadCount": 0,
            "captureFlushReloadTexts": expectedCaptureFlushReloadTexts
        ]
        report["matchesExpected"] = trimmedOrderedTexts == expectedTrimmedOrderedTexts
            && saveSucceeded
            && reloadedOrderedTexts == expectedTrimmedOrderedTexts
            && clearedReloadCount == 0
            && clearedReloadEmpty
            && quitSavePersistSucceeded
            && quitSaveExpectedTexts == expectedQuitSaveReloadTexts
            && quitSaveReloadTexts == expectedQuitSaveReloadTexts
            && quitDiscardPersistSucceeded
            && quitDiscardReloadCount == 0
            && quitDiscardReloadEmpty
            && captureFlushPersistSucceeded
            && captureFlushReloadTexts == expectedCaptureFlushReloadTexts

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugTypedCaptureReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugTypedCaptureReportPath")
            ?? "/tmp/clipmenu-typed-capture-report.json")
        var report: [String: Any] = [
            "usedIsolatedSupportDirectory": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
            return
        }

        let originalStoreTypes = defaults.object(forKey: CMPrefStoreTypesKey)

        defer {
            restoreDefault(originalStoreTypes, forKey: CMPrefStoreTypesKey)
            debugTerminateApplication()
        }

        func makeScratchPasteboard(suffix: String) -> NSPasteboard {
            NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.typed-capture.\(suffix).\(UUID().uuidString)"))
        }

        let allDisabledStoreTypes = Dictionary(uniqueKeysWithValues: ClipItem.defaultStoreTypes().keys.map { ($0, false) })
        defaults.set(allDisabledStoreTypes, forKey: CMPrefStoreTypesKey)
        let allDisabledStringPasteboard = makeScratchPasteboard(suffix: "allDisabledString")
        allDisabledStringPasteboard.clearContents()
        allDisabledStringPasteboard.declareTypes([.string], owner: nil)
        allDisabledStringPasteboard.setString("all-disabled-string-clip", forType: .string)
        let allDisabledStoreTypesRejectString = capturedClip(from: allDisabledStringPasteboard, frontmostBundleIdentifier: nil) == nil

        let allDisabledPDFPasteboard = makeScratchPasteboard(suffix: "allDisabledPDF")
        _ = writeDebugPDFPasteboard(allDisabledPDFPasteboard)
        let allDisabledStoreTypesRejectPDF = capturedClip(from: allDisabledPDFPasteboard, frontmostBundleIdentifier: nil) == nil

        var pdfOnlyStoreTypes = Dictionary(uniqueKeysWithValues: ClipItem.defaultStoreTypes().keys.map { ($0, false) })
        pdfOnlyStoreTypes["PDF"] = true
        defaults.set(pdfOnlyStoreTypes, forKey: CMPrefStoreTypesKey)
        let pdfOnlyStringPasteboard = makeScratchPasteboard(suffix: "pdfOnlyString")
        pdfOnlyStringPasteboard.clearContents()
        pdfOnlyStringPasteboard.declareTypes([.string], owner: nil)
        pdfOnlyStringPasteboard.setString("pdf-only-string-clip", forType: .string)
        let pdfOnlyStoreTypesRejectString = capturedClip(from: pdfOnlyStringPasteboard, frontmostBundleIdentifier: nil) == nil

        let pdfOnlyPasteboard = makeScratchPasteboard(suffix: "pdfOnly")
        _ = writeDebugPDFPasteboard(pdfOnlyPasteboard)
        let pdfOnlyClip = capturedClip(from: pdfOnlyPasteboard, frontmostBundleIdentifier: nil)
        let pdfOnlyStoreTypesAcceptPDF = pdfOnlyClip?.types.contains(NSPasteboard.PasteboardType.pdf.rawValue) == true

        var rtfOnlyStoreTypes = Dictionary(uniqueKeysWithValues: ClipItem.defaultStoreTypes().keys.map { ($0, false) })
        rtfOnlyStoreTypes["RTF"] = true
        defaults.set(rtfOnlyStoreTypes, forKey: CMPrefStoreTypesKey)
        let rtfOnlyStringPasteboard = makeScratchPasteboard(suffix: "rtfOnlyString")
        rtfOnlyStringPasteboard.clearContents()
        rtfOnlyStringPasteboard.declareTypes([.string], owner: nil)
        rtfOnlyStringPasteboard.setString("rtf-only-string-clip", forType: .string)
        let rtfOnlyStoreTypesRejectString = capturedClip(from: rtfOnlyStringPasteboard, frontmostBundleIdentifier: nil) == nil

        let rtfOnlyPasteboard = makeScratchPasteboard(suffix: "rtfOnly")
        _ = writeDebugRTFPasteboard(rtfOnlyPasteboard)
        let rtfOnlyClip = capturedClip(from: rtfOnlyPasteboard, frontmostBundleIdentifier: nil)
        let rtfOnlyStoreTypesAcceptRTF = rtfOnlyClip?.types.contains(NSPasteboard.PasteboardType.rtf.rawValue) == true
            && rtfOnlyClip?.rtfData?.isEmpty == false
            && rtfOnlyClip?.text == "Rich Smoke"

        var tiffOnlyStoreTypes = Dictionary(uniqueKeysWithValues: ClipItem.defaultStoreTypes().keys.map { ($0, false) })
        tiffOnlyStoreTypes["TIFF"] = true
        defaults.set(tiffOnlyStoreTypes, forKey: CMPrefStoreTypesKey)
        let tiffOnlyStringPasteboard = makeScratchPasteboard(suffix: "tiffOnlyString")
        tiffOnlyStringPasteboard.clearContents()
        tiffOnlyStringPasteboard.declareTypes([.string], owner: nil)
        tiffOnlyStringPasteboard.setString("tiff-only-string-clip", forType: .string)
        let tiffOnlyStoreTypesRejectString = capturedClip(from: tiffOnlyStringPasteboard, frontmostBundleIdentifier: nil) == nil

        let tiffOnlyPasteboard = makeScratchPasteboard(suffix: "tiffOnly")
        _ = writeDebugImagePasteboard(tiffOnlyPasteboard)
        let tiffOnlyClip = capturedClip(from: tiffOnlyPasteboard, frontmostBundleIdentifier: nil)
        let tiffOnlyStoreTypesAcceptImage = tiffOnlyClip?.types.contains(NSPasteboard.PasteboardType.tiff.rawValue) == true
            && tiffOnlyClip?.imageData?.isEmpty == false

        var disabledTIFFStoreTypes = ClipItem.defaultStoreTypes()
        disabledTIFFStoreTypes["TIFF"] = false
        defaults.set(disabledTIFFStoreTypes, forKey: CMPrefStoreTypesKey)
        let disabledTIFFPasteboard = makeScratchPasteboard(suffix: "disabledTIFF")
        _ = writeDebugImagePasteboard(disabledTIFFPasteboard)
        let disabledTIFFTypeRejected = capturedClip(from: disabledTIFFPasteboard, frontmostBundleIdentifier: nil) == nil

        var disabledRTFDStoreTypes = ClipItem.defaultStoreTypes()
        disabledRTFDStoreTypes["RTFD"] = false
        defaults.set(disabledRTFDStoreTypes, forKey: CMPrefStoreTypesKey)
        let disabledRTFDPasteboard = makeScratchPasteboard(suffix: "disabledRTFD")
        _ = writeDebugRTFDOnlyPasteboard(disabledRTFDPasteboard)
        let disabledRTFDTypeRejected = capturedClip(from: disabledRTFDPasteboard, frontmostBundleIdentifier: nil) == nil

        report["allDisabledStoreTypesRejectString"] = allDisabledStoreTypesRejectString
        report["allDisabledStoreTypesRejectPDF"] = allDisabledStoreTypesRejectPDF
        report["pdfOnlyStoreTypesRejectString"] = pdfOnlyStoreTypesRejectString
        report["pdfOnlyStoreTypesAcceptPDF"] = pdfOnlyStoreTypesAcceptPDF
        report["rtfOnlyStoreTypesRejectString"] = rtfOnlyStoreTypesRejectString
        report["rtfOnlyStoreTypesAcceptRTF"] = rtfOnlyStoreTypesAcceptRTF
        report["tiffOnlyStoreTypesRejectString"] = tiffOnlyStoreTypesRejectString
        report["tiffOnlyStoreTypesAcceptImage"] = tiffOnlyStoreTypesAcceptImage
        report["disabledTIFFTypeRejected"] = disabledTIFFTypeRejected
        report["disabledRTFDTypeRejected"] = disabledRTFDTypeRejected
        report["matchesExpected"] = allDisabledStoreTypesRejectString
            && allDisabledStoreTypesRejectPDF
            && pdfOnlyStoreTypesRejectString
            && pdfOnlyStoreTypesAcceptPDF
            && rtfOnlyStoreTypesRejectString
            && rtfOnlyStoreTypesAcceptRTF
            && tiffOnlyStoreTypesRejectString
            && tiffOnlyStoreTypesAcceptImage
            && disabledTIFFTypeRejected
            && disabledRTFDTypeRejected

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugTypedRenderingReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugTypedRenderingReportPath")
            ?? "/tmp/clipmenu-typed-rendering-report.json")
        var report: [String: Any] = [
            "usedIsolatedSupportDirectory": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
            return
        }

        let originalShowImage = defaults.object(forKey: CMPrefShowImageInTheMenuKey)
        let originalShowIcon = defaults.object(forKey: CMPrefShowIconInTheMenuKey)
        let originalThumbnailWidth = defaults.object(forKey: CMPrefThumbnailWidthKey)
        let originalThumbnailHeight = defaults.object(forKey: CMPrefThumbnailHeightKey)
        let originalMenuIconSize = defaults.object(forKey: CMPrefMenuIconSizeKey)

        defer {
            restoreDefault(originalShowImage, forKey: CMPrefShowImageInTheMenuKey)
            restoreDefault(originalShowIcon, forKey: CMPrefShowIconInTheMenuKey)
            restoreDefault(originalThumbnailWidth, forKey: CMPrefThumbnailWidthKey)
            restoreDefault(originalThumbnailHeight, forKey: CMPrefThumbnailHeightKey)
            restoreDefault(originalMenuIconSize, forKey: CMPrefMenuIconSizeKey)
            debugTerminateApplication()
        }

        func makeDeterministicDate(_ seconds: TimeInterval) -> Date {
            Date(timeIntervalSinceReferenceDate: seconds)
        }

        let visibleImageClip = ClipItem(
            types: [NSPasteboard.PasteboardType.tiff.rawValue],
            createdAt: makeDeterministicDate(500),
            lastUsedAt: makeDeterministicDate(500),
            text: "",
            imageData: debugImageData()
        )
        let iconFallbackPDFClip = ClipItem(
            types: [NSPasteboard.PasteboardType.pdf.rawValue],
            createdAt: makeDeterministicDate(600),
            lastUsedAt: makeDeterministicDate(600),
            text: "",
            pdfData: Data("pdf-icon-smoke".utf8)
        )

        defaults.set(true, forKey: CMPrefShowImageInTheMenuKey)
        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        defaults.set(4, forKey: CMPrefThumbnailWidthKey)
        defaults.set(6, forKey: CMPrefThumbnailHeightKey)
        let visibleImageItem = makeClipMenuItem(clip: visibleImageClip, globalIndex: 0, listNumber: 1)
        let showImageEnabledHasThumbnail = visibleImageItem.image != nil
        let showImageEnabledThumbnailFitsBounds = {
            guard let size = visibleImageItem.image?.size else { return false }
            return size.width <= 4.0 && size.height <= 6.0
        }()

        defaults.set(false, forKey: CMPrefShowImageInTheMenuKey)
        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        let hiddenImageItem = makeClipMenuItem(clip: visibleImageClip, globalIndex: 0, listNumber: 1)
        let showImageDisabledSuppressesImageClipImage = hiddenImageItem.image == nil

        defaults.set(false, forKey: CMPrefShowImageInTheMenuKey)
        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        let iconFallbackPDFItem = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let nonImageClipStillUsesIconWhenIconsEnabled = iconFallbackPDFItem.image != nil

        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        defaults.set(16, forKey: CMPrefMenuIconSizeKey)
        let icon16Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconSize16MatchesExpected = {
            guard let size = icon16Item.image?.size else { return false }
            return size.width == 16 && size.height == 16
        }()

        defaults.set(32, forKey: CMPrefMenuIconSizeKey)
        let icon32Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconSize32MatchesExpected = {
            guard let size = icon32Item.image?.size else { return false }
            return size.width == 32 && size.height == 32
        }()

        defaults.set(48, forKey: CMPrefMenuIconSizeKey)
        let icon48Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconSize48MatchesExpected = {
            guard let size = icon48Item.image?.size else { return false }
            return size.width == 48 && size.height == 48
        }()

        defaults.set(24, forKey: CMPrefMenuIconSizeKey)
        let icon24Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconSize24NormalizesToLegacy16 = {
            guard let size = icon24Item.image?.size else { return false }
            return size.width == 16 && size.height == 16
        }()

        defaults.set(false, forKey: CMPrefShowIconInTheMenuKey)
        let iconsDisabledItem = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconsDisabledSuppressesNonImageIcon = iconsDisabledItem.image == nil

        report["showImageEnabledHasThumbnail"] = showImageEnabledHasThumbnail
        report["showImageEnabledThumbnailFitsBounds"] = showImageEnabledThumbnailFitsBounds
        report["showImageDisabledSuppressesImageClipImage"] = showImageDisabledSuppressesImageClipImage
        report["nonImageClipStillUsesIconWhenIconsEnabled"] = nonImageClipStillUsesIconWhenIconsEnabled
        report["menuIconSize16MatchesExpected"] = menuIconSize16MatchesExpected
        report["menuIconSize32MatchesExpected"] = menuIconSize32MatchesExpected
        report["menuIconSize48MatchesExpected"] = menuIconSize48MatchesExpected
        report["menuIconSize24NormalizesToLegacy16"] = menuIconSize24NormalizesToLegacy16
        report["menuIconsDisabledSuppressesNonImageIcon"] = menuIconsDisabledSuppressesNonImageIcon
        report["matchesExpected"] = showImageEnabledHasThumbnail
            && showImageEnabledThumbnailFitsBounds
            && showImageDisabledSuppressesImageClipImage
            && nonImageClipStillUsesIconWhenIconsEnabled
            && menuIconSize16MatchesExpected
            && menuIconSize32MatchesExpected
            && menuIconSize48MatchesExpected
            && menuIconSize24NormalizesToLegacy16
            && menuIconsDisabledSuppressesNonImageIcon

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugTypeIconRoutingReport() {
