            restoreDefault(originalHowToChangeFontSize, forKey: CMPrefHowToChangeFontSizeKey)
            restoreDefault(originalShowIconInMenu, forKey: CMPrefShowIconInTheMenuKey)
            restoreDefault(originalMenuIconSize, forKey: CMPrefMenuIconSizeKey)
            restoreDefault(originalSelectedFontSize, forKey: CMPrefSelectedFontSizeKey)
            restoreDefault(originalShowLabels, forKey: CMPrefShowLabelsInMenuKey)
            restoreDefault(originalMarkNumbers, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
            restoreDefault(originalStartsFromZero, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
            debugTerminateApplication()
        }

        defaults.set(true, forKey: CMPrefChangeFontSizeKey)
        defaults.set(false, forKey: CMPrefShowLabelsInMenuKey)
        defaults.set(true, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        defaults.set(false, forKey: CMPrefMenuItemsTitleStartWithZeroKey)

        let clip = ClipItem(
            text: "font-size-smoke",
            createdAt: Date(timeIntervalSinceReferenceDate: 100),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 100)
        )

        func reportedFontSize(mode: Int, showIcons: Bool, iconSize: Int, selectedSize: Float) -> Double? {
            defaults.set(mode, forKey: CMPrefHowToChangeFontSizeKey)
            defaults.set(showIcons, forKey: CMPrefShowIconInTheMenuKey)
            defaults.set(iconSize, forKey: CMPrefMenuIconSizeKey)
            defaults.set(selectedSize, forKey: CMPrefSelectedFontSizeKey)
            let item = makeClipMenuItem(clip: clip, globalIndex: 0, listNumber: 1)
            guard
                let attributedTitle = item.attributedTitle,
                attributedTitle.length > 0,
                let font = attributedTitle.attribute(.font, at: 0, effectiveRange: nil) as? NSFont
            else {
                return nil
            }
            return Double(font.pointSize)
        }

        let iconHiddenSize = reportedFontSize(mode: 0, showIcons: false, iconSize: 16, selectedSize: 17)
        let icon16Size = reportedFontSize(mode: 0, showIcons: true, iconSize: 16, selectedSize: 17)
        let icon32Size = reportedFontSize(mode: 0, showIcons: true, iconSize: 32, selectedSize: 17)
        let icon48Size = reportedFontSize(mode: 0, showIcons: true, iconSize: 48, selectedSize: 17)
        let selectedPointSize = reportedFontSize(mode: 1, showIcons: true, iconSize: 48, selectedSize: 19)
        let verificationItem = makeClipMenuItem(clip: clip, globalIndex: 0, listNumber: 1)
        let actualState: [String: Any] = [
            "iconHiddenFontSize": iconHiddenSize ?? NSNull(),
            "icon16FontSize": icon16Size ?? NSNull(),
            "icon32FontSize": icon32Size ?? NSNull(),
            "icon48FontSize": icon48Size ?? NSNull(),
            "selectedPointFontSize": selectedPointSize ?? NSNull(),
            "verificationTitle": verificationItem.title,
            "verificationAction": verificationItem.action.map(NSStringFromSelector) ?? ""
        ]
        let expectedState: [String: Any] = [
            "iconHiddenFontSize": 14.0,
            "icon16FontSize": 14.0,
            "icon32FontSize": 28.0,
            "icon48FontSize": 42.0,
            "selectedPointFontSize": 16.0,
            "verificationTitle": "1. font-size-smoke",
            "verificationAction": "selectMenuItem:"
        ]

        let report: [String: Any] = [
            "iconHiddenFontSize": iconHiddenSize ?? NSNull(),
            "icon16FontSize": icon16Size ?? NSNull(),
            "icon32FontSize": icon32Size ?? NSNull(),
            "icon48FontSize": icon48Size ?? NSNull(),
            "selectedPointFontSize": selectedPointSize ?? NSNull(),
            "verificationTitle": verificationItem.title,
            "verificationAction": verificationItem.action.map(NSStringFromSelector) ?? "",
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpected": (actualState as NSDictionary).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

