    private func runDebugTypeThumbnailDimensionsNormalizationReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugTypeThumbnailDimensionsNormalizationReportPath")
            ?? "/tmp/clipmenu-type-thumbnail-dimensions-normalization-report.json")
        let originalClips = clipsStore.clips
        let originalShowImages = defaults.object(forKey: CMPrefShowImageInTheMenuKey)
        let originalShowIcons = defaults.object(forKey: CMPrefShowIconInTheMenuKey)
        let originalThumbnailWidth = defaults.object(forKey: CMPrefThumbnailWidthKey)
        let originalThumbnailHeight = defaults.object(forKey: CMPrefThumbnailHeightKey)

        defer {
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalShowImages, forKey: CMPrefShowImageInTheMenuKey)
            restoreDefault(originalShowIcons, forKey: CMPrefShowIconInTheMenuKey)
            restoreDefault(originalThumbnailWidth, forKey: CMPrefThumbnailWidthKey)
            restoreDefault(originalThumbnailHeight, forKey: CMPrefThumbnailHeightKey)
            rebuildMenu()
            debugTerminateApplication()
        }

        defaults.set(true, forKey: CMPrefShowImageInTheMenuKey)
        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        let imageClip = ClipItem(
            types: [NSPasteboard.PasteboardType.tiff.rawValue],
            createdAt: Date(timeIntervalSinceReferenceDate: 700),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 700),
            text: "",
            imageData: debugImageData()
        )
        let pixelLabel = NSLocalizedString("pixel", comment: "")

        func captureState(storedWidth: Int, storedHeight: Int) -> [String: Any] {
            defaults.set(storedWidth, forKey: CMPrefThumbnailWidthKey)
            defaults.set(storedHeight, forKey: CMPrefThumbnailHeightKey)
            userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

            let paneSnapshot = CMTypePreferencesSnapshotForDebug()
            let images = paneSnapshot["images"] as? [String: Any] ?? [:]
            let imageStates = images["states"] as? [String: Any] ?? [:]
            let menuItem = makeClipMenuItem(clip: imageClip, globalIndex: 0, listNumber: 1)
            let renderedSize = menuItem.image?.size

            return [
                "storedWidth": storedWidth,
                "storedHeight": storedHeight,
                "normalizedStoredThumbnailWidth": defaults.integer(forKey: CMPrefThumbnailWidthKey),
                "normalizedStoredThumbnailHeight": defaults.integer(forKey: CMPrefThumbnailHeightKey),
                "snapshotThumbnailWidth": imageStates["thumbnailWidth"] as? Int ?? -1,
                "snapshotThumbnailHeight": imageStates["thumbnailHeight"] as? Int ?? -1,
                "snapshotSummaryTitle": images["summaryTitle"] as? String ?? "",
                "snapshotDimensionBadges": images["dimensionBadges"] as? [String] ?? [],
                "renderedThumbnailSize": [
                    "width": renderedSize?.width ?? -1,
                    "height": renderedSize?.height ?? -1
                ],
                "renderedThumbnailFitsStoredBounds": (renderedSize?.width ?? -1) <= CGFloat(defaults.integer(forKey: CMPrefThumbnailWidthKey))
                    && (renderedSize?.height ?? -1) <= CGFloat(defaults.integer(forKey: CMPrefThumbnailHeightKey))
                    && (renderedSize?.width ?? -1) > 0
                    && (renderedSize?.height ?? -1) > 0
            ]
        }

        let minimumCaseState = captureState(storedWidth: 0, storedHeight: -3)
        let minimumCaseExpectedState: [String: Any] = [
            "storedWidth": 0,
            "storedHeight": -3,
            "normalizedStoredThumbnailWidth": 1,
            "normalizedStoredThumbnailHeight": 1,
            "snapshotThumbnailWidth": 1,
            "snapshotThumbnailHeight": 1,
            "snapshotSummaryTitle": "Image thumbnails: 1 x 1 px",
            "snapshotDimensionBadges": CMTypeThumbnailDimensionBadgeTitles(width: 1, height: 1, pixelLabel: pixelLabel),
            "renderedThumbnailSize": [
                "width": 1.0,
                "height": 1.0
            ],
            "renderedThumbnailFitsStoredBounds": true
        ]

        let largeCaseState = captureState(storedWidth: 120, storedHeight: 64)
        let largeCaseExpectedState: [String: Any] = [
            "storedWidth": 120,
            "storedHeight": 64,
            "normalizedStoredThumbnailWidth": 120,
            "normalizedStoredThumbnailHeight": 64,
            "snapshotThumbnailWidth": 120,
            "snapshotThumbnailHeight": 64,
            "snapshotSummaryTitle": "Image thumbnails: 120 x 64 px",
            "snapshotDimensionBadges": CMTypeThumbnailDimensionBadgeTitles(width: 120, height: 64, pixelLabel: pixelLabel),
            "renderedThumbnailSize": [
                "width": 16.0,
                "height": 16.0
            ],
            "renderedThumbnailFitsStoredBounds": true
        ]

        let report: [String: Any] = [
            "state": [
                "minimumCase": minimumCaseState,
                "largeCase": largeCaseState
            ],
            "expectedState": [
                "minimumCase": minimumCaseExpectedState,
                "largeCase": largeCaseExpectedState
            ],
            "matchesExpected": NSDictionary(dictionary: minimumCaseState).isEqual(to: minimumCaseExpectedState)
                && NSDictionary(dictionary: largeCaseState).isEqual(to: largeCaseExpectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

