            text: "",
            pdfData: Data("pdf-icon-normalization".utf8)
        )

        func normalizeCase(storedSelectionTag: Int) -> [String: Any] {
            defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
            defaults.set(storedSelectionTag, forKey: tagKey)
            defaults.set(defaultFileType, forKey: fileTypeKey)
            userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

            let menuItem = makeClipMenuItem(clip: pdfClip, globalIndex: 0, listNumber: 1)
            let normalizedTag = defaults.integer(forKey: tagKey)
            return [
                "storedSelectionTag": storedSelectionTag,
                "normalizedStoredSelectionTag": normalizedTag,
                "resolvedMode": normalizedTag == 1 ? "File Type Code" : "File Extension",
                "storedFileType": defaults.string(forKey: fileTypeKey) ?? "",
                "iconPresent": menuItem.image != nil
            ]
        }

        let highTagCase = normalizeCase(storedSelectionTag: 99)
        let negativeTagCase = normalizeCase(storedSelectionTag: -7)
        let actualState: [String: Any] = [
            "highTagCase": highTagCase,
            "negativeTagCase": negativeTagCase
        ]
        let expectedState: [String: Any] = [
            "highTagCase": [
                "storedSelectionTag": 99,
                "normalizedStoredSelectionTag": defaultSelectionTag,
                "resolvedMode": "File Extension",
                "storedFileType": defaultFileType,
                "iconPresent": true
            ],
            "negativeTagCase": [
                "storedSelectionTag": -7,
                "normalizedStoredSelectionTag": defaultSelectionTag,
                "resolvedMode": "File Extension",
                "storedFileType": defaultFileType,
                "iconPresent": true
            ]
        ]
        let report: [String: Any] = [
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpected": NSDictionary(dictionary: actualState).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

