    private func runDebugSnippetSelection() {
        let text = debugStringValue(forKey: "debugRunSnippetSelectionText") ?? "clipmenu snippet smoke"
        let snippet = SnippetActionReference(folderID: UUID(), snippetID: UUID(), content: text)
        rememberPasteTargetApplication()
        let item = NSMenuItem(title: "1. \(text)", action: #selector(selectSnippet(_:)), keyEquivalent: "")
        item.target = self
        item.representedObject = snippet
        debugPasteFlow("runDebugSnippetSelection firing title=\(item.title)")
        selectSnippet(item)
    }

