        let delay = debugDoubleValue(forKey: "debugRunSnippetStoreRoundTripAfterLaunchDelay")
        guard delay > 0 else { return }

        DispatchQueue.main.asyncAfter(deadline: .now() + delay) {
            self.runDebugSnippetStoreRoundTrip()
        }
