    private func scheduleDebugJavaScriptActionIfNeeded() {
        let delay = UserDefaults.standard.double(forKey: "debugRunJavaScriptActionAfterLaunchDelay")
        guard delay > 0 else { return }

        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            self?.runDebugJavaScriptAction()
        }
    }

    private func runDebugJavaScriptAction() {
        guard let scriptPath = UserDefaults.standard.string(forKey: "debugRunJavaScriptActionPath"),
              !scriptPath.isEmpty else {
            debugPasteFlow("runDebugJavaScriptAction noScriptPath")
            return
        }

        let text = UserDefaults.standard.string(forKey: "debugRunJavaScriptActionText") ?? "clipmenu debug action"
        debugPasteFlow("runDebugJavaScriptAction begin path=\(scriptPath) text=\(text)")
        guard let result = runJavaScriptAction(at: scriptPath, clip: ClipItem(text: text)) else {
            debugPasteFlow("runDebugJavaScriptAction result=nil")
            return
        }

        debugPasteFlow("runDebugJavaScriptAction result text=\(result.text) types=\(result.types.joined(separator: ","))")
    }

    private func scheduleDebugActionMenuSelectionIfNeeded() {
        let delay = UserDefaults.standard.double(forKey: "debugRunActionMenuSelectionAfterLaunchDelay")
        guard delay > 0 else { return }

        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            self?.runDebugActionMenuSelection()
        }
    }

    private func runDebugActionMenuSelection() {
        let itemTitle = UserDefaults.standard.string(forKey: "debugRunActionMenuSelectionTitle") ?? "UPPERCASE.js"
        let text = UserDefaults.standard.string(forKey: "debugRunActionMenuSelectionText") ?? "clipmenu action menu smoke"
        let clip = ClipItem(text: text)
        clipsStore.add(clip)
        actionTarget = .clip(clip.id)
        let oldInputPasteCommand = UserDefaults.standard.object(forKey: CMPrefInputPasteCommandKey)
        let allowsPaste = UserDefaults.standard.bool(forKey: "debugRunActionMenuSelectionAllowsPaste")
        if allowsPaste {
            rememberPasteTargetApplication()
        }
        if !allowsPaste {
            UserDefaults.standard.set(false, forKey: CMPrefInputPasteCommandKey)
        }
        defer {
            actionTarget = nil
            clipsStore.remove(clip.id)
            rebuildMenu()
            if let oldInputPasteCommand {
                UserDefaults.standard.set(oldInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            } else {
                UserDefaults.standard.removeObject(forKey: CMPrefInputPasteCommandKey)
            }
        }

        let menu = makeActionMenu()
        debugPasteFlow("runDebugActionMenuSelection menuItems=\(menu.numberOfItems) title=\(itemTitle)")
        guard let item = menuItem(withTitle: itemTitle, in: menu) else {
            debugPasteFlow("runDebugActionMenuSelection missing title=\(itemTitle)")
            return
        }

        debugPasteFlow("runDebugActionMenuSelection firing title=\(item.title)")
        selectAction(item)
        let pasteboardText = NSPasteboard.general.string(forType: .string) ?? ""
        debugPasteFlow("runDebugActionMenuSelection pasteboardText=\(pasteboardText)")
    }

    private func scheduleDebugVisibleActionMenuIfNeeded() {
        let delay = UserDefaults.standard.double(forKey: "debugShowVisibleActionMenuAfterLaunchDelay")
        guard delay > 0 else { return }

        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            self?.runDebugVisibleActionMenu()
        }
    }

    private func runDebugVisibleActionMenu() {
        let text = UserDefaults.standard.string(forKey: "debugVisibleActionMenuText") ?? "clipmenu visible action smoke"
        let clip = ClipItem(text: text)
        clipsStore.add(clip)
        actionTarget = .clip(clip.id)
        let oldInputPasteCommand = UserDefaults.standard.object(forKey: CMPrefInputPasteCommandKey)
        UserDefaults.standard.set(false, forKey: CMPrefInputPasteCommandKey)
        defer {
            actionTarget = nil
            clipsStore.remove(clip.id)
            rebuildMenu()
            if let oldInputPasteCommand {
                UserDefaults.standard.set(oldInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            } else {
                UserDefaults.standard.removeObject(forKey: CMPrefInputPasteCommandKey)
            }
            let pasteboardText = NSPasteboard.general.string(forType: .string) ?? ""
            debugPasteFlow("runDebugVisibleActionMenu pasteboardText=\(pasteboardText)")
            if UserDefaults.standard.bool(forKey: "debugTerminateAfterVisibleActionMenu") {
                debugTerminateApplication()
            }
        }

        let menu = makeActionMenu()
        debugPasteFlow("runDebugVisibleActionMenu popup menuItems=\(menu.numberOfItems)")
        popUpMenuAtMouseLocation(menu, style: .action)
        debugPasteFlow("runDebugVisibleActionMenu closed")
    }

    private func menuItem(withTitle title: String, in menu: NSMenu) -> NSMenuItem? {
        for item in menu.items {
            if normalizedMenuItemTitle(item.title) == normalizedMenuItemTitle(title) {
                return item
            }
            if let submenu = item.submenu,
               let child = menuItem(withTitle: title, in: submenu) {
                return child
            }
        }
        return nil
    }

    private func scheduleDebugPasteboardRoundTripIfNeeded() {
        let delay = UserDefaults.standard.double(forKey: "debugRunPasteboardRoundTripAfterLaunchDelay")
        guard delay > 0 else { return }

        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            self?.runDebugPasteboardRoundTrip()
        }
    }

    private func runDebugPasteboardRoundTrip() {
        let cases: [(String, (NSPasteboard) -> Bool, (ClipItem, NSPasteboard) -> Bool)] = [
            ("rtf", writeDebugRTFPasteboard, verifyDebugRTFRoundTrip),
            ("pdf", writeDebugPDFPasteboard, verifyDebugPDFRoundTrip),
            ("fileURL", writeDebugFileURLPasteboard, verifyDebugFileURLRoundTrip),
            ("url", writeDebugURLPasteboard, verifyDebugURLRoundTrip),
            ("image", writeDebugImagePasteboard, verifyDebugImageRoundTrip)
        ]

        for testCase in cases {
            let input = NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.input.\(UUID().uuidString)"))
            let output = NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.output.\(UUID().uuidString)"))
            guard testCase.1(input) else {
                debugPasteFlow("runDebugPasteboardRoundTrip \(testCase.0) setup=false")
                continue
            }
            guard let clip = ClipItem.fromPasteboard(input) else {
                debugPasteFlow("runDebugPasteboardRoundTrip \(testCase.0) captured=false inputTypes=\((input.types ?? []).map(\.rawValue).joined(separator: ","))")
                continue
            }

            clip.write(to: output)
            let passed = testCase.2(clip, output)
            debugPasteFlow("runDebugPasteboardRoundTrip \(testCase.0) passed=\(passed) clipTypes=\(clip.types.joined(separator: ",")) outputTypes=\((output.types ?? []).map(\.rawValue).joined(separator: ",")) text=\(clip.text)")
        }
    }

    private func runDebugOpenRecentMenuReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugOpenRecentMenuReportPath")
            ?? "/tmp/clipmenu-open-recent-menu-report.json")
        let documentController = NSDocumentController.shared
        let testURL = URL(fileURLWithPath: "/tmp/clipmenu-open-recent-smoke.txt")
        let originalRecentDocumentURLs = documentController.recentDocumentURLs
        try? "open recent smoke".write(to: testURL, atomically: true, encoding: .utf8)

        func openRecentSubmenu(from menu: NSMenu?) -> NSMenu? {
            menu?.items
                .first(where: { $0.title == NSLocalizedString("File", comment: "") })?
                .submenu?
                .items
                .first(where: { $0.title == NSLocalizedString("Open Recent", comment: "") })?
                .submenu
        }

        func menuTitles(_ menu: NSMenu?) -> [String] {
            menu?.items.map { $0.isSeparatorItem ? "<separator>" : $0.title } ?? []
        }

        defer {
            restoreRecentDocumentURLs(originalRecentDocumentURLs, documentController: documentController)
            try? FileManager.default.removeItem(at: testURL)
            debugTerminateApplication()
        }

        let beforeURLs = documentController.recentDocumentURLs.map { $0.resolvingSymlinksInPath().path }
        documentController.clearRecentDocuments(nil)
        installMainMenu()
        let openRecentMenuBefore = openRecentSubmenu(from: NSApp.mainMenu)
        let openRecentTitlesBefore = menuTitles(openRecentMenuBefore)
        let clearMenuEnabledBefore = openRecentMenuBefore?
            .items
            .first(where: { $0.title == NSLocalizedString("Clear Menu", comment: "") })?
            .isEnabled

        documentController.noteNewRecentDocumentURL(testURL)
        refreshMainMenuDocumentItems(nil)
        let afterURLs = documentController.recentDocumentURLs.map { $0.resolvingSymlinksInPath().path }
        let openRecentMenuAfter = openRecentSubmenu(from: NSApp.mainMenu)
        let openRecentTitlesAfter = menuTitles(openRecentMenuAfter)
        let clearMenuItem = openRecentMenuAfter?
            .items
            .first(where: { $0.title == NSLocalizedString("Clear Menu", comment: "") })
        let clearMenuEnabledAfter = clearMenuItem?.isEnabled
        clearMenuItem.map(clearRecentSnippetDocuments(_:))
        let afterClearURLs = documentController.recentDocumentURLs.map { $0.resolvingSymlinksInPath().path }
        let openRecentMenuAfterClear = openRecentSubmenu(from: NSApp.mainMenu)
        let openRecentTitlesAfterClear = menuTitles(openRecentMenuAfterClear)
        let clearMenuEnabledAfterClear = openRecentMenuAfterClear?
            .items
            .first(where: { $0.title == NSLocalizedString("Clear Menu", comment: "") })?
            .isEnabled
        installMainMenu()
        let rebuiltOpenRecentTitlesAfter = menuTitles(openRecentSubmenu(from: NSApp.mainMenu))
        let expectedBeforeURLs: [String] = []
        let expectedAfterURLs = [testURL.resolvingSymlinksInPath().path]
        let expectedAfterClearURLs: [String] = []
        let expectedOpenRecentTitlesBefore = [NSLocalizedString("Clear Menu", comment: "")]
        let expectedOpenRecentTitlesAfter = [testURL.lastPathComponent, "<separator>", NSLocalizedString("Clear Menu", comment: "")]
        let expectedOpenRecentTitlesAfterClear = [NSLocalizedString("Clear Menu", comment: "")]
        let expectedRebuiltOpenRecentTitlesAfter = [NSLocalizedString("Clear Menu", comment: "")]

        let report: [String: Any] = [
            "beforeURLs": beforeURLs,
            "afterURLs": afterURLs,
            "afterClearURLs": afterClearURLs,
            "openRecentTitlesBefore": openRecentTitlesBefore,
            "openRecentTitlesAfter": openRecentTitlesAfter,
            "openRecentTitlesAfterClear": openRecentTitlesAfterClear,
            "rebuiltOpenRecentTitlesAfter": rebuiltOpenRecentTitlesAfter,
            "clearMenuEnabledBefore": clearMenuEnabledBefore as Any,
            "clearMenuEnabledAfter": clearMenuEnabledAfter as Any,
            "clearMenuEnabledAfterClear": clearMenuEnabledAfterClear as Any,
            "expectedBeforeURLs": expectedBeforeURLs,
            "expectedAfterURLs": expectedAfterURLs,
            "expectedAfterClearURLs": expectedAfterClearURLs,
            "expectedOpenRecentTitlesBefore": expectedOpenRecentTitlesBefore,
            "expectedOpenRecentTitlesAfter": expectedOpenRecentTitlesAfter,
            "expectedOpenRecentTitlesAfterClear": expectedOpenRecentTitlesAfterClear,
            "expectedRebuiltOpenRecentTitlesAfter": expectedRebuiltOpenRecentTitlesAfter,
            "recentDocumentsContainsTestURL": afterURLs.contains(testURL.resolvingSymlinksInPath().path),
            "menuContainsRecentEntry": openRecentTitlesAfter.contains(testURL.lastPathComponent),
            "rebuiltMenuContainsRecentEntry": rebuiltOpenRecentTitlesAfter.contains(testURL.lastPathComponent),
            "clearMenuItemPresent": openRecentTitlesAfter.contains(NSLocalizedString("Clear Menu", comment: "")),
            "matchesExpected": beforeURLs == expectedBeforeURLs
                && afterURLs == expectedAfterURLs
                && afterClearURLs == expectedAfterClearURLs
                && openRecentTitlesBefore == expectedOpenRecentTitlesBefore
                && openRecentTitlesAfter == expectedOpenRecentTitlesAfter
                && openRecentTitlesAfterClear == expectedOpenRecentTitlesAfterClear
                && rebuiltOpenRecentTitlesAfter == expectedRebuiltOpenRecentTitlesAfter
                && clearMenuEnabledBefore == false
                && clearMenuEnabledAfter == true
                && clearMenuEnabledAfterClear == false
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugOpenRecentImportReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugOpenRecentImportReportPath")
            ?? "/tmp/clipmenu-open-recent-import-report.json")
        let documentController = NSDocumentController.shared
