    private func runDebugMalformedActionsReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugMalformedActionsReportPath")
            ?? "/tmp/clipmenu-malformed-actions-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
            return
        }

        let fileManager = FileManager.default
        let actionsFileURL = supportDirectory.appendingPathComponent("actions.plist")
        let legacyArchiveURL = supportDirectory.appendingPathComponent("actionMenu.data")

        defer {
            try? fileManager.removeItem(at: actionsFileURL)
            try? fileManager.removeItem(at: legacyArchiveURL)
            CMReloadActionPreferences()
            rebuildMenu()
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
        }

        do {
            try "not a property list".write(to: actionsFileURL, atomically: true, encoding: .utf8)

            let removeNode = LegacyRuntimeArchivedActionNode()
            removeNode.nodeTitle = "Remove"
            removeNode.isLeaf = true
            removeNode.action = ["name": "removeAction"]

            let folderNode = LegacyRuntimeArchivedActionNode()
            folderNode.nodeTitle = "Legacy Fallback"
            folderNode.isLeaf = false
            folderNode.children = []

            let archiveData = try NSKeyedArchiver.archivedData(
                withRootObject: [removeNode, folderNode],
                requiringSecureCoding: false
            )
            try archiveData.write(to: legacyArchiveURL, options: .atomic)
        } catch {
            report["error"] = error.localizedDescription
            return
        }

        CMReloadActionPreferences()

        let runtimeNodes = loadRuntimeActionNodes()
        let actionMenu = makeActionMenu()
        let preferenceTitles = CMCurrentActionPreferenceTitles()

        report["runtimeTopLevelTitles"] = runtimeNodes.map(\.nodeTitle)
        report["runtimeTopLevelCount"] = runtimeNodes.count
        report["preferenceTopLevelTitles"] = preferenceTitles
        report["preferenceTopLevelCount"] = preferenceTitles.count
        report["menuTopLevelTitles"] = actionMenu.items.map(\.title)
        report["menuTopLevelCount"] = actionMenu.items.count
        report["menuContainsLegacyFallback"] = actionMenu.items.contains { $0.title == "Legacy Fallback" }
        report["runtimeContainsLegacyFallback"] = runtimeNodes.contains { $0.nodeTitle == "Legacy Fallback" }
        report["runtimeContainsDefaultPasteAsPlainText"] = runtimeNodes.contains { $0.nodeTitle == NSLocalizedString("Paste as Plain Text", comment: "") }
        report["preferenceContainsDefaultPasteAsPlainText"] = preferenceTitles.contains(NSLocalizedString("Paste as Plain Text", comment: ""))
        report["treatsMalformedPlistAsAuthoritativeEmpty"] =
            runtimeNodes.isEmpty
            && preferenceTitles.isEmpty
            && actionMenu.items.isEmpty
        report["matchesExpected"] = report["treatsMalformedPlistAsAuthoritativeEmpty"] as? Bool == true
            && (report["runtimeContainsLegacyFallback"] as? Bool) == false
            && (report["menuContainsLegacyFallback"] as? Bool) == false
            && (report["runtimeContainsDefaultPasteAsPlainText"] as? Bool) == false
            && (report["preferenceContainsDefaultPasteAsPlainText"] as? Bool) == false
    }

    private func runDebugJavaScriptActionErrorReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugJavaScriptActionErrorReportPath")
            ?? "/tmp/clipmenu-javascript-action-error-report.json")
        let fileManager = FileManager.default
        let temporaryDirectory = fileManager.temporaryDirectory
            .appendingPathComponent("clipmenu-js-action-error-\(UUID().uuidString)", isDirectory: true)
        let throwingScriptURL = temporaryDirectory.appendingPathComponent("Throw.js")
        let originalClips = clipsStore.clips
        let originalActionTarget = actionTarget
        let originalDebugAlertLogging = defaults.object(forKey: "debugJavaScriptAlertsAreLogged")

        defer {
            restoreDefault(originalDebugAlertLogging, forKey: "debugJavaScriptAlertsAreLogged")
            actionTarget = originalActionTarget
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            try? fileManager.removeItem(at: temporaryDirectory)
            debugLastJavaScriptAlertTitle = nil
            debugLastJavaScriptAlertMessage = nil
            debugTerminateApplication()
        }

        defaults.set(true, forKey: "debugJavaScriptAlertsAreLogged")
        clipsStore.clear()
        let clip = ClipItem(text: "javascript error smoke")
        clipsStore.add(clip)
        actionTarget = .clip(clip.id)

        func captureAlert(for action: [String: String], sentinel: String) -> [String: Any] {
            pasteboard.clearContents()
            pasteboard.setString(sentinel, forType: .string)
            debugLastJavaScriptAlertTitle = nil
            debugLastJavaScriptAlertMessage = nil
            invokeAction(action, target: .clip(clip.id))
            let resultingText = pasteboard.string(forType: .string) ?? ""
            return [
                "alertTitle": debugLastJavaScriptAlertTitle as Any,
                "alertMessage": debugLastJavaScriptAlertMessage as Any,
                "pasteboardTextAfter": resultingText,
                "pasteboardUnchanged": resultingText == sentinel
            ]
        }

        do {
            try fileManager.createDirectory(at: temporaryDirectory, withIntermediateDirectories: true)
            try "throw new Error('codex debug exception');".write(to: throwingScriptURL, atomically: true, encoding: .utf8)
        } catch {
            let report: [String: Any] = [
                "error": "Could not create JavaScript action error fixture",
                "details": error.localizedDescription
            ]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        let missingResult = captureAlert(
            for: ["type": "js", "path": temporaryDirectory.appendingPathComponent("Missing.js").path],
            sentinel: "missing script sentinel"
        )
        let exceptionResult = captureAlert(
            for: ["type": "js", "path": throwingScriptURL.path],
            sentinel: "script exception sentinel"
        )

        let report: [String: Any] = [
            "missingScript": [
                "alertTitle": missingResult["alertTitle"] as Any,
                "alertMessage": missingResult["alertMessage"] as Any,
                "pasteboardTextAfter": missingResult["pasteboardTextAfter"] as Any,
                "pasteboardUnchanged": missingResult["pasteboardUnchanged"] as Any,
                "matchesExpectedAlert": (missingResult["alertTitle"] as? String) == NSLocalizedString("The script you selected does not exist", comment: "")
                    && ((missingResult["alertMessage"] as? String) ?? "").isEmpty
            ],
            "scriptException": [
                "alertTitle": exceptionResult["alertTitle"] as Any,
                "alertMessage": exceptionResult["alertMessage"] as Any,
                "pasteboardTextAfter": exceptionResult["pasteboardTextAfter"] as Any,
                "pasteboardUnchanged": exceptionResult["pasteboardUnchanged"] as Any,
                "matchesExpectedAlert": (exceptionResult["alertTitle"] as? String) == NSLocalizedString("Script Exception Raised", comment: "")
                    && (exceptionResult["alertMessage"] as? String) == "Error: codex debug exception"
            ]
        ]
        let matchesExpected = ((missingResult["pasteboardUnchanged"] as? Bool) == true)
            && ((exceptionResult["pasteboardUnchanged"] as? Bool) == true)
            && ((((report["missingScript"] as? [String: Any])?["matchesExpectedAlert"]) as? Bool) == true)
            && ((((report["scriptException"] as? [String: Any])?["matchesExpectedAlert"]) as? Bool) == true)
        var finalizedReport = report
        finalizedReport["matchesExpected"] = matchesExpected

        if let data = try? JSONSerialization.data(withJSONObject: finalizedReport, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugJavaScriptDialogsReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugJavaScriptDialogsReportPath")
            ?? "/tmp/clipmenu-javascript-dialogs-report.json")

        func accessoryTextValues(for alert: NSAlert) -> [String] {
            guard let accessoryView = alert.accessoryView else { return [] }
            var values: [String] = []
            func collect(from view: NSView) {
                if let textField = view as? NSTextField {
                    let value = textField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
                    if !value.isEmpty {
                        values.append(value)
                    }
                }
                for subview in view.subviews {
                    collect(from: subview)
                }
            }
            collect(from: accessoryView)
            return Array(NSOrderedSet(array: values)) as? [String] ?? values
        }

        let alert = makeJavaScriptBridgeAlert(message: "Sample JavaScript alert")
        let fallbackAlert = makeJavaScriptBridgeAlert(message: nil)
        let confirm = makeJavaScriptBridgeConfirm(message: "Sample JavaScript confirmation")
        let fallbackConfirm = makeJavaScriptBridgeConfirm(message: "")
        let prompt = makeJavaScriptPromptDialog(message: "Sample JavaScript prompt", defaultValue: "Default value")
        let fallbackPrompt = makeJavaScriptPromptDialog(message: nil, defaultValue: nil)
        let errorAlert = makeJavaScriptActionFailureAlert(
            title: NSLocalizedString("Script Error", comment: ""),
            message: "Sample JavaScript error."
        )

        let alertState: [String: Any] = [
            "messageText": alert.messageText,
            "informativeText": alert.informativeText,
            "buttonTitles": alert.buttons.map(\.title),
            "hasAccessoryView": alert.accessoryView != nil,
            "accessoryTextValues": accessoryTextValues(for: alert)
        ]
        let expectedAlertState: [String: Any] = [
            "messageText": "Sample JavaScript alert",
            "informativeText": "",
            "buttonTitles": [NSLocalizedString("OK", comment: "")],
            "hasAccessoryView": true,
            "accessoryTextValues": [
                localizedJavaScriptBridgeAlertAccessoryTitle(),
                localizedJavaScriptBridgeAlertAccessoryDetail()
            ]
        ]
        let fallbackAlertState: [String: Any] = [
            "messageText": fallbackAlert.messageText,
            "buttonTitles": fallbackAlert.buttons.map(\.title)
        ]
        let expectedFallbackAlertState: [String: Any] = [
            "messageText": NSLocalizedString("JavaScript Alert", comment: ""),
            "buttonTitles": [NSLocalizedString("OK", comment: "")]
        ]
        let confirmState: [String: Any] = [
            "messageText": confirm.messageText,
            "informativeText": confirm.informativeText,
            "buttonTitles": confirm.buttons.map(\.title),
            "hasAccessoryView": confirm.accessoryView != nil,
            "accessoryTextValues": accessoryTextValues(for: confirm)
        ]
        let expectedConfirmState: [String: Any] = [
            "messageText": "Sample JavaScript confirmation",
            "informativeText": "",
            "buttonTitles": [
                NSLocalizedString("OK", comment: ""),
                NSLocalizedString("Cancel", comment: "")
            ],
            "hasAccessoryView": true,
            "accessoryTextValues": [
                localizedJavaScriptBridgeConfirmAccessoryTitle(),
                localizedJavaScriptBridgeConfirmAccessoryDetail()
            ]
        ]
        let fallbackConfirmState: [String: Any] = [
            "messageText": fallbackConfirm.messageText,
            "buttonTitles": fallbackConfirm.buttons.map(\.title)
        ]
        let expectedFallbackConfirmState: [String: Any] = [
            "messageText": NSLocalizedString("Confirm", comment: ""),
            "buttonTitles": [
                NSLocalizedString("OK", comment: ""),
                NSLocalizedString("Cancel", comment: "")
            ]
        ]
        let promptState: [String: Any] = [
            "messageText": prompt.alert.messageText,
            "informativeText": prompt.alert.informativeText,
            "buttonTitles": prompt.alert.buttons.map(\.title),
            "hasAccessoryView": prompt.alert.accessoryView != nil,
            "accessoryTextValues": accessoryTextValues(for: prompt.alert),
            "inputStringValue": prompt.input.stringValue
        ]
        let expectedPromptState: [String: Any] = [
            "messageText": "Sample JavaScript prompt",
            "informativeText": "",
            "buttonTitles": [
                NSLocalizedString("OK", comment: ""),
                NSLocalizedString("Cancel", comment: "")
            ],
            "hasAccessoryView": true,
            "accessoryTextValues": [
                localizedJavaScriptBridgePromptAccessoryTitle(),
                localizedJavaScriptBridgePromptAccessoryDetail(),
                "Default value"
            ],
            "inputStringValue": "Default value"
        ]
        let fallbackPromptState: [String: Any] = [
            "messageText": fallbackPrompt.alert.messageText,
            "buttonTitles": fallbackPrompt.alert.buttons.map(\.title),
            "inputStringValue": fallbackPrompt.input.stringValue
        ]
        let expectedFallbackPromptState: [String: Any] = [
            "messageText": NSLocalizedString("Input", comment: ""),
            "buttonTitles": [
                NSLocalizedString("OK", comment: ""),
                NSLocalizedString("Cancel", comment: "")
            ],
            "inputStringValue": ""
        ]
        let errorAlertState: [String: Any] = [
            "messageText": errorAlert.messageText,
            "informativeText": errorAlert.informativeText,
            "buttonTitles": errorAlert.buttons.map(\.title),
            "hasAccessoryView": errorAlert.accessoryView != nil,
            "accessoryTextValues": accessoryTextValues(for: errorAlert)
        ]
        let expectedErrorAlertState: [String: Any] = [
