    private func runDebugActionSupportDirectoryReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugActionSupportDirectoryReportPath")
            ?? "/tmp/clipmenu-action-support-directory-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
            return
        }

        let fileManager = FileManager.default
        let actionsFileURL = supportDirectory.appendingPathComponent("actions.plist")
        let actionFolderURL = supportDirectory
            .appendingPathComponent("script/action", isDirectory: true)
            .appendingPathComponent("Fixture Folder", isDirectory: true)
        let actionScriptURL = actionFolderURL.appendingPathComponent("Fixture Script.js")
        let libraryDirectoryURL = supportDirectory.appendingPathComponent("script/lib", isDirectory: true)
        let libraryScriptURL = libraryDirectoryURL.appendingPathComponent("fixture-helper.js")

        let clip = ClipItem(text: "action support smoke")
        clipsStore.add(clip)
        actionTarget = .clip(clip.id)

        defer {
            actionTarget = nil
            clipsStore.remove(clip.id)
            try? fileManager.removeItem(at: actionsFileURL)
            try? fileManager.removeItem(at: actionScriptURL)
            try? fileManager.removeItem(at: libraryScriptURL)
            try? fileManager.removeItem(at: actionFolderURL)
            try? fileManager.removeItem(at: libraryDirectoryURL)
            rebuildMenu()
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
        }

        do {
            try fileManager.createDirectory(at: actionFolderURL, withIntermediateDirectories: true)
            try fileManager.createDirectory(at: libraryDirectoryURL, withIntermediateDirectories: true)

            try "function fixtureTransform(text) { return text.toUpperCase() + \" via lib\"; }"
                .write(to: libraryScriptURL, atomically: true, encoding: .utf8)
            try """
            if (!ClipMenu.require("fixture-helper")) {
                throw new Error("require failed");
            }
            return fixtureTransform(clip.stringValue);
            """
                .write(to: actionScriptURL, atomically: true, encoding: .utf8)

            let payload: [[String: Any]] = [[
                "nodeTitle": "Fixture Folder",
                "isLeaf": false,
                "children": [[
                    "nodeTitle": "Fixture Script",
                    "isLeaf": true,
                    "action": [
                        "type": "js",
                        "path": "script/action/Fixture Folder/Fixture Script.js"
                    ]
                ]]
            ]]
            let data = try PropertyListSerialization.data(
                fromPropertyList: payload,
                format: .xml,
                options: 0
            )
            try data.write(to: actionsFileURL, options: .atomic)
        } catch {
            report["error"] = error.localizedDescription
            return
        }

        let nodes = loadRuntimeActionNodes()
        report["topLevelTitles"] = nodes.map(\.nodeTitle)

        let menu = makeActionMenu()
        let folderItems = menu.items.filter { $0.submenu != nil }
        report["menuTopLevelTitles"] = menu.items.map(\.title)
        report["menuFolderTitles"] = folderItems.map(\.title)
        let fixtureItem = folderItems
            .first { $0.title == "Fixture Folder" }?
            .submenu?.items
            .first { $0.title == "Fixture Script" }
        report["menuContainsFixtureFolder"] = folderItems.contains { $0.title == "Fixture Folder" }
        report["menuContainsFixtureScript"] = fixtureItem != nil

        if let action = fixtureItem?.representedObject as? [String: String] {
            report["fixtureActionType"] = action["type"] ?? ""
            report["fixtureActionPath"] = action["path"] ?? ""
            report["resolvedFixtureScriptPath"] = resolvedActionScriptURL(for: action["path"] ?? "")?.path ?? ""
            let result = action["path"].flatMap { path in
                runJavaScriptAction(at: path, clip: clip)
            }
            report["resultText"] = result?.text ?? ""
            report["resultMatchesExpected"] = result?.text == "ACTION SUPPORT SMOKE via lib"
            let actualState: [String: Any] = [
                "topLevelTitles": nodes.map(\.nodeTitle),
                "menuContainsFixtureFolder": folderItems.contains { $0.title == "Fixture Folder" },
                "menuContainsFixtureScript": fixtureItem != nil,
                "fixtureActionType": action["type"] ?? "",
                "fixtureActionPath": action["path"] ?? "",
                "resolvedFixtureScriptPath": resolvedActionScriptURL(for: action["path"] ?? "")?.path ?? "",
                "resultText": result?.text ?? ""
            ]
            let expectedState: [String: Any] = [
                "topLevelTitles": ["Fixture Folder"],
                "menuContainsFixtureFolder": true,
                "menuContainsFixtureScript": true,
                "fixtureActionType": "js",
                "fixtureActionPath": "script/action/Fixture Folder/Fixture Script.js",
                "resolvedFixtureScriptPath": actionScriptURL.path,
                "resultText": "ACTION SUPPORT SMOKE via lib"
            ]
            report["state"] = actualState
            report["expectedState"] = expectedState
            report["matchesExpected"] = NSDictionary(dictionary: actualState).isEqual(to: expectedState)
        } else {
            report["matchesExpected"] = false
        }
    }

