            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
            return
        }

        let fileManager = FileManager.default
        let legacyURL = supportDirectory.appendingPathComponent("clips.data")
        let jsonURL = supportDirectory.appendingPathComponent("clips.json")
        let defaults = UserDefaults.standard
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)

        defer {
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            try? fileManager.removeItem(at: legacyURL)
            try? fileManager.removeItem(at: jsonURL)
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            debugTerminateApplication()
        }

        do {
            try fileManager.createDirectory(at: supportDirectory, withIntermediateDirectories: true)
            try? fileManager.removeItem(at: legacyURL)
            try? fileManager.removeItem(at: jsonURL)

            let fixtures = [
                DebugLegacyArchiveClip(
                    types: ["NSStringPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 100),
                    stringValue: "legacy-string"
                ),
                DebugLegacyArchiveClip(
                    types: ["NSRTFPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 200),
                    stringValue: "legacy-rtf",
                    rtfData: Data("{\\rtf1\\ansi legacy-rtf}".utf8)
                ),
                DebugLegacyArchiveClip(
                    types: ["NSPDFPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 300),
                    stringValue: "legacy-pdf",
                    pdfData: Data("legacy-pdf".utf8)
                ),
                DebugLegacyArchiveClip(
                    types: ["NSFilenamesPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 400),
                    stringValue: "legacy-files",
                    filenames: ["/tmp/legacy-a.txt", "/tmp/legacy-b.txt"]
                ),
                DebugLegacyArchiveClip(
                    types: ["Apple URL pasteboard type"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 500),
                    stringValue: "legacy-url",
                    urls: ["https://example.com/legacy"]
                ),
                DebugLegacyArchiveClip(
                    types: ["NSPICTPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 600),
                    stringValue: "legacy-image",
                    imageData: Data([0x01, 0x02, 0x03, 0x04])
                )
            ]
            let legacyData = try DebugLegacyArchiveClip.archivedData(for: fixtures)
            try legacyData.write(to: legacyURL, options: .atomic)
        } catch {
            report["error"] = error.localizedDescription
            return
        }

        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        let untrimmedStore = ClipStore()
        untrimmedStore.load()
        let untrimmedOrderedTexts = untrimmedStore.orderedClips.map(\.text)
        let untrimmedPrimaryTypes = untrimmedStore.orderedClips.compactMap { $0.primaryPasteboardType?.rawValue }
        let untrimmedCountsByType = Dictionary(
            grouping: untrimmedStore.orderedClips,
            by: { $0.primaryPasteboardType?.rawValue ?? "" }
        ).mapValues(\.count)

        defaults.set(3, forKey: CMPrefMaxHistorySizeKey)
        let trimmedStore = ClipStore()
        trimmedStore.load()
        let trimmedOrderedTexts = trimmedStore.orderedClips.map(\.text)

        report["legacyArchiveExistsAfterWrite"] = fileManager.fileExists(atPath: legacyURL.path)
        report["jsonSidecarExistsAfterLoad"] = fileManager.fileExists(atPath: jsonURL.path)
        report["untrimmedCount"] = untrimmedStore.clips.count
        report["untrimmedOrderedTexts"] = untrimmedOrderedTexts
        report["untrimmedPrimaryTypes"] = untrimmedPrimaryTypes
        report["untrimmedCountsByPrimaryType"] = untrimmedCountsByType
        report["trimmedCount"] = trimmedStore.clips.count
        report["trimmedOrderedTexts"] = trimmedOrderedTexts
        let actualState: [String: Any] = [
            "legacyArchiveExistsAfterWrite": fileManager.fileExists(atPath: legacyURL.path),
            "jsonSidecarExistsAfterLoad": fileManager.fileExists(atPath: jsonURL.path),
            "untrimmedOrderedTexts": untrimmedOrderedTexts,
            "untrimmedPrimaryTypes": untrimmedPrimaryTypes,
            "untrimmedCountsByPrimaryType": untrimmedCountsByType,
            "trimmedOrderedTexts": trimmedOrderedTexts
        ]
        let expectedState: [String: Any] = [
            "legacyArchiveExistsAfterWrite": true,
            "jsonSidecarExistsAfterLoad": true,
            "untrimmedOrderedTexts": [
                "legacy-image",
                "legacy-url",
                "legacy-files",
                "legacy-pdf",
                "legacy-rtf",
                "legacy-string"
            ],
            "untrimmedPrimaryTypes": [
                NSPasteboard.PasteboardType.tiff.rawValue,
                NSPasteboard.PasteboardType.clipMenuURL.rawValue,
                NSPasteboard.PasteboardType.clipMenuFilenames.rawValue,
                NSPasteboard.PasteboardType.pdf.rawValue,
                NSPasteboard.PasteboardType.rtf.rawValue,
                NSPasteboard.PasteboardType.string.rawValue
            ],
            "untrimmedCountsByPrimaryType": [
                NSPasteboard.PasteboardType.string.rawValue: 1,
                NSPasteboard.PasteboardType.rtf.rawValue: 1,
                NSPasteboard.PasteboardType.pdf.rawValue: 1,
                NSPasteboard.PasteboardType.clipMenuFilenames.rawValue: 1,
                NSPasteboard.PasteboardType.clipMenuURL.rawValue: 1,
                NSPasteboard.PasteboardType.tiff.rawValue: 1
            ],
            "trimmedOrderedTexts": ["legacy-image", "legacy-url", "legacy-files"]
        ]
        report["state"] = actualState
        report["expectedState"] = expectedState
        report["matchesExpected"] = NSDictionary(dictionary: actualState).isEqual(to: expectedState)
    }

