    private static func defaultLegacyHotKeys() -> [String: [String: Int]] {
        [
            "ClipMenu": [
                "keyCode": 9,
                "modifiers": cmdKey | shiftKey
            ],
            "SnippetsMenu": [
                "keyCode": 11,
                "modifiers": cmdKey | shiftKey
            ]
        ]
    }

    private static func migrateLegacyHotKeyDefaultsIfNeeded() {
        let defaults = UserDefaults.standard
        guard let bundleIdentifier = Bundle.main.bundleIdentifier,
              let persistentDefaults = defaults.persistentDomain(forName: bundleIdentifier),
              let legacyHotKeys = dictionary(fromLegacyObject: persistentDefaults[CMPrefLegacyHotKeysKey]) else {
            return
        }

        migrateLegacyHotKey(
            identifier: "ClipMenu",
            from: legacyHotKeys,
            persistentDomain: persistentDefaults,
            enabledKey: CMPrefHotKeyEnabledKey,
            keyCodeKey: CMPrefHotKeyKeyCodeKey,
            modifierFlagsKey: CMPrefHotKeyModifierFlagsKey
        )
        migrateLegacyHotKey(
            identifier: "SnippetsMenu",
            from: legacyHotKeys,
            persistentDomain: persistentDefaults,
            enabledKey: CMPrefSnippetsHotKeyEnabledKey,
            keyCodeKey: CMPrefSnippetsHotKeyKeyCodeKey,
            modifierFlagsKey: CMPrefSnippetsHotKeyModifierFlagsKey
        )
    }

    private static func migrateLegacyUpdateDefaultsIfNeeded() {
        let defaults = UserDefaults.standard
        guard let bundleIdentifier = Bundle.main.bundleIdentifier else { return }
        let persistentDefaults = defaults.persistentDomain(forName: bundleIdentifier) ?? [:]
        let migrated = UpdateCoordinator.migratedLegacyPreferences(persistentDefaults)
        if !(migrated as NSDictionary).isEqual(to: persistentDefaults) {
            defaults.setPersistentDomain(migrated, forName: bundleIdentifier)
        }
    }

    private static func migrateLegacyHotKey(
        identifier: String,
        from legacyHotKeys: [String: Any],
        persistentDomain: [String: Any],
        enabledKey: String,
        keyCodeKey: String,
        modifierFlagsKey: String
    ) {
        guard !hasPersistentSplitHotKeyDefaults(
            in: persistentDomain,
            enabledKey: enabledKey,
            keyCodeKey: keyCodeKey,
            modifierFlagsKey: modifierFlagsKey
        ) else {
            return
        }
        guard let combo = dictionary(fromLegacyObject: legacyHotKeys[identifier]) else { return }
        let keyCode = (combo["keyCode"] as? NSNumber)?.intValue ?? combo["keyCode"] as? Int ?? -1
        let carbonModifiers = (combo["modifiers"] as? NSNumber)?.intValue ?? combo["modifiers"] as? Int ?? -1
        let isEnabled = keyCode >= 0 && carbonModifiers > 0

        UserDefaults.standard.set(isEnabled, forKey: enabledKey)
        if isEnabled {
            UserDefaults.standard.set(keyCode, forKey: keyCodeKey)
            UserDefaults.standard.set(Int(modifierFlags(fromCarbonModifiers: carbonModifiers).rawValue), forKey: modifierFlagsKey)
        }
    }

    private static func hasPersistentSplitHotKeyDefaults(
        in domain: [String: Any],
        enabledKey: String,
        keyCodeKey: String,
        modifierFlagsKey: String
    ) -> Bool {
        domain[enabledKey] != nil
            || domain[keyCodeKey] != nil
            || domain[modifierFlagsKey] != nil
    }

    private static func modifierFlags(fromCarbonModifiers carbonModifiers: Int) -> NSEvent.ModifierFlags {
        var flags: NSEvent.ModifierFlags = []
        if carbonModifiers & cmdKey != 0 {
            flags.insert(.command)
        }
        if carbonModifiers & optionKey != 0 {
            flags.insert(.option)
        }
        if carbonModifiers & controlKey != 0 {
            flags.insert(.control)
        }
        if carbonModifiers & shiftKey != 0 {
            flags.insert(.shift)
        }
        return flags
    }

    private static func dictionary(fromLegacyObject object: Any?) -> [String: Any]? {
        if let dictionary = object as? [String: Any] {
            return dictionary
        }
        if let dictionary = object as? NSDictionary {
            var result: [String: Any] = [:]
            dictionary.forEach { key, value in
                if let key = key as? String {
                    result[key] = value
                }
            }
            return result
        }
        return nil
    }

    private func installHotKeyEventHandler() {
        guard hotKeyEventHandler == nil else { return }

        var eventType = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
        let callback: EventHandlerUPP = { _, event, _ in
            guard let event else { return noErr }

            var hotKeyID = EventHotKeyID()
            let status = GetEventParameter(
                event,
                EventParamName(kEventParamDirectObject),
                EventParamType(typeEventHotKeyID),
                nil,
                MemoryLayout<EventHotKeyID>.size,
                nil,
                &hotKeyID
            )

            guard status == noErr,
                  hotKeyID.signature == AppController.hotKeySignature,
                  let kind = HotKeyKind(rawValue: hotKeyID.id) else {
                return status
            }

            DispatchQueue.main.async {
                AppController.shared?.showMenu(for: kind)
            }
            return noErr
        }

        InstallEventHandler(
            GetApplicationEventTarget(),
            callback,
            1,
            &eventType,
            nil,
            &hotKeyEventHandler
        )
    }

    @objc private func userDefaultsDidChange(_ notification: Notification) {
        guard Thread.isMainThread else {
            DispatchQueue.main.async { [weak self] in
                self?.applyUserDefaultsChanges()
            }
            return
        }

        applyUserDefaultsChanges()
    }

    private func applyUserDefaultsChanges() {
        guard !isApplyingUserDefaultsChanges else { return }
        let snapshot = effectiveUserDefaultsSnapshot()
        guard !(snapshot as NSDictionary).isEqual(to: lastAppliedUserDefaultsSnapshot) else { return }
        let traceStarted = ProcessInfo.processInfo.systemUptime
        CMTraceMenuPaste("main.defaults.begin")
        defer { CMTraceMenuPaste(String(format: "main.defaults.end elapsedMs=%.1f", (ProcessInfo.processInfo.systemUptime - traceStarted) * 1000)) }
        isApplyingUserDefaultsChanges = true
        defer {
            // Normalization can publish more defaults notifications during this pass.
            // Remember the final values so those notifications do not repeat the work.
            lastAppliedUserDefaultsSnapshot = effectiveUserDefaultsSnapshot()
            isApplyingUserDefaultsChanges = false
        }
#if DEBUG || TESTING
        userDefaultsApplicationGeneration += 1
#endif
        AppController.migrateLegacyHotKeyDefaultsIfNeeded()
        AppController.migrateLegacyUpdateDefaultsIfNeeded()
        let normalizedObserveInterval = CMNormalizedLegacyObserveInterval(
            UserDefaults.standard.double(forKey: CMPrefTimeIntervalKey)
        )
        if abs(normalizedObserveInterval - UserDefaults.standard.double(forKey: CMPrefTimeIntervalKey)) > 0.0001 {
            UserDefaults.standard.set(normalizedObserveInterval, forKey: CMPrefTimeIntervalKey)
        }
        let normalizedExportSeparator = CMNormalizedLegacyExportSeparatorTag(
            UserDefaults.standard.integer(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        )
        if normalizedExportSeparator != UserDefaults.standard.integer(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey) {
            UserDefaults.standard.set(normalizedExportSeparator, forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        }
        let normalizedExportMode = CMNormalizedLegacyExportHistoryAsSingleFileValue(
            UserDefaults.standard.object(forKey: CMPrefExportHistoryAsSingleFileKey)
        )
        if normalizedExportMode != UserDefaults.standard.bool(forKey: CMPrefExportHistoryAsSingleFileKey)
            || !(UserDefaults.standard.object(forKey: CMPrefExportHistoryAsSingleFileKey) is Bool) {
            UserDefaults.standard.set(normalizedExportMode, forKey: CMPrefExportHistoryAsSingleFileKey)
        }
        let normalizedSortOrder = CMNormalizedLegacyReorderClipsAfterPastingValue(
            UserDefaults.standard.object(forKey: CMPrefReorderClipsAfterPasting)
        )
        if normalizedSortOrder != UserDefaults.standard.bool(forKey: CMPrefReorderClipsAfterPasting)
            || !(UserDefaults.standard.object(forKey: CMPrefReorderClipsAfterPasting) is Bool) {
            UserDefaults.standard.set(normalizedSortOrder, forKey: CMPrefReorderClipsAfterPasting)
        }
        let normalizedSnippetPosition = CMNormalizedLegacySnippetPosition(
            UserDefaults.standard.integer(forKey: CMPrefPositionOfSnippetsKey)
        )
        if normalizedSnippetPosition != UserDefaults.standard.integer(forKey: CMPrefPositionOfSnippetsKey) {
            UserDefaults.standard.set(normalizedSnippetPosition, forKey: CMPrefPositionOfSnippetsKey)
        }
        let normalizedMaxHistorySize = CMNormalizedLegacyMaxHistorySize(
            UserDefaults.standard.integer(forKey: CMPrefMaxHistorySizeKey)
        )
        if normalizedMaxHistorySize != UserDefaults.standard.integer(forKey: CMPrefMaxHistorySizeKey) {
            UserDefaults.standard.set(normalizedMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
        }
        let normalizedAutosaveDelay = CMNormalizedLegacyAutosaveDelay(
            UserDefaults.standard.integer(forKey: CMPrefAutosaveDelayKey)
        )
        if normalizedAutosaveDelay != UserDefaults.standard.integer(forKey: CMPrefAutosaveDelayKey) {
            UserDefaults.standard.set(normalizedAutosaveDelay, forKey: CMPrefAutosaveDelayKey)
        }
        let normalizedThumbnailWidth = CMNormalizedLegacyThumbnailDimension(
            UserDefaults.standard.integer(forKey: CMPrefThumbnailWidthKey)
        )
        if normalizedThumbnailWidth != UserDefaults.standard.integer(forKey: CMPrefThumbnailWidthKey) {
            UserDefaults.standard.set(normalizedThumbnailWidth, forKey: CMPrefThumbnailWidthKey)
        }
        let normalizedThumbnailHeight = CMNormalizedLegacyThumbnailDimension(
            UserDefaults.standard.integer(forKey: CMPrefThumbnailHeightKey)
        )
        if normalizedThumbnailHeight != UserDefaults.standard.integer(forKey: CMPrefThumbnailHeightKey) {
            UserDefaults.standard.set(normalizedThumbnailHeight, forKey: CMPrefThumbnailHeightKey)
        }
        for option in CMLegacyMenuIconTypeDefaults() {
            let storedTag = UserDefaults.standard.object(forKey: option.tagKey) as? Int ?? option.defaultSelectionTag
            let normalizedTag = CMNormalizedTypeFileIconSelectionTag(storedTag)
            if normalizedTag != storedTag {
                UserDefaults.standard.set(normalizedTag, forKey: option.tagKey)
            }
            let storedFileType = UserDefaults.standard.string(forKey: option.fileTypeKey)
            let normalizedFileType = CMNormalizedMenuIconFileTypeValue(
                storedFileType,
                defaultValue: option.defaultFileType,
                selectionTag: normalizedTag
            )
            if normalizedFileType != storedFileType {
                UserDefaults.standard.set(normalizedFileType, forKey: option.fileTypeKey)
            }
        }
        let normalizedMenuFontSizingMode = CMNormalizedMenuLegacyFontSizingMode(
            UserDefaults.standard.integer(forKey: CMPrefHowToChangeFontSizeKey)
        )
        if normalizedMenuFontSizingMode != UserDefaults.standard.integer(forKey: CMPrefHowToChangeFontSizeKey) {
            UserDefaults.standard.set(normalizedMenuFontSizingMode, forKey: CMPrefHowToChangeFontSizeKey)
        }
        let normalizedTooltipLength = CMNormalizedLegacyMenuTooltipLength(
            UserDefaults.standard.integer(forKey: CMPrefMaxLengthOfToolTipKey)
        )
        if normalizedTooltipLength != UserDefaults.standard.integer(forKey: CMPrefMaxLengthOfToolTipKey) {
            UserDefaults.standard.set(normalizedTooltipLength, forKey: CMPrefMaxLengthOfToolTipKey)
        }
        let normalizedTitleLength = CMNormalizedLegacyMenuTitleLength(
            UserDefaults.standard.integer(forKey: CMPrefMaxMenuItemTitleLengthKey)
        )
        if normalizedTitleLength != UserDefaults.standard.integer(forKey: CMPrefMaxMenuItemTitleLengthKey) {
            UserDefaults.standard.set(normalizedTitleLength, forKey: CMPrefMaxMenuItemTitleLengthKey)
        }
        let normalizedFolderItemsCount = CMNormalizedLegacyMenuFolderItemsCount(
            UserDefaults.standard.integer(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        )
        if normalizedFolderItemsCount != UserDefaults.standard.integer(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey) {
            UserDefaults.standard.set(normalizedFolderItemsCount, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        }
        let normalizedInlineItemsCount = CMNormalizedLegacyMenuInlineItemsCount(
            UserDefaults.standard.integer(forKey: CMPrefNumberOfItemsPlaceInlineKey)
        )
        if normalizedInlineItemsCount != UserDefaults.standard.integer(forKey: CMPrefNumberOfItemsPlaceInlineKey) {
            UserDefaults.standard.set(normalizedInlineItemsCount, forKey: CMPrefNumberOfItemsPlaceInlineKey)
        }
        syncLoginItemState()
        UpdateCoordinator.shared.configureFromDefaults()
        configureStatusItem()
        clipsStore.trimToCurrentHistoryLimit()
        syncAutosaveTimer()
        syncClipboardPollingInterval()
        registerHotKey()
        rebuildMenu()
    }

    private func effectiveUserDefaultsSnapshot() -> [String: Any] {
        var snapshot = UserDefaults.standard.dictionaryRepresentation()
        // Switching panes only remembers presentation state. It does not change
        // menus, capture behavior, timers, or registered shortcuts.
        snapshot.removeValue(forKey: CMSelectedPreferencePaneKey)
        return snapshot
    }

