    private func updateImageHoverPreview(for item: NSMenuItem?, in menu: NSMenu) {
        // Parent menus can lose their highlight as a submenu starts tracking.
        // That callback must not dismiss the submenu's own image preview.
        if item == nil, let owner = imageHoverPreviewMenu, owner !== menu { return }
        if imageHoverPreviewMenu === menu, imageHoverPreviewItem === item { return }
        dismissImageHoverPreview()

        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: CMPrefShowImageInTheMenuKey),
              let item, item.isEnabled,
              let id = item.representedObject as? String,
              let clip = clipsStore.clip(with: id),
              clip.imageData?.isEmpty == false else { return }

        imageHoverPreviewMenu = menu
        imageHoverPreviewItem = item
        let timer = Timer(timeInterval: 0.25, repeats: false) { [weak self, weak menu, weak item] timer in
            guard let self, let menu, let item,
                  self.imageHoverPreviewTimer === timer,
                  self.imageHoverPreviewMenu === menu,
                  self.imageHoverPreviewItem === item else { return }
            self.imageHoverPreviewTimer = nil
            guard let clip = self.clipsStore.clip(with: id), let image = clip.image else {
                self.dismissImageHoverPreview()
                return
            }

            let pointer = NSEvent.mouseLocation
            guard let screen = NSScreen.screens.first(where: { $0.frame.contains(pointer) }) ?? NSScreen.screens.first else { return }
            self.imageHoverPreviewController.show(
                image: image,
                clipID: clip.id,
                menuFrame: self.imageHoverMenuFrame(menu, near: pointer),
                pointer: pointer,
                visibleFrame: screen.visibleFrame
            )
        }
        imageHoverPreviewTimer = timer
        // Native menus run their own tracking mode; default-only timers wait
        // until the menu closes and cannot display a hover preview in time.
        RunLoop.main.add(timer, forMode: .eventTracking)
        RunLoop.main.add(timer, forMode: .default)
    }

    private func imageHoverMenuFrame(_ menu: NSMenu, near pointer: NSPoint) -> NSRect {
        if let primaryScreen = NSScreen.screens.first,
           let windows = CGWindowListCopyWindowInfo([.optionOnScreenOnly, .excludeDesktopElements], kCGNullWindowID) as? [[String: Any]] {
            for window in windows {
                guard window[kCGWindowOwnerPID as String] as? Int == Int(getpid()),
                      window[kCGWindowLayer as String] as? Int == NSWindow.Level.popUpMenu.rawValue,
                      let bounds = window[kCGWindowBounds as String] as? [String: Any],
                      let quartzFrame = CGRect(dictionaryRepresentation: bounds as CFDictionary) else { continue }
                let frame = NSRect(
                    x: quartzFrame.minX,
                    y: primaryScreen.frame.maxY - quartzFrame.maxY,
                    width: quartzFrame.width,
                    height: quartzFrame.height
                )
                if frame.contains(pointer) { return frame }
            }
        }
        // The pointer may be anywhere within the menu. Conservatively reserve
        // its full width on both sides when exact window metadata is unavailable.
        return NSRect(
            x: pointer.x - menu.size.width,
            y: pointer.y,
            width: menu.size.width * 2,
            height: menu.size.height
        )
    }

    private func dismissImageHoverPreview() {
        imageHoverPreviewTimer?.invalidate()
        imageHoverPreviewTimer = nil
        imageHoverPreviewMenu = nil
        imageHoverPreviewItem = nil
        imageHoverPreviewController.hide()
    }

    func validateMenuItem(_ menuItem: NSMenuItem) -> Bool {
        if menuItem.action == #selector(checkForUpdates(_:)) {
            return UpdateCoordinator.shared.canCheckForUpdates
        }
        if menuItem.action == #selector(clearHistory(_:)) {
            // Objective-C disabled AppController-owned clear-history items when history
            // was empty, but the visible status-menu item remained enabled because it was
            // owned by MenuController and only forwarded to AppController on selection.
            if menuItem.menu?.title == "ClipMenu" {
                return true
            }
            return !clipsStore.clips.isEmpty
        }
        if menuItem.action == #selector(performClose(_:)) {
            return closableWindow() != nil
        }
        if menuItem.action == #selector(`print`(_:)) {
            return printableWindow() != nil
        }
        if menuItem.action == #selector(saveDocument(_:)) {
            return snippetEditorController?.window?.isVisible == true && SnippetFileStore.shared.hasUnsavedChanges
        }
        if menuItem.action == #selector(saveDocumentAs(_:)) {
            return snippetEditorController?.window?.isVisible == true
        }
        if menuItem.action == #selector(revertDocumentToSaved(_:)) {
            return snippetEditorController?.window?.isVisible == true && SnippetFileStore.shared.hasUnsavedChanges
        }
        return true
    }

    private func unhighlightFolderMenuItem() {
        highlightedFolderMenuItem?.image = menuFolderIcon()
        highlightedFolderMenuItem = nil
    }

    private func syncLoginItemState(force: Bool = false) {
        let requested = UserDefaults.standard.bool(forKey: CMPrefLoginItemKey)
        guard requested != lastRequestedLoginItemState else { return }
        if !force, SwiftUIPreferencesWindowController.shared.window?.isVisible == true {
            deferredLoginItemSyncRequired = true
            return
        }

        if LoginItemManager.setEnabled(requested) {
            lastRequestedLoginItemState = requested
            deferredLoginItemSyncRequired = false
        } else {
            lastRequestedLoginItemState = false
            deferredLoginItemSyncRequired = false
            if requested {
                UserDefaults.standard.set(false, forKey: CMPrefLoginItemKey)
            }
        }
    }

    private func shouldPromptToAddLoginItem(defaults: UserDefaults = .standard) -> Bool {
        guard !defaults.bool(forKey: CMPrefLoginItemKey),
              !defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey),
              LoginItemManager.supportsMainAppLoginItem else {
            return false
        }
        return true
    }

    private func applyLoginItemPromptDecision(
        launchOnStartup: Bool,
        suppressPrompt: Bool,
        defaults: UserDefaults = .standard
    ) {
        if launchOnStartup {
            defaults.set(true, forKey: CMPrefLoginItemKey)
            syncLoginItemState()
        }

        if suppressPrompt {
            defaults.set(true, forKey: CMPrefSuppressAlertForLoginItemKey)
        }
    }

    private func localizedLoginItemPromptAccessoryDetail() -> String {
        CMLocalizedModernString(
            "Keep ClipMenu ready in the menu bar as soon as you sign in.",
            japanese: "サインイン後すぐに、ClipMenu をメニューバーで使えるようにします。"
        )
    }

    private func makeLoginItemPromptAccessory() -> NSView {
        let width: CGFloat = 420
        let container = NSVisualEffectView(frame: NSRect(x: 0, y: 0, width: width, height: 72))
        container.material = .menu
        container.state = .active
        container.wantsLayer = true
        container.layer?.cornerRadius = 12
        container.layer?.masksToBounds = true

        let iconBackground = NSVisualEffectView(frame: NSRect(x: 16, y: 16, width: 40, height: 40))
        iconBackground.material = .sidebar
        iconBackground.state = .active
        iconBackground.wantsLayer = true
        iconBackground.layer?.cornerRadius = 10
        iconBackground.layer?.masksToBounds = true
        container.addSubview(iconBackground)

        let iconView = NSImageView(frame: NSRect(x: 6, y: 6, width: 28, height: 28))
        iconView.image = NSApp.applicationIconImage
        iconView.imageScaling = .scaleProportionallyUpOrDown
        iconBackground.addSubview(iconView)

        let textWidth = width - 90

        let titleLabel = NSTextField(
            labelWithString: NSLocalizedString("768.title", tableName: "Preferences", bundle: .main, value: "Launch on Login", comment: "")
        )
        titleLabel.font = .systemFont(ofSize: 13, weight: .semibold)
        titleLabel.frame = NSRect(x: 70, y: 38, width: textWidth, height: 18)
        container.addSubview(titleLabel)

        let detailLabel = NSTextField(labelWithString: localizedLoginItemPromptAccessoryDetail())
        detailLabel.font = .systemFont(ofSize: 12)
        detailLabel.textColor = .secondaryLabelColor
        detailLabel.lineBreakMode = .byTruncatingTail
        detailLabel.frame = NSRect(x: 70, y: 18, width: textWidth, height: 17)
        container.addSubview(detailLabel)

        return container
    }

    private func makeLoginItemPrompt() -> NSAlert {
        let alert = NSAlert()
        alert.messageText = NSLocalizedString("Launch ClipMenu on system startup?", comment: "")
        alert.informativeText = NSLocalizedString("You can change this setting in the Preferences if you want.", comment: "")
        alert.accessoryView = makeLoginItemPromptAccessory()
        alert.addButton(withTitle: NSLocalizedString("Launch on system startup", comment: ""))
        alert.addButton(withTitle: NSLocalizedString("Don't Launch", comment: ""))
        alert.showsSuppressionButton = true
        return alert
    }

