    @discardableResult
    private func promptToAddLoginItemIfNeeded() -> Bool {
        let defaults = UserDefaults.standard
        guard shouldPromptToAddLoginItem(defaults: defaults) else {
            return false
        }

#if DEBUG
        if debugBypassLoginItemPromptUI() {
            return false
        }
#endif

        DispatchQueue.main.async {
            let alert = self.makeLoginItemPrompt()
            NSApp.activate(ignoringOtherApps: true)

            let shouldLaunchOnStartup = alert.runModal() == .alertFirstButtonReturn
            let shouldSuppressPrompt = alert.suppressionButton?.state == .on
            self.applyLoginItemPromptDecision(
                launchOnStartup: shouldLaunchOnStartup,
                suppressPrompt: shouldSuppressPrompt,
                defaults: defaults
            )
            UpdateCoordinator.shared.configureFromDefaults()
        }
        return true
    }

    private func registerHotKey() {
        unregisterHotKey()

        for kind in HotKeyKind.allCases {
            registerHotKey(kind)
        }
        hotKeyRegistrationGeneration += 1
    }

    private func registerHotKey(_ kind: HotKeyKind) {
        guard UserDefaults.standard.bool(forKey: kind.enabledKey) else { return }

        let savedKeyCode = UserDefaults.standard.integer(forKey: kind.keyCodeKey)
        guard savedKeyCode >= 0 else { return }
        let keyCode = UInt32(savedKeyCode)
        let modifierFlags = NSEvent.ModifierFlags(rawValue: UInt(UserDefaults.standard.integer(forKey: kind.modifierFlagsKey)))
        let carbonModifiers = UInt32(modifierFlags.carbonHotKeyModifiers)
        guard carbonModifiers != 0 else { return }

        let hotKeyID = EventHotKeyID(signature: Self.hotKeySignature, id: kind.rawValue)
        var hotKeyRef: EventHotKeyRef?
        let status = RegisterEventHotKey(
            keyCode,
            carbonModifiers,
            hotKeyID,
            GetApplicationEventTarget(),
            0,
            &hotKeyRef
        )

        if status != noErr {
            NSLog("ClipMenu failed to register hot key \(kind.rawValue): \(status)")
        } else if let hotKeyRef {
            hotKeyRefs[kind.rawValue] = hotKeyRef
        }
    }

    private func unregisterHotKey() {
        for (_, hotKeyRef) in hotKeyRefs {
            UnregisterEventHotKey(hotKeyRef)
        }
        hotKeyRefs.removeAll()
    }

    private func showMenu(for kind: HotKeyKind) {
        let menu: NSMenu
        switch kind {
        case .mainMenu:
            menu = makeMainMenu()
            if CMNormalizedStatusItemSelectionTag(
                UserDefaults.standard.integer(forKey: CMPrefShowStatusItemKey)
            ) != 0 {
                if statusItem == nil {
                    configureStatusItem()
                }
                statusItem?.menu = menu
            }
        case .snippetsMenu:
            menu = makeSnippetsMenu()
        }
        rememberPasteTargetApplication()
        popUpMenuAtMouseLocation(menu)
    }

    private func configureStatusItem() {
        let defaults = UserDefaults.standard
        let storedTag = defaults.integer(forKey: CMPrefShowStatusItemKey)
        let iconTag = CMNormalizedStatusItemSelectionTag(storedTag)
        if iconTag != storedTag {
            defaults.set(iconTag, forKey: CMPrefShowStatusItemKey)
        }
        guard iconTag != 0 else {
            if let statusItem {
                statusItem.menu = nil
                NSStatusBar.system.removeStatusItem(statusItem)
                self.statusItem = nil
            }
            statusItemIconTag = nil
            return
        }

        if let statusItem, statusItemIconTag != iconTag {
            statusItem.menu = nil
            NSStatusBar.system.removeStatusItem(statusItem)
            self.statusItem = nil
        }

        let statusItem: NSStatusItem
        if let existingStatusItem = self.statusItem {
            statusItem = existingStatusItem
        } else {
            statusItem = NSStatusBar.system.statusItem(withLength: 24.0)
            self.statusItem = statusItem
        }
        statusItemIconTag = iconTag
        statusItem.length = 24.0
        let statusImage = statusItemImage(forTag: iconTag, pressed: false)
        let pressedStatusImage = statusItemImage(forTag: iconTag, pressed: true) ?? statusImage
        statusItem.button?.image = statusImage
        statusItem.button?.alternateImage = pressedStatusImage
        statusItem.button?.imagePosition = .imageOnly
        statusItem.button?.imageScaling = .scaleProportionallyDown
        statusItem.button?.toolTip = statusItemToolTip()
    }

    private func statusItemImage(forTag tag: Int, pressed: Bool) -> NSImage? {
        let imageName = statusItemImageName(forTag: tag)
        let resolvedName = pressed ? imageName + "_pressed" : imageName
        let fallbackName = pressed ? "StatusMenuIcon_pressed" : "StatusMenuIcon"

        let sourceImage = NSImage(named: resolvedName)
            ?? NSImage(named: fallbackName)
            ?? (pressed ? statusItemImage(forTag: tag, pressed: false) : legacyStatusTemplateImage())

        guard let sourceImage, let copiedImage = sourceImage.copy() as? NSImage else {
            return nil
        }

        copiedImage.isTemplate = statusItemUsesTemplateRendering(forTag: tag)
        return copiedImage
    }

    private func statusItemImageName(forTag tag: Int) -> String {
        switch tag {
        case 2:
            return "StatusMenuIconFirst"
        case 3:
            return "StatusMenuIconByDaveUlrich-scissors1-bw-left"
        case 4:
            return "StatusMenuIconByDaveUlrich-scissors1-bw-right"
        case 5:
            return "StatusMenuIconByDaveUlrich-scissors1-color-left"
        case 6:
            return "StatusMenuIconByDaveUlrich-scissors1-color-right"
        case 7:
            return "StatusMenuIconByDaveUlrich-diagonal-bw"
        case 8:
            return "StatusMenuIconByDaveUlrich-diagonal-color"
        case 9:
            return "StatusMenuIconByDaveUlrich-scissors2-bw-left"
        case 10:
            return "StatusMenuIconByDaveUlrich-scissors2-bw-right"
        case 11:
            return "StatusMenuIconByDaveUlrich-scissors2-color-left"
        case 12:
            return "StatusMenuIconByDaveUlrich-scissors2-color-right"
        default:
            return "StatusMenuIcon"
        }
    }

    private func statusItemUsesTemplateRendering(forTag tag: Int) -> Bool {
        switch tag {
        case 5, 6, 8, 11, 12:
            return false
        default:
            return true
        }
    }

    private func legacyStatusTemplateImage() -> NSImage {
        let image = NSImage(size: NSSize(width: 18, height: 18))
        image.lockFocus()
        NSColor.black.setStroke()
        NSColor.black.setFill()

        let board = NSBezierPath(
            roundedRect: NSRect(x: 4, y: 3, width: 10, height: 12),
            xRadius: 1.5,
            yRadius: 1.5
        )
        board.lineWidth = 1.8
        board.stroke()

        let clip = NSBezierPath(
            roundedRect: NSRect(x: 6, y: 13, width: 6, height: 3),
            xRadius: 1.4,
            yRadius: 1.4
        )
        clip.fill()

        let line = NSBezierPath()
        line.lineWidth = 1.4
        line.move(to: NSPoint(x: 6.5, y: 9.5))
        line.line(to: NSPoint(x: 11.5, y: 9.5))
        line.move(to: NSPoint(x: 6.5, y: 6.5))
        line.line(to: NSPoint(x: 10.5, y: 6.5))
        line.stroke()
        image.unlockFocus()
        image.isTemplate = true
        return image
    }

    private func statusItemToolTip() -> String {
        let appName = legacyApplicationName()
        let shortVersion = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? ""
        return shortVersion.isEmpty ? appName : "\(appName) \(shortVersion)"
    }

    private func startClipboardPolling() {
        pollingTimer?.invalidate()
        let defaults = UserDefaults.standard
        var interval = defaults.double(forKey: CMPrefTimeIntervalKey)
        let normalizedInterval = CMNormalizedLegacyObserveInterval(interval)
        if abs(normalizedInterval - interval) > 0.0001 {
            interval = normalizedInterval
            defaults.set(interval, forKey: CMPrefTimeIntervalKey)
        }
        lastAppliedClipboardPollingInterval = interval
        pollingTimer = Timer.scheduledTimer(withTimeInterval: interval, repeats: true) { [weak self] _ in
            self?.pollClipboard()
        }
    }

    private func startAutosaveTimer() {
        autosaveTimer?.invalidate()

        let defaults = UserDefaults.standard
        let storedInterval = defaults.integer(forKey: CMPrefAutosaveDelayKey)
        let normalizedInterval = CMNormalizedLegacyAutosaveDelay(storedInterval)
        if normalizedInterval != storedInterval {
            defaults.set(normalizedInterval, forKey: CMPrefAutosaveDelayKey)
        }

        var interval = Double(normalizedInterval)
        guard interval > 0 else {
            lastAppliedAutosaveInterval = nil
            autosaveTimer = nil
            return
        }
        interval = max(interval, CMMinimumAutosaveInterval)
        lastAppliedAutosaveInterval = interval

        autosaveTimer = Timer.scheduledTimer(withTimeInterval: interval, repeats: true) { [weak self] _ in
            self?.autosaveHistory()
        }
    }

    private func tracePendingPasteOperation<T>(_ stage: String, _ work: () -> T) -> T {
        guard pasteIsPending else { return work() }
        let started = ProcessInfo.processInfo.systemUptime
        CMTraceMenuPaste("\(stage).begin")
        defer { CMTraceMenuPaste(String(format: "%@.end elapsedMs=%.1f", stage, (ProcessInfo.processInfo.systemUptime - started) * 1000)) }
        return work()
    }

    private var pasteIsPending: Bool {
        pasteRequestLock.lock()
        let pending = pasteActivity != nil
        pasteRequestLock.unlock()
        return pending
    }

    private func autosaveHistory() {
        guard !pasteIsPending, !historyAutosaveIsPending else { return }
        historyAutosaveIsPending = true
        clipsStore.saveIfNeededAsync { [weak self] saved in
            guard let self else { return }
            self.historyAutosaveIsPending = false
            guard !saved else { return }
            // A failed background save must not steal focus from a newer paste.
            guard !self.pasteIsPending else {
                NSLog("Could not autosave clipboard history; will retry after the pending paste.")
                return
            }
            self.autosaveTimer?.invalidate()
            self.autosaveTimer = nil
            NSApp.activate(ignoringOtherApps: true)
            let alert = self.makeHistoryPersistenceFailureAlert()
            alert.runModal()
            self.startAutosaveTimer()
        }
    }

    private func pollClipboard(frontmostBundleIdentifier: String? = NSWorkspace.shared.frontmostApplication?.bundleIdentifier) {
        // Capturing snippet/action output and rebuilding menus can be expensive.
        // Leave its generation unacknowledged until the requested paste finishes.
        guard !pasteIsPending else {
            CMTraceMenuPaste("main.poll.deferred-paste")
            return
        }
        tracePendingPasteOperation("main.poll") {
            let changeCount = pasteboard.changeCount
            guard changeCount != lastChangeCount else { return }
            lastChangeCount = changeCount
            guard let clip = capturedClip(from: pasteboard, frontmostBundleIdentifier: frontmostBundleIdentifier) else { return }
#if DEBUG
            debugClipboardCaptureGeneration += 1
#endif
            clipsStore.add(clip)
            persistCapturedHistoryAsynchronouslyIfPreferred()
            rebuildMenu()
        }
    }

    private func frontmostAppIsExcluded() -> Bool {
        isExcludedApp(bundleIdentifier: NSWorkspace.shared.frontmostApplication?.bundleIdentifier)
    }

    private func isExcludedApp(bundleIdentifier: String?) -> Bool {
        guard let bundleIdentifier else { return false }
        let excludeList = excludedAppDictionaries(from: UserDefaults.standard.object(forKey: CMPrefExcludeAppsKey))
        return excludeList.contains { $0[kCMBundleIdentifierKey] == bundleIdentifier }
    }

    private func capturedClip(from pasteboard: NSPasteboard, frontmostBundleIdentifier: String? = NSWorkspace.shared.frontmostApplication?.bundleIdentifier) -> ClipItem? {
        guard !isExcludedApp(bundleIdentifier: frontmostBundleIdentifier) else { return nil }
        return ClipItem.fromPasteboard(pasteboard)
    }

    @objc private func rebuildMenu() {
        guard !pasteIsPending else {
            deferredMenuRebuildRequired = true
            CMTraceMenuPaste("main.rebuild.deferred-paste")
            return
        }
        deferredMenuRebuildRequired = false
#if DEBUG
        debugMenuRebuildGeneration += 1
#endif
        tracePendingPasteOperation("main.rebuild") { rebuildMenuContents() }
    }

    private func rebuildMenuContents() {
        dismissImageHoverPreview()
        guard UserDefaults.standard.integer(forKey: CMPrefShowStatusItemKey) != 0 else {
            statusItem?.menu = nil
            return
        }
        if statusItem == nil {
            configureStatusItem()
        }
        let menu = makeMainMenu()
        statusItem?.menu = menu
    }

    private func makeMainMenu() -> NSMenu {
        let menu = NSMenu(title: "ClipMenu")
        menu.delegate = self

        let defaults = UserDefaults.standard
        let storedSnippetsPosition = defaults.integer(forKey: CMPrefPositionOfSnippetsKey)
        let normalizedSnippetsPositionRawValue = CMNormalizedLegacySnippetPosition(storedSnippetsPosition)
        if normalizedSnippetsPositionRawValue != storedSnippetsPosition {
            defaults.set(normalizedSnippetsPositionRawValue, forKey: CMPrefPositionOfSnippetsKey)
        }
        let snippetsPosition = CMPositionOfSnippets(rawValue: normalizedSnippetsPositionRawValue) ?? .belowClips
        let addedSnippetsAboveClips = snippetsPosition == .aboveClips
            ? addSnippets(to: menu, position: snippetsPosition)
            : false
        let hasVisibleClips = clipsStoreHasVisibleClips()
        if snippetsPosition == .aboveClips, addedSnippetsAboveClips, hasVisibleClips {
            appendSeparatorIfNeeded(to: menu)
        }
        _ = addClips(to: menu)

        if snippetsPosition == .belowClips {
            _ = addSnippets(to: menu, position: snippetsPosition)
        }

        appendSeparatorIfNeeded(to: menu)
        if defaults.bool(forKey: CMPrefAddClearHistoryMenuItemKey) {
            let item = makeCommandMenuItem(title: NSLocalizedString("Clear History", comment: ""), action: #selector(clearHistory(_:)))
            item.target = statusMenuCommandRouter
            menu.addItem(item)
        }

        let snippetsItem = makeCommandMenuItem(title: NSLocalizedString("Edit Snippets...", comment: ""), action: #selector(showSnippetEditor(_:)))
        snippetsItem.target = statusMenuCommandRouter
        menu.addItem(snippetsItem)

        let preferencesItem = makeCommandMenuItem(title: NSLocalizedString("Preferences...", comment: ""), action: #selector(showPreferencePanel(_:)))
        preferencesItem.target = statusMenuCommandRouter
        menu.addItem(preferencesItem)

        appendSeparatorIfNeeded(to: menu)
        let quitItem = makeCommandMenuItem(title: NSLocalizedString("Quit ClipMenu", comment: ""), action: #selector(NSApplication.terminate(_:)))
        quitItem.target = NSApp
        menu.addItem(quitItem)

        return menu
    }

    private func makeHistoryMenu() -> NSMenu {
        let menu = NSMenu(title: "HistoryMenu")
        menu.delegate = self
        addClips(to: menu)
        return menu
    }

    private func makeSnippetsMenu() -> NSMenu {
        let menu = NSMenu(title: "SnippetsMenu")
        menu.delegate = self
        addSnippets(to: menu)
        return menu
    }

    @discardableResult
    private func addClips(to menu: NSMenu) -> Bool {
        let defaults = UserDefaults.standard
        if defaults.bool(forKey: CMPrefShowLabelsInMenuKey) {
            menu.addItem(disabledHeader(NSLocalizedString("History", comment: "")))
        }

        let maxHistory = max(0, defaults.integer(forKey: CMPrefMaxHistorySizeKey))
        let allClips = clipsStore.orderedClips
        let clips = Array(allClips.prefix(maxHistory))
        guard !clips.isEmpty else { return false }

        let storedInlineCount = defaults.integer(forKey: CMPrefNumberOfItemsPlaceInlineKey)
        let inlineCount = CMNormalizedLegacyMenuInlineItemsCount(storedInlineCount)
        if inlineCount != storedInlineCount {
            defaults.set(inlineCount, forKey: CMPrefNumberOfItemsPlaceInlineKey)
        }
        let storedFolderCount = defaults.integer(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        let folderCount = CMNormalizedLegacyMenuFolderItemsCount(storedFolderCount)
        if folderCount != storedFolderCount {
            defaults.set(folderCount, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        }
        let firstIndex = defaults.bool(forKey: CMPrefMenuItemsTitleStartWithZeroKey) ? 0 : 1

        for group in CMHistoryMenuGroups(
            clipCount: clips.count,
            inlineCount: inlineCount,
            folderCount: folderCount
        ) {
            switch group {
            case let .direct(offset):
                let numberLimit = offset < inlineCount ? inlineCount : clips.count
                let listNumber = menuListNumber(
                    forOffset: offset,
                    firstIndex: firstIndex,
                    maxCount: numberLimit
                )
                menu.addItem(makeClipMenuItem(clip: clips[offset], globalIndex: offset, listNumber: listNumber))

            case let .folder(range):
                let folderStart = range.lowerBound
                let submenuItem = NSMenuItem(
                    title: folderRangeTitle(
                        startOffset: folderStart,
                        folderCount: folderCount,
                        fullHistoryCount: allClips.count,
                        firstIndex: firstIndex
                    ),
                    action: nil,
                    keyEquivalent: ""
                )
                applyPreferredFont(to: submenuItem)

                let submenu = NSMenu(title: submenuItem.title)
                submenu.delegate = self
                for offset in range {
                    let listNumber = menuListNumber(
                        forOffset: offset - folderStart,
                        firstIndex: firstIndex,
                        maxCount: folderCount
                    )
                    submenu.addItem(
                        makeClipMenuItem(clip: clips[offset], globalIndex: offset, listNumber: listNumber)
                    )
                }
                submenuItem.submenu = submenu
                menu.addItem(submenuItem)
            }
        }
        return true
    }

    @discardableResult
    private func addSnippets(to menu: NSMenu, position: CMPositionOfSnippets? = nil) -> Bool {
        let folders = SnippetFileStore.shared.menuFolders.filter {
            $0.isEnabled && !$0.snippets.isEmpty
        }
        guard !folders.isEmpty else { return false }

        if position == .belowClips, !menu.items.isEmpty {
            appendSeparatorIfNeeded(to: menu)
        }

        if UserDefaults.standard.bool(forKey: CMPrefShowLabelsInMenuKey) {
            menu.addItem(disabledHeader(NSLocalizedString("Snippets", comment: "")))
        }

        let firstIndex = UserDefaults.standard.bool(forKey: CMPrefMenuItemsTitleStartWithZeroKey) ? 0 : 1
        for folder in folders {
            let item = NSMenuItem(title: folder.title, action: nil, keyEquivalent: "")
            if UserDefaults.standard.bool(forKey: CMPrefShowIconInTheMenuKey) {
                item.image = menuFolderIcon()
            }
            applyPreferredFont(to: item)
            let submenu = NSMenu(title: folder.title)
            submenu.delegate = self
            for (offset, snippet) in folder.snippets.filter(\.isEnabled).enumerated() {
                let listNumber = firstIndex + offset
                let snippetTitle = snippetMenuTitle(for: snippet.title, listNumber: listNumber)
                let snippetItem = NSMenuItem(
                    title: snippetTitle,
                    action: #selector(selectSnippet(_:)),
                    keyEquivalent: ""
                )
                snippetItem.target = statusMenuCommandRouter
                snippetItem.representedObject = SnippetActionReference(
                    folderID: folder.id,
                    snippetID: snippet.id,
                    content: snippet.content
                )
                snippetItem.toolTip = snippet.content
                if UserDefaults.standard.bool(forKey: CMPrefShowIconInTheMenuKey) {
                    snippetItem.image = menuSnippetIcon()
                }
                applyPreferredFont(to: snippetItem)
                submenu.addItem(snippetItem)
            }
            item.submenu = submenu
            menu.addItem(item)
        }
        return true
    }

    private func appendSeparatorIfNeeded(to menu: NSMenu) {
        guard !menu.items.isEmpty, menu.items.last?.isSeparatorItem == false else { return }
        menu.addItem(.separator())
    }

    private func clipsStoreHasVisibleClips() -> Bool {
        let maxHistory = max(0, UserDefaults.standard.integer(forKey: CMPrefMaxHistorySizeKey))
        return !clipsStore.orderedClips.prefix(maxHistory).isEmpty
    }

    private func disabledHeader(_ title: String) -> NSMenuItem {
        let item = NSMenuItem(title: title, action: nil, keyEquivalent: "")
        item.isEnabled = false
        return item
    }

    private func makeClipMenuItem(clip: ClipItem, globalIndex: Int, listNumber: Int) -> NSMenuItem {
        let item = NSMenuItem(
            title: clipMenuTitle(for: clip, listNumber: listNumber),
            action: #selector(selectClip(_:)),
            keyEquivalent: keyEquivalent(for: globalIndex)
        )
        item.keyEquivalentModifierMask = keyEquivalentModifierMask(for: globalIndex)
        item.target = statusMenuCommandRouter
        item.tag = globalIndex
        item.representedObject = clip.id.uuidString
        if UserDefaults.standard.bool(forKey: CMPrefShowToolTipOnMenuItemKey) {
            item.toolTip = tooltip(for: clip.tooltipSource)
        }
        applyImageOrIcon(to: item, for: clip)
        applyPreferredFont(to: item)
        return item
    }

    private func makeCommandMenuItem(title: String, action: Selector) -> NSMenuItem {
        let item = NSMenuItem(title: title, action: action, keyEquivalent: "")
        applyPreferredFont(to: item)
        return item
    }

    private func installMainMenu() {
        let mainMenu = NSMenu(title: "MainMenu")
        for item in [appMenuItem(), fileMenuItem(), editMenuItem(), helpMenuItem()] {
            mainMenu.addItem(item)
            if let submenu = item.submenu {
                mainMenu.setSubmenu(submenu, for: item)
            }
        }
        NSApp.mainMenu = mainMenu
        enforceLegacyMainMenuTitles()
    }

