    private func clipMenuTitle(for clip: ClipItem, listNumber: Int) -> String {
        let textTitle = trimmedMenuTitle(for: clip.text)
        let titleText: String
        switch clip.primaryPasteboardType {
        case .tiff, .clipMenuPICT:
            titleText = "(Image)"
        case .pdf:
            titleText = "(PDF)"
        case .clipMenuFilenames where textTitle.isEmpty:
            titleText = "(Filenames)"
        default:
            titleText = textTitle
        }

        return numberedMenuTitle(titleText, listNumber: listNumber)
    }

    private func snippetMenuTitle(for text: String, listNumber: Int) -> String {
        numberedMenuTitle(trimmedSnippetMenuTitle(for: text), listNumber: listNumber)
    }

    private func trimmedSnippetMenuTitle(for text: String) -> String {
        let stripped = text.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmedMenuTitle(for: stripped)
    }

    private func trimmedMenuTitle(for text: String) -> String {
        let stripped = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let nsString = stripped as NSString
        let firstLine: NSString
        if nsString.length > 0 {
            var lineStart = 0
            var lineEnd = 0
            var contentsEnd = 0
            nsString.getLineStart(&lineStart, end: &lineEnd, contentsEnd: &contentsEnd, for: NSRange(location: 0, length: 0))
            firstLine = nsString.substring(to: lineEnd == nsString.length ? nsString.length : contentsEnd) as NSString
        } else {
            firstLine = ""
        }
        let defaults = UserDefaults.standard
        let storedLimit = defaults.integer(forKey: CMPrefMaxMenuItemTitleLengthKey)
        let normalizedStoredLimit = CMNormalizedLegacyMenuTitleLength(storedLimit)
        if normalizedStoredLimit != storedLimit {
            defaults.set(normalizedStoredLimit, forKey: CMPrefMaxMenuItemTitleLengthKey)
        }
        let limit = max(3, normalizedStoredLimit)
        if firstLine.length > limit {
            let end = max(0, limit - 3)
            return firstLine.substring(to: end) + "..."
        }
        return firstLine as String
    }

    private func numberedMenuTitle(_ title: String, listNumber: Int) -> String {
        guard UserDefaults.standard.bool(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey) else {
            return title
        }
        return "\(listNumber). \(title)"
    }

    private func folderRangeTitle(startOffset: Int, folderCount: Int, fullHistoryCount: Int, firstIndex: Int) -> String {
        let firstNumber = startOffset + firstIndex
        let legacyCount = firstIndex == 0 ? startOffset - 1 : startOffset
        let legacyLastNumber = min(fullHistoryCount, legacyCount + folderCount)
        let lastNumber = max(firstNumber, legacyLastNumber)
        return "\(firstNumber) - \(lastNumber)"
    }

    private func keyEquivalent(for index: Int) -> String {
        guard index >= 0 else { return "" }
        guard UserDefaults.standard.bool(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey),
              index < 10 else {
            return ""
        }
        let startsFromZero = UserDefaults.standard.bool(forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        let shortcut = startsFromZero ? index : index + 1
        return shortcut == 10 ? "0" : "\(shortcut)"
    }

    private func keyEquivalentModifierMask(for index: Int) -> NSEvent.ModifierFlags {
        keyEquivalent(for: index).isEmpty ? [] : [.command]
    }

    private func tooltip(for text: String) -> String {
        let defaults = UserDefaults.standard
        let storedMaxLength = defaults.integer(forKey: CMPrefMaxLengthOfToolTipKey)
        let maxLength = CMNormalizedLegacyMenuTooltipLength(storedMaxLength)
        if maxLength != storedMaxLength {
            defaults.set(maxLength, forKey: CMPrefMaxLengthOfToolTipKey)
        }
        let nsString = text as NSString
        return nsString.length > maxLength ? nsString.substring(to: maxLength) : text
    }

    private func menuListNumber(forOffset offset: Int, firstIndex: Int, maxCount: Int) -> Int {
        let value = firstIndex + offset
        if firstIndex == 1, maxCount == 10, value == 10 {
            return 0
        }
        return value
    }

    private func applyPreferredFont(to item: NSMenuItem) {
        guard UserDefaults.standard.bool(forKey: CMPrefChangeFontSizeKey) else { return }
        let defaults = UserDefaults.standard
        let size: CGFloat
        let storedFontSizingMode = defaults.integer(forKey: CMPrefHowToChangeFontSizeKey)
        let normalizedFontSizingMode = CMNormalizedMenuLegacyFontSizingMode(storedFontSizingMode)
        if normalizedFontSizingMode != storedFontSizingMode {
            defaults.set(normalizedFontSizingMode, forKey: CMPrefHowToChangeFontSizeKey)
        }
        switch normalizedFontSizingMode {
        case 0:
            if defaults.bool(forKey: CMPrefShowIconInTheMenuKey) {
                switch defaults.integer(forKey: CMPrefMenuIconSizeKey) {
                case 32:
                    size = 28
                case 48:
                    size = 42
                default:
                    size = 14
                }
            } else {
                size = 14
            }
        case 1:
            size = CGFloat(CMNormalizedMenuLegacyFontSize(defaults.integer(forKey: CMPrefSelectedFontSizeKey)))
        default:
            size = 14
        }
        item.attributedTitle = NSAttributedString(
            string: item.title,
            attributes: [.font: NSFont.systemFont(ofSize: size)]
        )
    }

    private func applyImageOrIcon(to item: NSMenuItem, for clip: ClipItem) {
        let defaults = UserDefaults.standard
        let image = clip.image
        let isImageClip = isImagePasteboardType(clip.primaryPasteboardType)
        if let image, isImageClip {
            if defaults.bool(forKey: CMPrefShowImageInTheMenuKey) {
                let storedThumbnailWidth = defaults.integer(forKey: CMPrefThumbnailWidthKey)
                let thumbnailWidth = CMNormalizedLegacyThumbnailDimension(storedThumbnailWidth)
                if thumbnailWidth != storedThumbnailWidth {
                    defaults.set(thumbnailWidth, forKey: CMPrefThumbnailWidthKey)
                }
                let storedThumbnailHeight = defaults.integer(forKey: CMPrefThumbnailHeightKey)
                let thumbnailHeight = CMNormalizedLegacyThumbnailDimension(storedThumbnailHeight)
                if thumbnailHeight != storedThumbnailHeight {
                    defaults.set(thumbnailHeight, forKey: CMPrefThumbnailHeightKey)
                }
                if let thumbnail = thumbnail(for: image, fitting: NSSize(width: thumbnailWidth, height: thumbnailHeight)) {
                    item.image = thumbnail
                    return
                }
            } else {
                return
            }
        }

        guard defaults.bool(forKey: CMPrefShowIconInTheMenuKey),
              let icon = fileTypeIcon(for: clip.primaryPasteboardType) else {
            return
        }
        item.image = sizedMenuIcon(icon)
    }

    private func isImagePasteboardType(_ type: NSPasteboard.PasteboardType?) -> Bool {
        switch type {
        case .tiff, .clipMenuPICT:
            return true
        default:
            return false
        }
    }

    private func thumbnail(for image: NSImage, fitting size: NSSize) -> NSImage? {
        guard let bitmapRep = image.representations.first(where: { $0 is NSBitmapImageRep }) as? NSBitmapImageRep else {
            return nil
        }

        let originalWidth = CGFloat(bitmapRep.pixelsWide)
        let originalHeight = CGFloat(bitmapRep.pixelsHigh)
        guard originalWidth > 0, originalHeight > 0 else { return nil }

        let scale = min(size.width / originalWidth, size.height / originalHeight, 1)
        let targetSize = NSSize(width: originalWidth * scale, height: originalHeight * scale)
        let thumbnail = NSImage(size: targetSize)
        thumbnail.lockFocus()
        NSGraphicsContext.current?.imageInterpolation = .high
        image.draw(in: NSRect(origin: .zero, size: targetSize), from: .zero, operation: .copy, fraction: 1)
        thumbnail.unlockFocus()
        return thumbnail
    }

    private func fileTypeIcon(for type: NSPasteboard.PasteboardType?) -> NSImage? {
        guard let type, let preference = menuIconPreference(for: type) else {
            return nil
        }

        let defaults = UserDefaults.standard
        let storedFileType = defaults.string(forKey: preference.fileTypeKey)
        let storedTag = defaults.object(forKey: preference.tagKey) as? Int ?? preference.defaultSelectionTag
        let normalizedTag = CMNormalizedTypeFileIconSelectionTag(storedTag)
        let fileType = CMNormalizedMenuIconFileTypeValue(
            storedFileType,
            defaultValue: preference.defaultFileType,
            selectionTag: normalizedTag
        )
        if normalizedTag != storedTag {
            defaults.set(normalizedTag, forKey: preference.tagKey)
        }
        if fileType != storedFileType {
            defaults.set(fileType, forKey: preference.fileTypeKey)
        }
        if normalizedTag == 1 {
            return CMIconForLegacyHFSType(legacyHFSTypeCode(from: fileType))
        }
        return CMIconForFileType(fileType)
    }

    private func menuFolderIcon(open: Bool = false) -> NSImage {
        let hfsType = open ? kOpenFolderIcon : kGenericFolderIcon
        let icon = CMIconForLegacyHFSType(OSType(hfsType))
        return sizedMenuIcon(icon)
    }

    private func menuSnippetIcon() -> NSImage {
        let icon = CMIconForLegacyHFSType(OSType(kClippingTextTypeIcon))
        return sizedMenuIcon(icon)
    }

    private func menuActionIcon(for action: [String: String]) -> NSImage? {
        guard UserDefaults.standard.bool(forKey: CMPrefShowIconInTheMenuKey) else { return nil }
        switch action["type"] {
        case "builtin":
            let iconName = UserDefaults.standard.integer(forKey: CMPrefMenuIconSizeKey) <= 16 ? "ActionIcon" : "ActionIconLarge"
            if let icon = NSImage(named: iconName) {
                return sizedMenuIcon(icon)
            }
            return nil
        case "js":
            return sizedMenuIcon(CMIconForFileType("js"))
        default:
            return nil
        }
    }

    private func sizedMenuIcon(_ icon: NSImage) -> NSImage {
        let size = CMNormalizedTypeLegacyMenuIconSize(
            UserDefaults.standard.integer(forKey: CMPrefMenuIconSizeKey)
        )
        let copy = icon.copy() as? NSImage ?? icon
        copy.size = NSSize(width: size, height: size)
        return copy
    }

    private struct MenuIconPreference {
        let tagKey: String
        let fileTypeKey: String
        let defaultSelectionTag: Int
        let defaultFileType: String
    }

    private func menuIconPreference(for type: NSPasteboard.PasteboardType) -> MenuIconPreference? {
        switch type {
        case .string:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForStringKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForStringKey,
                defaultSelectionTag: 1,
                defaultFileType: "TEXT"
            )
        case .rtf:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForRTFKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForRTFKey,
                defaultSelectionTag: 0,
                defaultFileType: "rtf"
            )
        case .rtfd:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForRTFDKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForRTFDKey,
                defaultSelectionTag: 0,
                defaultFileType: "rtfd"
            )
        case .pdf:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForPDFKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForPDFKey,
                defaultSelectionTag: 0,
                defaultFileType: "pdf"
            )
        case .clipMenuFilenames:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForFilenamesKey,
                defaultSelectionTag: 1,
                defaultFileType: "clpu"
            )
        case .clipMenuURL:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForURLKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForURLKey,
                defaultSelectionTag: 1,
                defaultFileType: "gurl"
            )
        case .tiff:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForTIFFKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForTIFFKey,
                defaultSelectionTag: 0,
                defaultFileType: "tiff"
            )
        case .clipMenuPICT:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForPICTKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForPICTKey,
                defaultSelectionTag: 0,
                defaultFileType: "pict"
            )
        default:
            return nil
        }
    }

#if TESTING
    func debugMenuIconPreferencesForTesting() -> [[String: Any]] {
        [
            NSPasteboard.PasteboardType.string,
            .rtf,
            .rtfd,
            .pdf,
            .clipMenuFilenames,
            .clipMenuURL,
            .tiff,
            .clipMenuPICT,
            .png
        ].map { type in
            let preference = menuIconPreference(for: type)
            return [
                "type": type.rawValue,
                "tagKey": preference?.tagKey ?? "",
                "fileTypeKey": preference?.fileTypeKey ?? "",
                "defaultSelectionTag": preference?.defaultSelectionTag as Any,
                "defaultFileType": preference?.defaultFileType ?? ""
            ]
        }
    }
#endif

    private func legacyHFSTypeCode(from value: String) -> OSType {
        NSHFSTypeCodeFromFileType("'\(value)'")
    }

    private enum MenuPopupEventStyle {
        case hotKey
        case action
    }

    private func popUpMenuAtMouseLocation(_ menu: NSMenu, style: MenuPopupEventStyle = .hotKey) {
        let window = popupWindow ?? {
            let window = NSWindow(
                contentRect: .zero,
                styleMask: .borderless,
                backing: .buffered,
                defer: false
            )
            window.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
            popupWindow = window
            return window
        }()

        let currentEvent = NSApp.currentEvent
        let screenLocation: NSPoint
        switch style {
        case .hotKey:
            screenLocation = NSEvent.mouseLocation
        case .action:
            screenLocation = NSEvent.mouseLocation
        }
        window.setFrameOrigin(screenLocation)
        window.makeKeyAndOrderFront(nil)

#if DEBUG || TESTING
        if debugCapturePopupMenus {
            debugCapturedPopupMenuSummaries.append(
                debugPopupMenuSummary(menu: menu, style: style, screenLocation: screenLocation)
            )
            window.orderOut(nil)
            return
        }
#endif

        let localPoint = window.convertPoint(fromScreen: screenLocation)
        guard let view = window.contentView,
              let event = popupEvent(
                style: style,
                currentEvent: currentEvent,
                location: localPoint,
                windowNumber: window.windowNumber
              ) else {
            window.orderOut(nil)
            return
        }

        beginTrackingPopupInteraction()
        NSMenu.popUpContextMenu(menu, with: event, for: view)
        endTrackingPopupInteraction()
        window.orderOut(nil)
    }

#if DEBUG || TESTING
    private func debugPopupMenuSummary(menu: NSMenu, style: MenuPopupEventStyle, screenLocation: NSPoint) -> [String: Any] {
        let topLevelTitles = menu.items.map { $0.isSeparatorItem ? "<separator>" : $0.title }
        let submenuTitlesByParent = Dictionary(uniqueKeysWithValues: menu.items.compactMap { item -> (String, [String])? in
            guard let submenu = item.submenu else { return nil }
            return (item.title, submenu.items.map { $0.isSeparatorItem ? "<separator>" : $0.title })
        })

        return [
            "menuTitle": menu.title,
            "style": style == .hotKey ? "hotKey" : "action",
            "topLevelCount": menu.items.count,
            "topLevelTitles": topLevelTitles,
            "submenuTitlesByParent": submenuTitlesByParent,
            "screenLocation": [
                "x": screenLocation.x,
                "y": screenLocation.y
            ]
        ]
    }
#endif

    private func popupEvent(
        style: MenuPopupEventStyle,
        currentEvent: NSEvent?,
        location: NSPoint,
        windowNumber: Int
    ) -> NSEvent? {
        switch style {
        case .hotKey:
            return NSEvent.otherEvent(
                with: currentEvent?.type ?? .applicationDefined,
                location: location,
                modifierFlags: currentEvent?.modifierFlags ?? [],
                timestamp: currentEvent?.timestamp ?? 0,
                windowNumber: windowNumber,
                context: nil,
                subtype: 0,
                data1: 0,
                data2: 0
            )
        case .action:
            guard let currentEvent else {
                return NSEvent.otherEvent(
                    with: .applicationDefined,
                    location: location,
                    modifierFlags: [],
                    timestamp: 0,
                    windowNumber: windowNumber,
                    context: nil,
                    subtype: 0,
                    data1: 0,
                    data2: 0
                )
            }

            switch currentEvent.type {
            case .leftMouseDown, .leftMouseUp, .rightMouseDown, .rightMouseUp, .keyDown:
                return NSEvent.otherEvent(
                    with: .applicationDefined,
                    location: location,
                    modifierFlags: [],
                    timestamp: 0,
                    windowNumber: windowNumber,
                    context: nil,
                    subtype: 0,
                    data1: 0,
                    data2: 0
                )
            default:
                return NSEvent.otherEvent(
                    with: currentEvent.type,
                    location: location,
                    modifierFlags: currentEvent.modifierFlags,
                    timestamp: currentEvent.timestamp,
                    windowNumber: windowNumber,
                    context: nil,
                    subtype: 0,
                    data1: 0,
                    data2: 0
                )
            }
        }
    }

    @objc(selectMenuItem:) fileprivate func selectClip(_ sender: NSMenuItem) {
        let traceStarted = ProcessInfo.processInfo.systemUptime
        CMTraceMenuPaste("selection.begin")
        defer { CMTraceMenuPaste(String(format: "selection.end elapsedMs=%.1f", (ProcessInfo.processInfo.systemUptime - traceStarted) * 1000)) }
        dismissImageHoverPreview()
        guard let id = sender.representedObject as? String,
              let clip = clipsStore.clip(with: id) else { return }
        debugPasteFlow("selectClip title=\(sender.title) targetText=\(clip.text)")
        if applyActionIfRequested(to: .clip(clip.id), sender: sender) {
            return
        }
        CMTraceMenuPaste("selection.pasteboard.begin")
        // The item is already in history. Acknowledge exactly our ownership
        // generation so polling neither recaptures it nor skips a later copy.
        lastChangeCount = clip.write(to: pasteboard)
        CMTraceMenuPaste("selection.pasteboard.end")
        debugPasteFlow("selectClip wroteToPasteboard")

        let defaults = UserDefaults.standard
        let shouldReorder = CMNormalizedLegacyReorderClipsAfterPastingValue(
            defaults.object(forKey: CMPrefReorderClipsAfterPasting)
        )
        if shouldReorder != defaults.bool(forKey: CMPrefReorderClipsAfterPasting)
            || !(defaults.object(forKey: CMPrefReorderClipsAfterPasting) is Bool) {
            defaults.set(shouldReorder, forKey: CMPrefReorderClipsAfterPasting)
        }

        if shouldReorder {
            CMTraceMenuPaste("selection.reorder.begin")
            clipsStore.promote(clip.id)
            CMTraceMenuPaste("selection.reorder.end")
            persistCapturedHistoryAsynchronouslyIfPreferred()
        }

        let shouldSynthesizePaste = defaults.bool(forKey: CMPrefInputPasteCommandKey)
        debugPasteFlow("selectClip shouldSynthesizePaste=\(shouldSynthesizePaste)")
        if shouldSynthesizePaste {
            synthesizePasteIfEnabled()
        }
        if shouldReorder {
            rebuildMenu()
        }
    }

    @objc(selectSnippetMenuItem:) fileprivate func selectSnippet(_ sender: NSMenuItem) {
        guard let snippet = sender.representedObject as? SnippetActionReference else { return }
        let snippetContent = snippet.content.replacingOccurrences(of: "\n", with: "\\n")
        debugPasteFlow("selectSnippet title=\(sender.title) content=\(snippetContent)")
        if applyActionIfRequested(to: .snippet(snippet), sender: sender) {
            return
        }
        pasteboard.clearContents()
        pasteboard.setString(snippet.content, forType: .string)
        debugPasteFlow("selectSnippet wroteToPasteboard")
        let shouldSynthesizePaste = UserDefaults.standard.bool(forKey: CMPrefInputPasteCommandKey)
        debugPasteFlow("selectSnippet shouldSynthesizePaste=\(shouldSynthesizePaste)")
        if shouldSynthesizePaste {
            synthesizePasteIfEnabled()
        }
    }

    private func applyActionIfRequested(to target: ActionTarget, sender: NSMenuItem) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: CMPrefEnableActionKey) else {
            debugPasteFlow("applyActionIfRequested disabled")
            return false
        }

        let event = NSApp.currentEvent
        let interactionType = lastPopupInteractionType ?? event?.type
        if isDispatchingPopupKeyEquivalent || interactionType == .keyDown {
            debugPasteFlow("applyActionIfRequested keyboardSelection")
            return false
        }
        if event == nil && lastPopupInteractionType == nil {
            debugPasteFlow("applyActionIfRequested noPopupEventContext")
            return false
        }
        guard interactionType == .leftMouseDown || interactionType == .leftMouseUp
                || interactionType == .rightMouseDown || interactionType == .rightMouseUp else {
            return false
        }
        let modifierFlags = currentModifierFlags(for: event)
        let isRightClick = currentMenuInteractionIsRightClick(event: event)
        let eventDescription = event.map { "\($0.type.rawValue)" } ?? "nil"
        let lastTypeDescription = lastPopupInteractionType.map { "\($0.rawValue)" } ?? "nil"
        let behavior: Any?
        if isRightClick || modifierFlags.contains(.control) {
            behavior = defaults.object(forKey: CMPrefContorlClickBehaviorKey)
        } else if modifierFlags.contains(.shift) {
            behavior = defaults.object(forKey: CMPrefShiftClickBehaviorKey)
        } else if modifierFlags.contains(.option) {
            behavior = defaults.object(forKey: CMPrefOptionClickBehaviorKey)
        } else if modifierFlags.contains(.command) {
            behavior = defaults.object(forKey: CMPrefCommandClickBehaviorKey)
        } else {
            debugPasteFlow("applyActionIfRequested noModifiers event=\(eventDescription) lastType=\(lastTypeDescription)")
            return false
        }

        let behaviorDescription: String
        if let behaviorString = behavior as? String {
            behaviorDescription = behaviorString
        } else if let action = actionDictionary(from: behavior) {
            behaviorDescription = action["name"] ?? action["type"] ?? "action"
        } else {
            behaviorDescription = "nil"
        }
        debugPasteFlow("applyActionIfRequested modifiers=\(modifierFlags.rawValue) rightClick=\(isRightClick) event=\(eventDescription) lastType=\(lastTypeDescription) behavior=\(behaviorDescription)")

        let invoked = invokeModifiedClickBehavior(behavior, popupTarget: target, sender: sender)
        debugPasteFlow("applyActionIfRequested invoked=\(invoked)")
        return invoked
    }

    private func currentModifierFlags(for event: NSEvent?) -> NSEvent.ModifierFlags {
        let eventFlags = event?.modifierFlags.normalizedShortcutFlags ?? []
        let trackedFlags = eventFlags.union(lastPopupInteractionFlags)
        if lastPopupInteractionType != nil || !trackedFlags.isEmpty {
            return trackedFlags
        }
        let globalFlags = NSEvent.modifierFlags.normalizedShortcutFlags
        return eventFlags.union(globalFlags)
    }

    private func currentMenuInteractionIsRightClick(event: NSEvent?) -> Bool {
        if event?.type == .rightMouseDown || event?.type == .rightMouseUp {
            return true
        }
        return lastPopupInteractionType == .rightMouseDown || lastPopupInteractionType == .rightMouseUp
    }

    private func beginTrackingPopupInteraction() {
        lastPopupInteractionFlags = []
        lastPopupInteractionType = nil
        popupInteractionMonitor = NSEvent.addLocalMonitorForEvents(matching: [.leftMouseDown, .leftMouseUp, .rightMouseDown, .rightMouseUp, .keyDown, .flagsChanged]) { [weak self] event in
            self?.recordPopupInteraction(event: event)
            return event
        }
        installPopupInteractionEventTap()
    }

    private func endTrackingPopupInteraction() {
        if let popupInteractionMonitor {
            NSEvent.removeMonitor(popupInteractionMonitor)
            self.popupInteractionMonitor = nil
        }
        if let popupInteractionRunLoopSource {
            CFRunLoopRemoveSource(CFRunLoopGetMain(), popupInteractionRunLoopSource, .commonModes)
            self.popupInteractionRunLoopSource = nil
        }
        if let popupInteractionEventTap {
            CGEvent.tapEnable(tap: popupInteractionEventTap, enable: false)
            self.popupInteractionEventTap = nil
        }
    }

    private func installPopupInteractionEventTap() {
        let events = [
            CGEventType.leftMouseDown,
            .leftMouseUp,
            .rightMouseDown,
            .rightMouseUp,
            .keyDown,
            .flagsChanged
        ]
        let mask = events.reduce(CGEventMask(0)) { partialResult, eventType in
            partialResult | (1 << eventType.rawValue)
        }

        let callback: CGEventTapCallBack = { _, type, event, userInfo in
            guard let userInfo else {
                return Unmanaged.passUnretained(event)
            }
            let controller = Unmanaged<AppController>.fromOpaque(userInfo).takeUnretainedValue()
            controller.recordPopupInteraction(type: type, event: event)
            return Unmanaged.passUnretained(event)
        }

#if TESTING
        if UserDefaults.standard.bool(forKey: "debugBypassPopupInteractionEventTapForTesting") {
            if let event = CGEvent(source: nil) {
                event.flags = [.maskShift, .maskCommand]
                let proxy = OpaquePointer(bitPattern: 1)!
                _ = callback(proxy, .rightMouseDown, event, nil)
                _ = callback(proxy, .keyDown, event, Unmanaged.passUnretained(self).toOpaque())
            }
            return
        }
#endif

        guard let eventTap = CGEvent.tapCreate(
            tap: .cgSessionEventTap,
            place: .headInsertEventTap,
            options: .listenOnly,
            eventsOfInterest: mask,
            callback: callback,
            userInfo: Unmanaged.passUnretained(self).toOpaque()
        ) else {
            return
        }

        let runLoopSource = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, eventTap, 0)
        CFRunLoopAddSource(CFRunLoopGetMain(), runLoopSource, .commonModes)
        CGEvent.tapEnable(tap: eventTap, enable: true)
        popupInteractionEventTap = eventTap
        popupInteractionRunLoopSource = runLoopSource
    }

    private func recordPopupInteraction(event: NSEvent) {
        lastPopupInteractionFlags = event.modifierFlags.normalizedShortcutFlags
        if event.type != .flagsChanged {
            lastPopupInteractionType = event.type
        }
    }

    private func recordPopupInteraction(type: CGEventType, event: CGEvent) {
        lastPopupInteractionFlags = modifierFlags(for: event.flags)
        if type != .flagsChanged {
            lastPopupInteractionType = menuInteractionEventType(for: type)
        }
    }

    private func modifierFlags(for flags: CGEventFlags) -> NSEvent.ModifierFlags {
        var result: NSEvent.ModifierFlags = []
        if flags.contains(.maskShift) {
            result.insert(.shift)
        }
        if flags.contains(.maskControl) {
            result.insert(.control)
        }
        if flags.contains(.maskAlternate) {
            result.insert(.option)
        }
        if flags.contains(.maskCommand) {
            result.insert(.command)
        }
        return result
    }

    private func menuInteractionEventType(for type: CGEventType) -> NSEvent.EventType? {
        switch type {
        case .leftMouseDown:
            return .leftMouseDown
        case .leftMouseUp:
            return .leftMouseUp
        case .rightMouseDown:
            return .rightMouseDown
        case .rightMouseUp:
            return .rightMouseUp
        case .keyDown:
            return .keyDown
        case .flagsChanged:
            return .flagsChanged
        default:
            return nil
        }
    }

    private func invokeModifiedClickBehavior(_ behavior: Any?, popupTarget: ActionTarget, sender: NSMenuItem) -> Bool {
        if let behavior = behavior as? String {
            guard !behavior.isEmpty else { return false }
            if behavior == "popUpActionMenu" {
                actionTarget = popupTarget
                defer { actionTarget = nil }

                let nodes = loadRuntimeActionNodes()
                if UserDefaults.standard.bool(forKey: CMPrefInvokeActionImmediatelyKey),
                   nodes.count == 1 {
                    if let action = nodes.first?.action {
                        invokeAction(action, target: popupTarget)
                    }
                    return true
                }

                let menu = makeActionMenu()
                if menu.numberOfItems > 0 {
                    popUpMenuAtMouseLocation(menu, style: .action)
                }
                return true
            }
            return false
        }

        if let action = actionDictionary(from: behavior) {
            let directTarget = legacyDirectActionTarget(for: sender)
            actionTarget = directTarget
            defer { actionTarget = nil }
            if let directTarget {
                invokeAction(action, target: directTarget)
            }
            return true
        }

        return false
    }

