    private func bundledRuntimeActionNodes() -> [RuntimeActionNode] {
        let candidates = [
            Bundle.main.resourceURL?
                .appendingPathComponent("script/action", isDirectory: true),
            URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
                .appendingPathComponent("resource/script/action", isDirectory: true)
        ].compactMap { $0 }

        guard let root = candidates.first(where: { FileManager.default.fileExists(atPath: $0.path) }) else {
            return []
        }
        return runtimeScriptNodes(walking: root)
    }

    private func bundledRuntimeScriptRelativePaths() -> [String] {
        var scriptPaths: [String] = []
        var builtinNames: [String] = []
        for node in bundledRuntimeActionNodes() {
            collectRuntimeActionSignatures(from: node, builtinNames: &builtinNames, scriptPaths: &scriptPaths)
        }
        return scriptPaths
    }

    private func runtimeScriptNodes(walking directoryURL: URL) -> [RuntimeActionNode] {
        guard let contents = try? FileManager.default.contentsOfDirectory(
            at: directoryURL,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles]
        ) else {
            return []
        }

        return contents.compactMap { url -> RuntimeActionNode? in
            let resourceValues = try? url.resourceValues(forKeys: [.isDirectoryKey])
            if resourceValues?.isDirectory == true {
                return RuntimeActionNode(
                    nodeTitle: NSLocalizedString(url.deletingPathExtension().lastPathComponent, comment: ""),
                    children: runtimeScriptNodes(walking: url)
                )
            }

            guard url.pathExtension == "js" else { return nil }
            return RuntimeActionNode(
                nodeTitle: NSLocalizedString(url.deletingPathExtension().lastPathComponent, comment: ""),
                action: ["type": "js", "path": url.path]
            )
        }
    }

    private func isActionPerformable(_ action: [String: String]) -> Bool {
        guard let type = action["type"] else { return false }
        switch type {
        case "builtin":
            let name = action["name"] ?? ""
            if name == "pasteAsPlainText:" {
                return targetContainsPasteboardType(.string)
            }
            if ["removeAction", "removeAction:", "remove:"].contains(name) {
                return true
            }
            if ["pasteAsFilePath:", "pasteAsHFSFilePath:"].contains(name) {
                return targetContainsPasteboardType(.clipMenuFilenames)
            }
            return false
        case "js":
            return targetContainsPasteboardType(.string)
        default:
            return false
        }
    }

    private func targetContainsPasteboardType(_ pasteboardType: NSPasteboard.PasteboardType) -> Bool {
        switch actionTarget {
        case .clip(let id):
            return clipsStore.clip(with: id.uuidString)?.types.contains(pasteboardType.rawValue) == true
        case .snippet:
            return pasteboardType == .string
        case nil:
            return false
        }
    }

    private func tooltipForAction(_ action: [String: String]) -> String? {
        switch action["name"] {
        case "pasteAsPlainText:":
            return NSLocalizedString("Paste the clip as Plain Text", comment: "")
        case "pasteAsFilePath:":
            return NSLocalizedString("Paste the clip as POSIX File Path", comment: "")
        case "pasteAsHFSFilePath:":
            return NSLocalizedString("Paste the clip as HFS File Path", comment: "")
        case "removeAction", "removeAction:", "remove:":
            return NSLocalizedString("Remove the clip from the clipboard history", comment: "")
        default:
            return nil
        }
    }

    @objc(selectActionMenuItem:) fileprivate func selectAction(_ sender: NSMenuItem) {
        guard let action = sender.representedObject as? [String: String],
              let target = actionTarget else { return }
        invokeAction(action, target: target)
    }

    private func invokeAction(_ action: [String: String], target: ActionTarget) {
        guard let type = action["type"] else { return }
        switch type {
        case "builtin":
            invokeBuiltinAction(action, target: target)
        case "js":
            invokeJavaScriptAction(action, target: target)
        default:
            return
        }
    }

    private func invokeBuiltinAction(_ action: [String: String], target: ActionTarget) {
        switch action["name"] {
        case "pasteAsPlainText:":
            guard let text = text(for: target) else { return }
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
            synthesizePasteForAction()
        case "removeAction", "removeAction:", "remove:":
            if case let .clip(id) = target {
                clipsStore.remove(id)
                rebuildMenu()
            } else if case let .snippet(snippet) = target {
                SnippetFileStore.shared.removeSnippet(folderID: snippet.folderID, snippetID: snippet.snippetID)
                rebuildMenu()
            }
        case "pasteAsFilePath:":
            guard let text = clip(for: target)?.filePathsText else { return }
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
            synthesizePasteForAction()
        case "pasteAsHFSFilePath:":
            guard let text = clip(for: target)?.hfsFilePathsText else { return }
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
            synthesizePasteForAction()
        default:
            NSSound.beep()
        }
    }

    private func invokeJavaScriptAction(_ action: [String: String], target: ActionTarget) {
        guard let scriptPath = action["path"],
              let sourceClip = scriptClip(for: target),
              let result = runJavaScriptAction(at: scriptPath, clip: sourceClip) else {
            return
        }
        result.write(to: pasteboard)
        synthesizePasteForAction()
    }

    private func text(for target: ActionTarget?) -> String? {
        guard let target else { return nil }
        switch target {
        case .clip(let id):
            return clipsStore.clips.first { $0.id == id }?.text
        case .snippet(let snippet):
            return snippet.content
        }
    }

    private func clip(for target: ActionTarget?) -> ClipItem? {
        guard let target, case let .clip(id) = target else { return nil }
        return clipsStore.clips.first { $0.id == id }
    }

    private func scriptClip(for target: ActionTarget) -> ClipItem? {
        switch target {
        case .clip(let id):
            return clipsStore.clips.first { $0.id == id }
        case .snippet(let snippet):
            return ClipItem(text: snippet.content)
        }
    }

    private func runJavaScriptAction(at scriptPath: String, clip: ClipItem) -> ClipItem? {
        guard !clip.text.isEmpty else { return nil }

        guard let scriptURL = resolvedActionScriptURL(for: scriptPath) else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("The script you selected does not exist", comment: ""),
                message: ""
            )
            return nil
        }

        guard let script = try? String(contentsOf: scriptURL, encoding: .utf8) else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Unable to load script", comment: ""),
                message: NSLocalizedString("Your script file does not exist.", comment: "")
            )
            return nil
        }

        guard let context = JSContext() else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Error", comment: ""),
                message: NSLocalizedString("Failed to evaluate script", comment: "")
            )
            return nil
        }

        let scriptableClip = ScriptableActionClip(clip: clip)
        context.setObject(scriptableClip.stringValue, forKeyedSubscript: "clipText" as NSString)
        guard let clipObject = JSValue(newObjectIn: context) else { return nil }
        let getStringValue: @convention(block) () -> String = {
            scriptableClip.stringValue
        }
        let setStringValue: @convention(block) (String) -> Void = { value in
            scriptableClip.setStringValue(value)
        }
        let setStringAttributes: @convention(block) (JSValue) -> Void = { attributes in
            scriptableClip.setStringAttributes(attributes)
        }
        let addStringAttributes: @convention(block) (JSValue) -> Void = { attributes in
            scriptableClip.addStringAttributes(attributes)
        }
        clipObject.setObject(getStringValue, forKeyedSubscript: "__getStringValue" as NSString)
        clipObject.setObject(setStringValue, forKeyedSubscript: "__setStringValue" as NSString)
        clipObject.setObject(setStringAttributes, forKeyedSubscript: "setStringAttributes" as NSString)
        clipObject.setObject(addStringAttributes, forKeyedSubscript: "addStringAttributes" as NSString)
        context.setObject(clipObject, forKeyedSubscript: "clip" as NSString)
        let require: @convention(block) (String?) -> Bool = { filename in
            guard let filename, !filename.isEmpty else { return false }
            let scriptName = (filename as NSString).pathExtension == "js"
                ? filename
                : (filename as NSString).appendingPathExtension("js") ?? "\(filename).js"
            let candidates = [
                self.userActionLibrariesURL()
                    .appendingPathComponent(scriptName),
                Bundle.main.resourceURL?
                    .appendingPathComponent("script/lib", isDirectory: true)
                    .appendingPathComponent(scriptName)
            ].compactMap { $0 }

            for url in candidates where FileManager.default.fileExists(atPath: url.path) {
                if let library = try? String(contentsOf: url, encoding: .utf8) {
                    context.evaluateScript(library)
                    return true
                }
            }
            return false
        }
        let activate: @convention(block) () -> Void = {
            self.keepCurrentFrontmostApplicationAndActivateForJavaScript()
        }
        let prompt: @convention(block) (String?, String?) -> String? = { message, defaultValue in
            self.runOnMainThread {
                self.promptForJavaScript(message: message, defaultValue: defaultValue)
            }
        }
        let alert: @convention(block) (String?) -> Void = { message in
            self.runOnMainThread {
                let dialog = self.makeJavaScriptBridgeAlert(message: message)
                _ = self.runJavaScriptModal(dialog)
            }
        }
        let confirm: @convention(block) (String?) -> Bool = { message in
            self.runOnMainThread {
                let dialog = self.makeJavaScriptBridgeConfirm(message: message)
                let result = self.runJavaScriptModal(dialog)
                return self.javaScriptConfirmationAccepted(response: result)
            }
        }
        let bridge: [String: Any] = [
            "require": require,
            "activate": activate
        ]
        context.setObject(bridge, forKeyedSubscript: "ClipMenu" as NSString)
        context.setObject(prompt, forKeyedSubscript: "prompt" as NSString)
        context.setObject(alert, forKeyedSubscript: "alert" as NSString)
        context.setObject(confirm, forKeyedSubscript: "confirm" as NSString)

        var exceptionMessage: String?
        context.exceptionHandler = { _, exception in
            exceptionMessage = exception?.toString()
        }
        defer {
            restorePreviousFrontmostApplicationForJavaScript()
        }

        context.evaluateScript("""
        var exports = {};
        var module = { exports: exports };
        Object.defineProperty(clip, 'stringValue', {
            get: clip.__getStringValue,
            set: clip.__setStringValue
        });
        delete clip.__getStringValue;
        delete clip.__setStringValue;
        """)
        guard exceptionMessage == nil else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Error", comment: ""),
                message: NSLocalizedString("Failed to evaluate script", comment: "")
            )
            return nil
        }

        context.setObject("", forKeyedSubscript: "__scriptException" as NSString)
        context.evaluateScript("""
        function __clipMenuWrapper() {
            try {
                \(script)
            } catch (e) {
                __scriptException = e.toString();
                return;
            }
        }
        """)
        guard exceptionMessage == nil else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Error", comment: ""),
                message: NSLocalizedString("Failed to evaluate script", comment: "")
            )
            return nil
        }

        exceptionMessage = nil
        context.evaluateScript("var __clipMenuResult = __clipMenuWrapper();")
        guard exceptionMessage == nil else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Exception Raised", comment: ""),
                message: exceptionMessage ?? ""
            )
            return nil
        }
        if let scriptException = context.objectForKeyedSubscript("__scriptException")?.toString(),
           !scriptException.isEmpty {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Exception Raised", comment: ""),
                message: scriptException
            )
            return nil
        }

        guard let result = context.objectForKeyedSubscript("__clipMenuResult") else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Error", comment: ""),
                message: NSLocalizedString("Failed to evaluate script", comment: "")
            )
            return nil
        }

        guard !result.isUndefined else { return nil }

        if context.evaluateScript("__clipMenuResult === clip")?.toBool() == true {
            return scriptableClip.clip
        }

        return ClipItem(text: result.toString())
    }

#if TESTING
