            "viewClassNames": views.map { String(describing: type(of: $0)) },
            "legacyStatusTemplate": legacyStatusTemplateImage().isTemplate,
            "preferredFontApplied": (menuItem.attributedTitle?.length ?? 0) > 0,
            "checkForUpdatesEnabled": validateMenuItem(checkForUpdatesItem),
            "clearHistoryEnabled": validateMenuItem(clearHistoryItem),
            "keyName": stringForKeyCode(CGKeyCode(kVK_ANSI_V)) as Any,
            "popupEventCount": popupEvents.count,
            "excludedAppCount": excludedApps.count,
            "actionSurfaceState": actionSurfaceState,
            "menuSurfaceState": menuSurfaceState,
            "menuIconDefaults": menuIconDefaults
        ]
    }
#endif

    @objc private func clearHistory(_ sender: Any?) {
        _ = performClearHistory()
    }

    @objc fileprivate func performMenuControllerSelectClip(_ sender: Any?) {
        guard let item = sender as? NSMenuItem else { return }
        selectClip(item)
    }

    @objc fileprivate func performMenuControllerSelectSnippet(_ sender: Any?) {
        guard let item = sender as? NSMenuItem else { return }
        selectSnippet(item)
    }

    @objc fileprivate func performMenuControllerSelectAction(_ sender: Any?) {
        guard let item = sender as? NSMenuItem else { return }
        selectAction(item)
    }

    @discardableResult
    private func performClearHistory(
        confirmationResolver: (() -> ClearHistoryAlertResolution)? = nil
    ) -> Bool {
        if UserDefaults.standard.bool(forKey: CMPrefShowAlertBeforeClearHistoryKey) {
            let resolution: ClearHistoryAlertResolution
            if let confirmationResolver {
                resolution = confirmationResolver()
            } else {
                let alert = makeClearHistoryPrompt()
                NSApp.activate(ignoringOtherApps: true)

                let result = alert.runModal()
                resolution = ClearHistoryAlertResolution(
                    confirmed: result == .alertFirstButtonReturn,
                    suppressFutureAlerts: alert.suppressionButton?.state == .on
                )
            }

            if resolution.suppressFutureAlerts {
                UserDefaults.standard.set(false, forKey: CMPrefShowAlertBeforeClearHistoryKey)
            }
            guard resolution.confirmed else { return false }
        }

        clipsStore.clear()
        rebuildMenu()
        return true
    }

    @objc func exportHistory(_ sender: Any?) {
        if UserDefaults.standard.bool(forKey: CMPrefExportHistoryAsSingleFileKey) {
            exportHistoryAsSingleFile()
        } else {
            exportHistoryAsMultipleFiles()
        }
    }

    @objc private func performClose(_ sender: Any?) {
        closableWindow()?.performClose(sender)
    }

    @objc private func saveDocument(_ sender: Any?) {
        guard snippetEditorController?.window?.isVisible == true else { return }
        snippetEditorController?.saveDocument(sender)
    }

    @objc private func saveDocumentAs(_ sender: Any?) {
        guard snippetEditorController?.window?.isVisible == true else { return }
        snippetEditorController?.saveDocumentAs(sender)
    }

    @objc private func revertDocumentToSaved(_ sender: Any?) {
        guard snippetEditorController?.window?.isVisible == true else { return }
        snippetEditorController?.revertDocumentToSaved(sender)
    }

    @objc private func openRecentSnippetDocument(_ sender: NSMenuItem) {
        guard let url = sender.representedObject as? URL else { return }
        showSnippetEditor(nil)
        snippetEditorController?.importSnippets(from: url)
        NSDocumentController.shared.noteNewRecentDocumentURL(url)
    }

    @objc private func clearRecentSnippetDocuments(_ sender: Any?) {
        NSDocumentController.shared.clearRecentDocuments(sender)
        if let menu = (sender as? NSMenuItem)?.menu {
            rebuildOpenRecentMenu(menu)
        }
    }

    @objc func refreshMainMenuDocumentItems(_ sender: Any?) {
        installMainMenu()
    }

    private func restoreRecentDocumentURLs(_ urls: [URL], documentController: NSDocumentController = .shared) {
        documentController.clearRecentDocuments(nil)
        for url in urls.reversed() {
            documentController.noteNewRecentDocumentURL(url)
        }
        refreshMainMenuDocumentItems(nil)
    }

    @objc private func restorePreviousFrontProcess() -> Bool {
        guard hasStoredPreviousFrontProcessSerialNumber() else {
            return true
        }
        let osError = carbonSetFrontProcess(&previousFrontProcessSerialNumber)
        resetPreviousFrontProcessSerialNumber()
        return osError == noErr
    }

    private func rebuildOpenRecentMenu(_ menu: NSMenu) {
        menu.removeAllItems()
        let recentURLs = NSDocumentController.shared.recentDocumentURLs
        for recentURL in recentURLs {
            let item = NSMenuItem(title: recentURL.lastPathComponent, action: #selector(openRecentSnippetDocument(_:)), keyEquivalent: "")
            item.target = self
            item.representedObject = recentURL
            item.toolTip = recentURL.path
            menu.addItem(item)
        }
        if !recentURLs.isEmpty {
            menu.addItem(.separator())
        }
        let clearRecentItem = NSMenuItem(title: NSLocalizedString("Clear Menu", comment: ""), action: #selector(clearRecentSnippetDocuments(_:)), keyEquivalent: "")
        clearRecentItem.target = self
        clearRecentItem.isEnabled = !recentURLs.isEmpty
        menu.addItem(clearRecentItem)
    }

    private func exportHistoryAsSingleFile() {
        let panel = NSSavePanel()
        panel.canCreateDirectories = true
        panel.allowedContentTypes = [.plainText]
        panel.nameFieldStringValue = "clipboard_history.txt"
        beginHistoryExportPanel(panel) { [weak self] response in
            guard response == .OK, let url = panel.url else { return }
            self?.finishExport {
                try self?.clipsStore.exportTextClipsAsSingleFile(to: url)
            }
        }
    }

    private func exportHistoryAsMultipleFiles() {
        let panel = NSOpenPanel()
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.canCreateDirectories = true
        panel.prompt = NSLocalizedString("Select", comment: "")
        beginHistoryExportPanel(panel) { [weak self] response in
            guard response == .OK, let url = panel.url else { return }
            self?.finishExport {
                try self?.clipsStore.exportTextClipsAsMultipleFiles(to: url)
            }
        }
    }

    private func beginHistoryExportPanel(_ panel: NSSavePanel, completion: @escaping (NSApplication.ModalResponse) -> Void) {
        if let preferencesWindow = SwiftUIPreferencesWindowController.shared.window,
           preferencesWindow.isVisible {
            panel.beginSheetModal(for: preferencesWindow, completionHandler: completion)
        } else {
            panel.begin(completionHandler: completion)
        }
    }

    private func finishExport(_ operation: () throws -> Void) {
        do {
            try operation()
        } catch {
            NSApp.activate(ignoringOtherApps: true)
            let alert = makeHistoryExportFailureAlert()
            CMShowAlert(
                alert,
                sheetFor: NSApp.keyWindow ?? NSApp.mainWindow ?? SwiftUIPreferencesWindowController.shared.window
            )
        }
    }

    @objc private func showPreferencePanel(_ sender: Any?) {
        SwiftUIPreferencesWindowController.shared.showWindow(nil)
    }

    @objc fileprivate func performStatusMenuShowPreferencePanel(_ sender: Any?) {
        showPreferencePanel(sender)
    }

    @objc private func checkForUpdates(_ sender: Any?) {
        UpdateCoordinator.shared.checkForUpdates()
    }

    @objc private func showSnippetEditor(_ sender: Any?) {
        if snippetEditorController == nil {
            snippetEditorController = SwiftUISnippetEditorWindowController()
        }
        snippetEditorController?.showWindow(self)
    }

    @objc private func popUpClipMenu(_ sender: Any?) {
        showMenu(for: .mainMenu)
    }

    @objc private func popUpSnippetsMenu(_ sender: Any?) {
        showMenu(for: .snippetsMenu)
    }

    @objc private func popUpActionMenu(_ sender: Any?) {
        let nodes = loadRuntimeActionNodes()
        guard !nodes.isEmpty else { return }

        let popupTarget: ActionTarget?
        if let item = sender as? NSMenuItem,
           let snippet = item.representedObject as? SnippetActionReference {
            popupTarget = .snippet(snippet)
        } else if let item = sender as? NSMenuItem,
                  let clipID = (item.representedObject as? String).flatMap(UUID.init(uuidString:)) {
            popupTarget = .clip(clipID)
        } else if let existingTarget = actionTarget {
            popupTarget = existingTarget
        } else {
            popupTarget = nil
        }

        guard let popupTarget else { return }

        actionTarget = popupTarget
        defer { actionTarget = nil }

        if UserDefaults.standard.bool(forKey: CMPrefInvokeActionImmediatelyKey),
           nodes.count == 1,
           let action = nodes.first?.action {
            invokeAction(action, target: popupTarget)
            return
        }

        let menu = makeActionMenu()
        guard menu.numberOfItems > 0 else { return }
        popUpMenuAtMouseLocation(menu, style: .action)
    }

    @objc private func keepCurrentFrontProcessAndActivate() {
        resetPreviousFrontProcessSerialNumber()
        let osError = carbonGetFrontProcess(&previousFrontProcessSerialNumber)
        if osError != noErr {
            resetPreviousFrontProcessSerialNumber()
        }
        NSApp.activate(ignoringOtherApps: true)
    }

    @objc fileprivate func performStatusMenuShowSnippetEditor(_ sender: Any?) {
        showSnippetEditor(sender)
    }

    @objc fileprivate func performStatusMenuClearHistory(_ sender: Any?) {
        clearHistory(sender)
    }

    @objc(print:) private func `print`(_ sender: Any?) {
        guard let window = printableWindow(),
              let contentView = window.contentView else {
            NSSound.beep()
            return
        }
        let printOperation = NSPrintOperation(view: contentView)
        printOperation.run()
    }

    private func printableWindow() -> NSWindow? {
        guard let snippetWindow = snippetEditorController?.window,
              snippetWindow.isVisible,
              !snippetWindow.isMiniaturized else {
            return nil
        }
        return snippetWindow
    }

    private func closableWindow() -> NSWindow? {
        let candidateWindows = [NSApp.keyWindow, NSApp.mainWindow].compactMap { $0 }
        for candidate in candidateWindows {
            if candidate == snippetEditorController?.window || candidate == SwiftUIPreferencesWindowController.shared.window,
               candidate.isVisible,
               !candidate.isMiniaturized {
                return candidate
            }
        }

        if let snippetWindow = snippetEditorController?.window,
           snippetWindow.isVisible,
           !snippetWindow.isMiniaturized {
            return snippetWindow
        }

        if let preferencesWindow = SwiftUIPreferencesWindowController.shared.window,
           preferencesWindow.isVisible,
           !preferencesWindow.isMiniaturized {
            return preferencesWindow
        }

        return nil
    }

}

