final class ClipStore {
    private(set) var clips: [ClipItem] = []
    private var hasUnsavedChanges = false
    private var persistenceRevision: UInt64 = 0
    private var pendingAsyncSaves: [PersistenceIdentity: [(Bool) -> Void]] = [:]

    // Store state belongs to the main thread. Only immutable snapshots cross this queue.
    // Sharing the queue also orders saves, loads, and deletion across store instances.
    private static let persistenceQueue = DispatchQueue(label: "ClipMenu.history-persistence", qos: .utility)

    private struct PersistenceIdentity: Hashable {
        let revision: UInt64
        let archiveURL: URL
        let jsonURL: URL
    }

    private struct PersistenceSnapshot {
        let identity: PersistenceIdentity
        let clips: [ClipItem]
        let orderedClips: [ClipItem]
#if DEBUG || TESTING
        var beforeWrite: (() -> Void)?
#endif
    }

#if DEBUG || TESTING
    var debugPersistenceDirectoryForTesting: URL?
    var debugBeforePersistenceWriteForTesting: (() -> Void)?
#endif

#if DEBUG
    struct DebugSnapshot {
        let clips: [ClipItem]
        let hasUnsavedChanges: Bool
    }

    var debugSnapshotForTesting: DebugSnapshot {
        DebugSnapshot(clips: clips, hasUnsavedChanges: hasUnsavedChanges)
    }

    func debugRestoreSnapshotForTesting(_ snapshot: DebugSnapshot) {
        persistenceRevision &+= 1
        clips = snapshot.clips
        hasUnsavedChanges = snapshot.hasUnsavedChanges
    }
#endif

    var debugHasUnsavedChanges: Bool {
        hasUnsavedChanges
    }

    var orderedClips: [ClipItem] {
        let defaults = UserDefaults.standard
        let sortByLastUsed = CMNormalizedLegacyReorderClipsAfterPastingValue(
            defaults.object(forKey: CMPrefReorderClipsAfterPasting)
        )
        if sortByLastUsed != defaults.bool(forKey: CMPrefReorderClipsAfterPasting)
            || !(defaults.object(forKey: CMPrefReorderClipsAfterPasting) is Bool) {
            defaults.set(sortByLastUsed, forKey: CMPrefReorderClipsAfterPasting)
        }

        let keyPath: KeyPath<ClipItem, Date> = sortByLastUsed ? \.lastUsedAt : \.createdAt
        return clips.sorted {
            let left = $0[keyPath: keyPath]
            let right = $1[keyPath: keyPath]
            if left == right {
                return $0.createdAt > $1.createdAt
            }
            return left > right
        }
    }

    var hasTextClips: Bool {
        clips.contains { !$0.text.isEmpty }
    }

    private var supportDirectory: URL {
#if DEBUG || TESTING
        if let debugPersistenceDirectoryForTesting {
            return debugPersistenceDirectoryForTesting
        }
#endif
        return clipMenuApplicationSupportDirectory()
    }

    private var fileURL: URL {
        supportDirectory.appendingPathComponent("clips.data")
    }

    private var jsonFileURL: URL {
        supportDirectory.appendingPathComponent("clips.json")
    }

    func load() {
        persistenceRevision &+= 1
        Self.persistenceQueue.sync {}
        if shouldPreferJSONStore(),
           let jsonClips = loadJSONClips(from: jsonFileURL) {
            clips = jsonClips
            trim()
            save()
            return
        }

        if let swiftClips = loadJSONClips(from: fileURL) {
            clips = swiftClips
            trim()
            hasUnsavedChanges = false
            return
        }

        if let legacyClips = loadLegacyClips() {
            clips = legacyClips
            trim()
            save()
            return
        }

        if let jsonClips = loadJSONClips(from: jsonFileURL) {
            clips = jsonClips
            trim()
            save()
            return
        }

        clips = []
        hasUnsavedChanges = false
    }

    @discardableResult
    func save() -> Bool {
        // A final synchronous save supersedes completions from earlier async saves.
        persistenceRevision &+= 1
        let snapshot = makePersistenceSnapshot()
        let saved = Self.persistenceQueue.sync { Self.writePersistenceSnapshot(snapshot) }
        hasUnsavedChanges = !saved
        return saved
    }

    @discardableResult
    func saveIfNeeded() -> Bool {
        guard hasUnsavedChanges else { return true }
        return save()
    }

    func saveIfNeededAsync(completion: @escaping (Bool) -> Void) {
        guard hasUnsavedChanges else {
            DispatchQueue.main.async { completion(true) }
            return
        }

        let snapshot = makePersistenceSnapshot()
        let identity = snapshot.identity
        if pendingAsyncSaves[identity] != nil {
            pendingAsyncSaves[identity]?.append(completion)
            return
        }
        pendingAsyncSaves[identity] = [completion]

        Self.persistenceQueue.async {
            let saved = Self.writePersistenceSnapshot(snapshot)
            DispatchQueue.main.async {
                let completions = self.pendingAsyncSaves.removeValue(forKey: identity) ?? []
                if self.currentPersistenceIdentity == identity {
                    self.hasUnsavedChanges = !saved
                }
                for completion in completions {
                    completion(saved)
                }
            }
        }
    }

    func removeSavedHistory() {
        let archiveURL = fileURL
        let jsonURL = jsonFileURL
        persistenceRevision &+= 1
        Self.persistenceQueue.sync {
            try? FileManager.default.removeItem(at: archiveURL)
            try? FileManager.default.removeItem(at: jsonURL)
        }
        hasUnsavedChanges = false
    }

    func add(_ clip: ClipItem) {
        if let index = clips.firstIndex(where: { $0.duplicateKey == clip.duplicateKey }) {
            clips[index].lastUsedAt = Date()
        } else {
            clips.append(clip)
        }
        trim()
        markUnsavedChanges()
    }

    func promote(_ id: UUID) {
        guard let index = clips.firstIndex(where: { $0.id == id }) else { return }
        clips[index].lastUsedAt = Date()
        markUnsavedChanges()
    }

    func clip(with uuidString: String) -> ClipItem? {
        guard let id = UUID(uuidString: uuidString) else { return nil }
        return clips.first { $0.id == id }
    }

    func clear() {
        clips.removeAll()
        markUnsavedChanges()
    }

    func remove(_ id: UUID) {
        clips.removeAll { $0.id == id }
        markUnsavedChanges()
    }

    func trimToCurrentHistoryLimit() {
        let oldCount = clips.count
        trim()
        if clips.count != oldCount {
            markUnsavedChanges()
        }
    }

    func exportTextClipsAsSingleFile(to url: URL) throws {
        guard !clips.isEmpty else { return }
        if FileManager.default.fileExists(atPath: url.path) {
            try FileManager.default.removeItem(at: url)
        }

        let separator = exportSeparator()
        let textClips = orderedClips.filter { $0.hasStringPasteboardType }
        guard !textClips.isEmpty else { return }

        let contents = textClips.map { $0.text + separator }.joined()
        try contents.write(to: url, atomically: true, encoding: .utf8)
    }

    func exportTextClipsAsMultipleFiles(to directoryURL: URL) throws {
        guard !clips.isEmpty else { return }

        for (index, clip) in orderedClips.enumerated() where clip.hasStringPasteboardType {
            let fileURL = directoryURL.appendingPathComponent("\(index + 1).txt")
            try clip.text.write(to: fileURL, atomically: true, encoding: .utf8)
        }
    }

    private func exportSeparator() -> String {
        let defaults = UserDefaults.standard
        let storedTag = defaults.integer(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        let normalizedTag = CMNormalizedLegacyExportSeparatorTag(storedTag)
        if normalizedTag != storedTag {
            defaults.set(normalizedTag, forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        }

        switch normalizedTag {
        case 0:
            return ""
        case 1:
            return "\n"
        case 2:
            return "\r\n"
        case 3:
            return "\r"
        case 4:
            return "\t"
        case 5:
            return " "
        default:
            return "\n"
        }
    }

    private func trim() {
        let defaults = UserDefaults.standard
        let storedLimit = defaults.integer(forKey: CMPrefMaxHistorySizeKey)
        let limit = CMNormalizedLegacyMaxHistorySize(storedLimit)
        if limit != storedLimit {
            defaults.set(limit, forKey: CMPrefMaxHistorySizeKey)
        }
        if clips.count > limit {
            clips = Array(orderedClips.prefix(limit))
        }
    }

    private func loadJSONClips(from url: URL) -> [ClipItem]? {
        guard let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode([ClipItem].self, from: data) else {
            return nil
        }
        return decoded
    }

    private func shouldPreferJSONStore() -> Bool {
        guard FileManager.default.fileExists(atPath: jsonFileURL.path) else { return false }
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return true }
        guard loadJSONClips(from: fileURL) == nil,
              let jsonDate = modificationDate(for: jsonFileURL),
              let dataDate = modificationDate(for: fileURL) else {
            return false
        }
        return jsonDate > dataDate
    }

    private func modificationDate(for url: URL) -> Date? {
        (try? FileManager.default.attributesOfItem(atPath: url.path)[.modificationDate]) as? Date
    }

    private func markUnsavedChanges() {
        persistenceRevision &+= 1
        hasUnsavedChanges = true
    }

    private func makePersistenceSnapshot() -> PersistenceSnapshot {
        let oldCount = clips.count
        trim()
        if clips.count != oldCount {
            markUnsavedChanges()
        }
        let identity = currentPersistenceIdentity
#if DEBUG || TESTING
        var snapshot = PersistenceSnapshot(identity: identity, clips: clips, orderedClips: orderedClips)
        snapshot.beforeWrite = debugBeforePersistenceWriteForTesting
#else
        let snapshot = PersistenceSnapshot(identity: identity, clips: clips, orderedClips: orderedClips)
#endif
        return snapshot
    }

    private var currentPersistenceIdentity: PersistenceIdentity {
        let directory = supportDirectory
        return PersistenceIdentity(
            revision: persistenceRevision,
            archiveURL: directory.appendingPathComponent("clips.data"),
            jsonURL: directory.appendingPathComponent("clips.json")
        )
    }

    private static func writePersistenceSnapshot(_ snapshot: PersistenceSnapshot) -> Bool {
        let started = ProcessInfo.processInfo.systemUptime
        CMTraceMenuPaste("history.persist.begin")
        let saved: Bool = autoreleasepool {
#if DEBUG || TESTING
            snapshot.beforeWrite?()
#endif
            do {
                let jsonData = try JSONEncoder().encode(snapshot.clips)
                let archivedClips = snapshot.orderedClips.map { ArchivedClip(clip: $0) }
                let archiveData = try NSKeyedArchiver.archivedData(withRootObject: archivedClips, requiringSecureCoding: false)
                try archiveData.write(to: snapshot.identity.archiveURL, options: .atomic)
                // The legacy archive remains authoritative, matching the existing save contract.
                try? jsonData.write(to: snapshot.identity.jsonURL, options: .atomic)
                return true
            } catch {
                NSLog("Could not save clipboard history: \(error.localizedDescription)")
                return false
            }
        }
        CMTraceMenuPaste(String(format: "history.persist.end elapsedMs=%.1f saved=%@",
                               (ProcessInfo.processInfo.systemUptime - started) * 1000,
                               saved ? "true" : "false"))
        return saved
    }

    private func loadLegacyClips() -> [ClipItem]? {
        guard let data = try? Data(contentsOf: fileURL) else { return nil }

        do {
            let unarchiver = try NSKeyedUnarchiver(forReadingFrom: data)
            unarchiver.requiresSecureCoding = false
            unarchiver.setClass(LegacyArchivedClip.self, forClassName: "Clip")
            unarchiver.setClass(LegacyArchivedClip.self, forClassName: "ClipMenu.Clip")
            defer { unarchiver.finishDecoding() }

            let decodedRoot = unarchiver.decodeObject(forKey: NSKeyedArchiveRootObjectKey)
            if let legacyClips = decodedRoot as? [LegacyArchivedClip] {
                return legacyClips.map(\.clipItem)
            }

            if let legacyClips = decodedRoot as? NSArray {
                return legacyClips.compactMap { ($0 as? LegacyArchivedClip)?.clipItem }
            }

            if let legacySet = decodedRoot as? Set<LegacyArchivedClip> {
                return legacySet
                    .map(\.clipItem)
                    .sorted { $0.createdAt > $1.createdAt }
            }

            if let legacySet = decodedRoot as? NSSet {
                return legacySet
                    .compactMap { ($0 as? LegacyArchivedClip)?.clipItem }
                    .sorted { $0.createdAt > $1.createdAt }
            }
        } catch {
            NSLog("ClipMenu failed to migrate legacy clips.data: \(error.localizedDescription)")
        }

        return nil
    }

#if TESTING
    func debugLegacyLoadReportForTesting() -> [String: Any] {
        let originalClips = clips
        let originalUnsavedChanges = hasUnsavedChanges
        let originalData = try? Data(contentsOf: fileURL)
        let originalJSONData = try? Data(contentsOf: jsonFileURL)
        let fileManager = FileManager.default
        defer {
            clips = originalClips
            hasUnsavedChanges = originalUnsavedChanges
            if let originalData {
                try? originalData.write(to: fileURL, options: .atomic)
            } else {
                try? fileManager.removeItem(at: fileURL)
            }
            if let originalJSONData {
                try? originalJSONData.write(to: jsonFileURL, options: .atomic)
            } else {
                try? fileManager.removeItem(at: jsonFileURL)
            }
        }

        do {
            try fileManager.createDirectory(at: supportDirectory, withIntermediateDirectories: true)
            try? fileManager.removeItem(at: jsonFileURL)
            let data = try DebugLegacyArchiveClip.archivedData(for: [
                DebugLegacyArchiveClip(
                    types: [NSPasteboard.PasteboardType.string.rawValue],
                    createdDate: Date(timeIntervalSince1970: 100),
                    lastUsedDate: Date(timeIntervalSince1970: 300),
                    stringValue: "First legacy",
                    rtfData: nil,
                    pdfData: nil,
                    filenames: nil,
                    urls: nil,
                    imageData: nil
                ),
                DebugLegacyArchiveClip(
                    types: [NSPasteboard.PasteboardType.pdf.rawValue],
                    createdDate: Date(timeIntervalSince1970: 200),
                    lastUsedDate: Date(timeIntervalSince1970: 200),
                    stringValue: "",
                    rtfData: nil,
                    pdfData: Data("pdf".utf8),
                    filenames: nil,
                    urls: nil,
                    imageData: nil
                )
            ])
            try data.write(to: fileURL, options: .atomic)
            load()

            let actualState: [String: Any] = [
                "texts": clips.map(\.text),
                "types": clips.map(\.types),
                "hasUnsavedChanges": hasUnsavedChanges,
                "jsonSidecarExists": fileManager.fileExists(atPath: jsonFileURL.path),
                "legacyArchiveExists": fileManager.fileExists(atPath: fileURL.path)
            ]
            let expectedState: [String: Any] = [
                "texts": ["First legacy", ""],
                "types": [
                    [NSPasteboard.PasteboardType.string.rawValue],
                    [NSPasteboard.PasteboardType.pdf.rawValue]
                ],
                "hasUnsavedChanges": false,
                "jsonSidecarExists": true,
                "legacyArchiveExists": true
            ]
            return [
                "state": actualState,
                "expectedState": expectedState,
                "matchesExpected": (actualState as NSDictionary).isEqual(to: expectedState)
            ]
        } catch {
            return [
                "error": error.localizedDescription,
                "matchesExpected": false
            ]
        }
    }
#endif
}
